lena 6: Temas de la Especialidad Penal
En muchos casos los hechos no pueden ser explicados, analizados o evaluados en su ver
dadera esencia sino a través de su reconstrucción o recreación experimental en condicio
nes de control. En la búsqueda de la verdad, los criminalistas han de recurrir muy frecuen
temente a este principio para poder comprobar la veracidad de las hipótesis planteadas,
verificar informaciones aportadas por testigos y principalmente para obtener toda la in
formación posible de las evidencias físicas que requieran un tratamiento especial.
En un caso específico, ante la localización de un cadáver dentro de un vehículo cuyos cau
chos delanteros presentaban orificios producidos por proyectiles disparados por arma de
fuego, y ante la evidencia que indicaba que esos cauchos habían sido rodados un largo
trecho luego de haber sido perforados, se solicitó un análisis exhaustivo de los mismos
para determinar qué distancia habían recorrido en esas condiciones. Una vez confirmado
por la empresa productora de dichos cauchos que la misma no realiza ni registra este tipo
de estudios por cuanto no diseña sus productos para ser rodados en tales circunstancias,
hubo entonces que plantearse la reconstrucción de este tipo de situación en similares
condiciones a las que existían para el momento del hecho.
En esa oportunidady tomando las precauciones del caso, se procedió a efectuarle dispa
ros a un par de neumáticos con las mismas características, colocados en el vehículo ob
jeto de estudio y mientras éste era desplazado por su ruta original, obteniéndose nuevos
elementos comparativos, denominados estándar de comparación, con los cuales, una vez
hechas las interpolaciones correspondientes, se logró determinar el lugar exacto donde
se iniciaron los hechos, permitiendo la ubicación de testigosy localizando nuevas eviden
cias físicas de gran valor para el esclarecimiento del caso.
d) La probabilidad: Podríamos decir, que es el arte de juzgar sobre la mayor o menor ad
misibilidad de ciertas hipótesis en base a los datos que se tienen. Este principio persigue
adaptarse lo más posible a la realidad de cómo fueron los hechos. El experto en crim i
nalística, puede inferir por el número de características observadas durante la compara
ción de las muestras colectadas la probabilidad de las mismas correspondan entre sí. Por
ejemplo; dos proyectiles hayan sido disparados por la misma arma al analizar los campos
de estrías.
e) Principio de certeza: Estudia e identifica cuantitativamente, cualitativamente y compa
rativa de los agentes o indicios que fueron utilizados en el sitio del suceso para poder
adecuarlos a la realidad científica. Este principio está basado fundamentalmente en que
todo cuerpo, cosa o individuo es idéntico sólo a sí mismo y no existe otro que sea estricta
y absolutamente idéntico al anterior.
En Criminalística se pueden apreciar que entre dos materiales “A” y “B” existen una serie
de características que nos permiten afirmar la fuente común de los mismos, sin embargo,
cada uno de ellos es inevitablemente distinto del otro.
Ciertamente, si analizáramos el contenido de un recipiente desde el punto de vista desús
propiedades físicas y químicas se pudiera afirmar indubitablemente que las gotas que
lo componen y que escapan del mismo tienen las mismas características (Color, sabor,
densidad, temperatura, etc.); y sin embargo cada gota es distinta de la otra por cuanto
son diferentes en tiempo y espacio: “Una salió primero que la otra, lo que la hace más
