f) Principio de uso: Se utilizan agentes mecánicos, físicos, químicosy biológicos para poder
descubrir o encontrar las evidencias o rastros del delito.
g) Principio de producción: Estudia la morfología (forma) y estructura (composición y ca
racterísticas) de las evidencias. Es la naturaleza del agente implicado.
3 . M É T O D O S D E IN V E S T IG A C IÓ N C R IM IN A L
La investigación científica se define como la serie de pasos que conducen a la búsqueda de
conocimientos mediante la aplicación de métodos y técnicas, y para lograr esto nos basamos
en los siguientes:
a) Exploratoria: son las investigaciones que pretenden darnos una visión general de tipo
aproximativo respecto a una determinada realidad.
b) Descriptivas: su preocupación primordial radica en describír algunas características funda
mentales de conjuntos homogéneos de fenómenos, utilizando criterios sistemáticos que
permitan poner de manifiesto su estructura o comportamiento. De esta formase pueden
obtener las notas que caracterizan a la realidad estudiada.
c) Explicativas-, son aquellos trabajos donde muestra preocupación, se centra en determinar
los orígenes o las causas de un determinado conjunto de fenómenos, donde el objetivo es
conocer por que suceden ciertos hechos a través de la delimitación de las relaciones cau
sales existentes o, al menos, de las condiciones en que ellas producen. Importancia de las
técnicas de investigación criminal. El estudio de la estructura de la investigación criminal
para la Criminalística, se justifica por cuanto el crecimiento de la delincuencia es cada vez
mayor en los países del mundo.
La investigación criminal mediante la aplicación de los métodos inductivos y deductivos,
desde un inicio en el sitio del suceso, y apoyada en los métodos, técnicas e instrumentos
que proporciona la Criminalística, puede realizar estudios preliminaresy análisis sobre la
forma en que ocurrieron los hechos, es decir, el modus operandi utilizado, instrumentos
utilizados, hasta llegara la colección y suministro de las evidencias de interés criminalís-
tico, que puedan llevara la identificación del o los autores.
á) Documentoscopia: es el estudio que se realiza en forma integral del documento en cues
tión, con el objeto de hallaren él las respuestas apropiadas a los interrogantes planteados
en los puntos de pericia mediante métodos, procedimientos y técnicas adecuadas. Es el
examen total y pormenorizado del documento, abarcando tanto las detecciones de adul
teraciones y falsificaciones que pueden ser de orden químico o físico, como el examen
comparativo para determinar la identidad escritural.
El campo de acción de la documentoscopia es muy amplio, comprende el estudio de tex
tos manuscritos, mecanografiados, billetes bancarios o de lotería, tarjetas de crédito, car
nets de identificación, etc.
Para su estudio los documentos se dividen en indubitados y dubitados:
