Tema 6: Temas de la Especialidad Penal
Se consideran indubitados aquellos cuyo origen no suscitan duda alguna con respecto
a su autenticidad.
Son documentos dubitados los que se someten a la apreciación y examen del perito,
porque se duda de su autenticidad.
e) La medicina forense.- también denominada medicina legal, jurisprudencia médica o medi
cina judicial, es la especialidad médica que engloba toda actividad relacionada con el po
der judicial. Estudia los aspectos médicos derivados de la práctica diaria de los tribunales
de justicia, donde actúan como peritos. El médico especialista en el área recibe el nombre
de médico legista o forense.
La medicina legal es la especialidad médica que aplica todos los conocimientos de la me
dicina para el auxilio a jueces y tribunales de la administración de justicia; es decir, es el
vínculo que une al derechoy a la medicina.
La medicina legal es el conjunto de conocimientos médicos y biológicos necesarios para
la resolución de problemas que plantea el Derecho. Además, proporciona esos conoci
mientos para el asesoramiento, perfeccionamiento y evolución de las leyes y tiene un
profundo compromiso con valores ético-deontológicos, básicos del ejercicio profesional.
También es el conocimiento de leyes necesarias para el quehacer cotidiano médico y se
vincula estrechamente con el Derecho Médico.
f) Balística: ciencia que estudia el movimiento de los cuerpos proyectados a través del espa
cio. La balística tiene que ver en general con proyectiles disparados por cañones o armas
ligeras, pero también puede examinar el vuelo libre de las bombas o de los cohetes.
El movimiento de un proyectil desde el momento del disparo hasta su impacto en el
blanco se divide en tres fases distintas: balística interior, que estudia el m ovimiento del
proyectil mientras se encuentra dentro del cañón; balística exterior, que considera el mo
vimiento del proyectil desde el momento en que abandona el cañón hasta que alcanza el
blanco, y balística terminal, que analiza el efecto del proyectil sobre el blanco.
La identificación de un armase basa en primer lugar en la coincidencia de las lesiones de
clase, comunes, en principio, a todas las armas de la misma marcay modelo, y fundamen
talmente en la correspondencia, en forma y ubicación de las microlesiones específicas o
individualizantes.
g) Hematología y Serología-, especialidades médicas relacionadas con el estudio de la sangre
y con los tejidos formadores de sangre. A los especialistas en esta rama de la medicina se
les conoce como hematólogos.
Estudian, diagnostican y tratan desórdenes de la sangre, como la leucemia, la anemia y
la hemofilia, así como enfermedades de los órganos que producen sangre, incluyendo los
ganglios linfáticos, la médula óseay el bazo.
h) Dactiloscopia: ha sido el método principalmente utilizado durante las últimas décadas para
la Identificación de personas no solo con fines civiles pero también policiales.
El estudio comparativo de las impresiones digitales (aquellas tomadas de forma volun
taria, por personal y con material idóneo, en el departamento de policía o registro civil) y
