4. ESCENA DEL CRIMEN
La escena del crimen o lugar del hecho, es aquella porción de espacio donde se material izo el acto
suscepti ble de revelarse por vestigios objetivamente constatables, es la fuente por excelencia de
los indicios perseguibles inmediatamente capaces de posibilitar el esclarecimiento del hecho.
Se entiende como lugar de los hechos “el sitio donde se cometió un hecho que puede ser delito" (Mon-
tiel, 19 92, p. 97).
Entendido como el sitio donde se debe comprobar la comisión de conductas punibles, pro
ducto de un presunto homicidio, suicidio, explosión, hurto, violación, o de cualquiera de los
delitos tipificados en el Código Penal (López Calvo, Gómez Silva zoo, p. 1).
Desde nuestro punto de vista el sitio del suceso, lugar de los hechos o escena del delito, es el
lugar donde se ha cometido un hecho delictivo que es objeto de investigación.
Importancia de la escena del crimen: Por la importancia en la investigación criminal y la cri
minalística, el estudio del manejo del lugar de los hechos es fuente básica de información y
fundamento legal para la recolección de pruebas. Desde un primer momento, el investigador
o autoridad competente debe actuar con ética, profesionalismo y conforme a la ley; aportar
siempre las pruebas en forma legítima para evitar nulidades posteriores y tener presente que
la protección del sitio del suceso es esencial para evitar que otras circunstancias: contamina
ción, pérdida inadecuada, manipulación de los elementos materiales de prueba allí encontra
dos factores que incidirán permanentemente en el desarrollo positivo o negativo de la investi
gación. (López Calvo, 2000, p. 11).
Tipos de escenas de crimen: A continuación, se exponen una serie de clasificaciones de sitios
del suceso, en los siguientes términos:
a. De acuerdo a sus características:
i. Típicos: Sitio en donde los indicios se encuentran en la misma área.
Lugar de los hechos (primario): es el sitio o espacio donde se ha producido un
hecho que puede ser delito y donde podemos encontrar evidencias. Se conoce
también como la escena del crimen, escena del delito, lugar del suceso, sitio del
suceso, etc.
ii. Atípicos: Los indicios se encuentran en lugares diferentes con respecto al lugar del
hecho.
Lugar de hallazgo (secundario): donde se van encontrar los indicios y/o eviden
cias (cuerpo del delito, cadáver, armas, restos biológicos, etc.) del delito cometi
do en otro lugar.
Lugar de enlace (terciario): donde se pueden encontrar evidencias relacionados
al hecho investigado, dejados por el autor o víctima con motivo de desplaza
miento dinámico o movimiento
