5 . P E R IC IA S F O R E N S E S
1. Medicina forense
La Medicina Forense es conocida también como, Medicina Legal, jurisprudencia Médica, Me
dicina judicial y Medicina de los Tribunales. Consiste en la aplicación de los conocimientos
médicos a los problemas judiciales, trata aquellos aspectos de importancia médico legal para
facilitar una correcta administración de justicia.
Alcance:
A. Según su objeto de estudio:
1. En personas: Practica exámenes médicos forenses, entre ellos, ectoscopía, patología,
gineco obstétrico y citología; determinación de la edad biológica, determinación de
secuelas, entre otros; asimismo interviene en reconstrucciones, inspecciones y otras
diligencias que la autoridad competente determine.
2. En cadáveres: Participa en el levantamiento de cadáveres, estudios necrópsicos mé
dico-forenses y efectúa apreciación médico forense criminalístico en la escena, así
como exhumaciones (data de la muertey causa de la misma).
3. En muestras: Realiza estudios en partes de cuerpos, osamentas, órganos, tejidos y do
cumentos médicos, para determinaciones de anatomía patológica, estudios citológi-
cos, rehabilitación de tejidos, análisis forenses de homologación y pronunciamientos
médicos en diversos aspectos forenses.
B. Según el campo jurídico
1. En lo civil. Efectúa estudios en relación con la determinación de la edad biológica,
pronunciamiento sobre incapacidad, etc.
2. En lo penal. Se realizan informes periciales evaluando y apreciando lesiones, necrop
sias, determinando mecanismosy causas de la muerte. Emite pronunciamientos médi
co-forenses y participa en diligencias judiciales como reconstrucciones, exhumaciones
e inspecciones criminalísticas.
3. En lo laboral: Emite pronunciamientos sobre accidentes de trabajo, enfermedades
ocupacionales, seguridad e higiene industrial, entre otros.
C. Según el área de estudio
i. En el campo médico: distingue las siguientes áreas de estudio: Anatomía patoló
gica o Patología forense, Medicina clínica forense o Medicina forense propiamente
dicha, Sexología forense, Obstetricia forense, Análisis de restos óseos, jurisprudencia
o deontología médica.
