2. En el campo criminalístico: La medicina forense brinda sus conocimientos en la de
tección y evaluación de los indicios y evidencias de valor médico que deja el delin
cuente, como son las lesionesy las secreciones.
2. Áreas periciales
A. Psiquiatría forense: Rama de la Medicina Forense que se encarga del estudio del estado
mental de una persona y su relación con el delito. Es decir, estudia los fenómenos psicológicos,
psicopatológicos o psiquiátricos y establece la probable relación con un acto supuestamente
delictivo. Orienta a la determinación del grado de capacidad civil o de capacidad penal de la
persona incriminada.
Auxilia al Derecho en dos aspectos fundamentales:
En sus aplicaciones teóricas y doctrinarias, cuando el operador de justicia necesita de los
conocimientos de Psiquiatría Forense al enfrentarse a situaciones en donde la aplicación
de una norma relaciona directamente con la Psiquiatría.
En la función pericial; al cuantificar, calificar, determinar y cronometrar los fenómenos
psiquiátricos y su relación con el delito.
B. Balística forense: Es aquella ciencia que analiza las armas de fuego empleadas en los crí
menes. Suele abarcar el estudio y análisis de los proyectiles y de los impactos determinando
el calibre del arma disparada; también se preocupa de determinar la correspondencia entre
proyectiles o vainas (cascos o casquillos) halladas en el sitio del suceso con algún arma halla
da en poder de un sospechoso o en el lugar mismo del hecho delictivo; asimismo, verifica la
presencia de residuos de pólvora sobre el blanco, con el objeto de obtener una aproximación
de la distancia a la que fue realizado el disparo.
La primera evidencia de uso de la ciencia forense aplicada a la balística fue aplicada en Ingla
terra en el año 1835 cuando las únicas pruebas de identificación de un asesinato fueron las
marcas en el proyectil encontrado dentro del cuerpo de la víctima: Cuando se confrontó la
evidencia con el sospechoso, éste confesó.
El primer juez que tomó en cuenta las pruebas forenses que mostraban los estudios balísticos,
ocurrió en 1902, cuando se pretendía demostrar que un arma podía ser asignada a la rela
ción posible de pertenencia de un sospechoso de posible asesinato. El experto del caso, Oliver
Wendell F-lolmes, había leído algo sobre identificación balísticas, y por aquel entonces ya se
empezó a estudiar el proyectil mediante el empleo de una lente.
C Grafotecnia: La Grafotecnia es parte de la ciencia Criminalística que tiene por objeto veri
ficar la autenticidad o falsedad del documento impugnado e identificar al autor del mismo.
La Grafotecnia como ciencia se vale del conjunto sistematizado de principios, reglas arte, para
elim inar los factores de duda y llegar a la verdad como cualquier conocimiento científico; la
cual contribuye a esclarecery complementar las investigaciones.
Tipos de análisis grafotécnicos:
Autoría de textos manuscritos.
Autenticidad o falsedad de firmas.
