Áreas de estudio de la grafotecnia:
Se agrupa en 3 áreas fundamentales, estas son:
Análisis de firm asy manuscritos.
Análisis de documentos.
Análisis de moneda nacional y extranjera.
D. Dactiloscopia: Es el procedimiento técnico que tiene por objeto el estudio de las impresio
nes dactilares como medio de identificación personal, no obstante, posee limitaciones que en
su momento se estudiaran, sin que por ello pierda la importancia en la labor investigativa. La
dactiloscopia sobre la cual vamos a fija r nuestro interés nos resuelve casos importantes como:
a) Identificación de las personas que maliciosamente quieren ocultar su verdadera identi
dad.
b) Identificación de cadáveres hallados sin ningún documento o datos que los identifique
plenamente.
c) Cuando una persona al ser reseñada no puede suministrar sus datos identificativos,
ejemplo: un sordo mudo, un analfabeto, un trastornado mental, un extranjero no hispa-
noparlantey que como los anteriores carece de documentos que lo identifiquen.
d) Descubre el autor agente o sujeto activo de un hecho punible, sin conocerle ni disponerle
de él, mediante el estudio y cotejo de sus impresiones dactilares halladas en el lugar don
de se cometió el hecho.
En la superficie anterior de la tercera falange o falangeta las crestas papilares adoptan siste
mas morfológicos determinados, formando dibujos muy variados y complicados, pero fáciles
de ser agrupados y diferenciados para ser debidamente clasificados. Es pues, esta tercera fa
lange o falangeta la que imprime el dactilograma. Esta región es llamada del dactilograma.
Por lo tanto, esta es la base de la Dactiloscopia.
