Principios que rige la dactiloscopia:
La dactiloscopia se basa en tres principios fundamentales:
Perennidad: Las huellas dactilares comienzan a formarse a partir de la sexta semana de
gestación, alcanzando su completo desarrollo en la semana 21 y acompañaran al indivi
duo hasta su muerte y posterior putrefacción.
Inm utabilidad: Los dibujos formados por las crestas de los pulpejos de persona determi
nada no varía en sus características. Según el profesor Montiel Sosa, aun si el individuo
desgasta a propósito estas crestas con el fin de evadir la acción de la justicia, estas se
regeneran aproximadamente en 15 días, formando un dibujo exactamente el original.
Diversidad: dado que los dibujos que forman las crestas son caprichosos y que existe un
elevado número de patrones, el dactilograma es individual y personalísimo, tanto que a
la fecha no se conoce literatura sobre dos personas con huellas dactilares exactamente
iguales.
E.Toxicología: Ciencia que estudia las sustancias químicasy los agentes físicos en cuanto son
capaces de producir alteraciones patológicas a los seres vivos, a la par que estudia los meca
nismos de producción de tales alteraciones y los medios para contrarrestarlas, así como los
procedimientos para detectar, identificar y determinar tales agentes y valorar su grado de to
xicidad.
Tóxico: Sustancia que puede producir algún efecto nocivo sobre un ser vivo, alterando sus
equilibrios vitales.
Aunque también las sustancias que son constituyentes de nuestro organismo pueden ser tó
xicas a concentraciones superiores a las fisiológicas, solemos referirnos a los tóxicos comoxe-
nobióticos o compuestos extraños que proceden del exterior.
Cualquier sustancia, ya sea endógena o exógena (xenobiótico) puede actuar como tóxico.
Todo depende de la condición del sujeto, dosis, ambiente, etc (Paracelso, sigloxvT: “Todo de
pende de la dosis”).
Veneno: Ese mismo agente cuando su empleo es intencionado.
Otras especialidades de la toxicología:
Toxicología forense: Aspectos médico-legales del uso de los tóxicos dañinos en el hombre o
animales.
Toxicología clínica: Enfermedades causadas poro relacionadas con sustancias tóxicas.
Toxicología Ambiental: Impacto que los contaminantes químicos del medio ambiente cau
san en los organismos vivos.
Ecotoxicología: Un área de la anterior que trata específicamente del impacto causado por los
tóxicos sobre la dinámica de poblaciones en un ecosistema determinado.
Toxicología alimentaria: Estudia la naturaleza, las fuentes y la formación de sustancias tóxi
cas en los alimentos. Varias áreas de estudio: tóxicos endógenos, tóxicos exógenos, bebidas
alcohólicas, alergias alimentarias.
