Tema 6: Temas de la Especialidad Penal
F. Antropología forense: Disciplina de la Medicina Forense que aplica los conocimientos de la
Anatomía humana, Antropología física, Biología, Patología y otras áreas necesarias, a fin de
realizar estudios óseos, con el fin de realizar las siguientes determinaciones:
Determinación de la biografía biológica del individuo, que comprende: (sexo, edad, talla,
tronco racial, patologías).
Determinación de la data de la muerte.
Concluyendo su estudio con metodología complementaría para la identificación que incluye:
Superposición de imágenes (cotejo cráneo-foto, cotejo radiografía de cráneo-foto, cotejo
video-foto).
Reconstrucción facial 2 D (gráfica) o 3D (plástica).
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1112 of 1506 --

1. PRINCIPIOS ¥ GARANTÍAS PROCESALES - TÍTULO PRELIMINAR DEL CÓDIGO
PROCESAL PENAL DE 2004.
Los principiosy garantías procesales se encuentran previstas en el Título Preliminardel Código
Procesal Penal, promulgado por Decreto Legislativo N.° 95 7- Su Importancia es tal que todo el
cuerpo procesal penal debe encontrarse en armonía con el título preliminar, por lo que ante
alguna duda o discrepancia para la aplicación de la norma, se debe recurrir a una interpreta
ción sistemática junto al título preliminar.
A continuación, efectuaremos una transcripción de cada artículo que integra el título prelim i
nar, para seguidamente analizar la norma que contiene:
ARTÍCULO I.- JUSTICIA PENAL
1. La justicia penal es gratuita, salvo el pago de las costas procesales establecidas conforme
a este Código. Se imparte con imparcialidad por los órganos jurisdiccionales competentes
y en un plazo razonable.
2. Toda persona tiene derecho a un juicio previo, oral, público y contradictorio, desarrollado
conforme a las normas de este Código.
3. Las partes intervendrán en el proceso con iguales posibilidades de ejercer las facultades y
derechos previstos en la Constitución y en este Código. Los jueces preservarán el principio
de igualdad procesal, debiendo allanar todos los obstáculos que impidan o dificulten su
vigencia.
4. Las resoluciones son recurribles, en los casos y en el modo previsto por la ley. Las senten
cias o autos que ponen fin a la instancia son susceptibles de recurso de apelación.
5. El Estado garantiza la indemnización por los errores judiciales.
COMENTARIO
Este artículo enumera los grandes principiosy garantías del proceso penal: imparcialidad, juez
legal, plazo razonable, juicio previo, oral, público y contradictorio, legalidad procesal, igualdad
procesal, y doble grado de jurisdicción. Además, enfatiza el principio de gratuidad de la justi
cia, a la taxatividad del recurso y obligatoriedad de su ejercicio cuando se trata de sentencias
y autos equivalentes, para finalmente referirse a la indemnización por errores judiciales. En
mérito a ello, explicaremos de manera muy sencilla cada uno de estos puntos.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1113 of 1506 --

Tema 7: Especialidad Procesal Penal
La gratuidad e imparcialidad de la justicia penal.
La gratuidad, este artículo asegura el acceso a la justicia sin costo para las partes procesales. La
gratuidad de la justicia penal está referida al no pago de aranceles y tasas judiciales, como si
sucede en el ámbito extra penal, ya sea civil, laboral, contencioso administrativo, entre otros.
Esto permite a los justiciables acceder a un sistema de justicia, donde se ventilen sus preten
siones sin efectuar pago alguno.
No debe confundirse esta gratuidad, con el servicio de recaudación de cada institución ope
rador de justicia, así, por ejemplo, es compresible el cobro por expedición de copias simples o
certificadas ante la autoridad policial, Ministerio Público y/o Poder Judicial, regulados porsus
respectivos T.U.PA. (texto único de procedimientos administrativos).
La imparcialidad, “aplicada a la caracterización de la tarea del juez, describe su función como
la de aquel que, no siendo parte en el litigio, debe decidir sin interés personal alguno; es decir,
sin perjuicio respecto de los litigantes o de la materia que juzga204”.
De allí que debe ser entendida como una exigencia hacia el juzgador que deberá ser resuelta a
través de la inhibición o a través de la recusación dependiendo el supuesto de hecho, ello aún
frente a sospecha de parcialidad.
El plazo razonable.
Queda claro que las causas penales deben ser resueltas en un lapso adecuado, sin que dilacio
nes indebidas afecten a las partes procesales.
Si bien el plazo razonable aplica para todos los ámbitos de administración de justicia, sin em
bargo, en el proceso penal cobra un valor especialísimo, pues en juego se encuentra la libertad
personal de un ser humano. De allí que el proceso debe efectuarse en un térm ino prudente,
sin dilaciones indebidas.
El referido plazo razonable, debe respetarse desde las diligencias preliminares, es más, debe
tenerse en cuenta durante la detención en flagrancia, pues el plazo de 48 horas es solamente
el máximo; es decir, la correcta interpretación al plazo de detención en flagrancia no es que
el ciudadano permanecerá 48 horas privado de su libertad, por el contrario, ese constituye el
plazo máximo, ya que solo se encontrará detenido durante el tiempo estrictamente necesario
para la realización de las investigaciones205.
Al respecto el Tribunal Constitucional afirma:
204 Casado Pérez, José. En Salas Arenas, Jorge Luis. Código Procesal Penal Comentado. Tomo I. Lima. Caceta Jurídica,
p. 19.
205 Literal f. Inciso 24. Artículo 2° de la Constitución Política del Perú, (modificación constitucional del 04/05/2017)
f. Nadie puede ser detenido sino por mandamiento escrito y motivado del juez o por las autoridades poli
ciales en caso de flagrante delito. La detención no durará más del tiempo estrictamente necesario para la
realización de las investigaciones y, en todo caso, el detenido debe ser puesto a disposición del juzgado
correspondiente, dentro del plazo máximo de cuarentay ocho horas o en el término de la distancia.
Estos plazos no se aplican a los casos de terrorismo, espionaje, tráfico ilícito de drogasy a los delitos cometidos
por organizaciones criminales. En tales casos, las autoridades policiales pueden efectuar la detención
preventiva de los presuntos implicados por un término no mayor de quince días naturales. Deben dar cuenta
al Ministerio Público y al juez, quien puede asumir jurisdicción antes de vencido dicho término".
