■. M W M i '' ha iniciado una persecución penal en su contra. Ahora bien, conviene precisar que el: momento
inicial puede coincidir con la detención policial o con otra medida restrictiva de derechos, pero
que tal supuesto no constituye requisito indispensable para habilitar el inicio del cómputo del
