sujeto de una persecución penal
En relación a la finalización del cómputo del plazo, este Tribunal Constitucional, en reiterada jurisprudencia,
ha establecido que el momento final del cómputo del plazo razonable del proceso penal opera en el momento
eg que el órgano jurisdiccional expide la decisión definitiva que resuelve la situación jurídica de la persona.
Precedente vinculante STC. N.° 00295-2012-PHC/TC-Lima.
Tutela jurisdiccional efectiva.
Su reconocimiento se contempla en el inciso 3 del artículo 139o de nuestra Constitución Polí
tica, que supone en su vertiente subjetiva “(...) un derecho a favor de toda persona para: i) un
derecho a favor de toda persona de acceder de manera directa o a través de representante,
ante los órganos judiciales; ¡i) de ejercersin ninguna interferencia los recursos y medios de de
fensa que franquea la ley; ¡i¡) de obtener una decisión razonablemente fundada en derecho; y,
finalmente, ¡v) de exigir la plena ejecución de la resolución de fondo obtenida."206
Básicamente, esel derechode todos los ciudadanos de recurriral órgano jurisdiccional en bús
queda de tutelar sus derechos. Es decir, el individuo ejerce esta potestad cuando recurre al
Estado para solucionar un conflicto relevante para el derecho penal; si esto es así, desde que
el ciudadano presenta denuncia por algún delito ante la Policía Nacional del Perú o Ministerio
Público, ya constituye el ejercicio de este derecho, ya que la pretensión final es que el Poder
Judicial emita resolución resolviendo tal controversia.
La oral idad.
La oral idad “(...) constituye un principio fundamental que rige el ordenamiento procesal penal
y que, al entraren vigencia, posibilita que se concreten otros principios fundamentales, como
la inmediación, contradicción, publicidady concentración. Es decir, si el juicio es oral, las par
tes tienen derecho a ser oídas, por lo que deben acudir al juzgado a sustentar verbal mente su
posición (inmediación); en dicha audiencia deben exponer sus argumentos y desvirtuar los
de la parte contraria (contradicción) y al ser la exposición verbal, cualquier ciudadano puede
acceder al contenido de la audiencia ingresando a ella (publicidad). En tal sentido, la oralldad
no es un mero instrumento que facilita la inmediación, contradicción y publicidad, sino que
estos hacen depender su eficacia de un proceso Iluminado por aquella.207
Así pues, este principio significa que el juez o tribunal que dicte la sentencia en el proceso
penal, tiene que condenaro absolvertomando como base los hechos y pruebas que se hayan
practicado ante él en forma oral.
Pero ¿porque es tan necesaria la oralidad en el proceso penal? Consideramos que uno de los
principales fundamentos, es la inmediación que trae consigo la oralidad, ya que el juzgado
percibe de manera directa, a través de todos sus sentidos, la prueba actuada.
206 Exp. N.° 03386-2009-PHC/TC, Fj. Sexto.
207 Seminario Sayán, Gustavo. Manual del Código Procesal Penal. Gaceta jurídica, p. 11.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1115 of 1506 --

T em a 7: Especialidad Procesal Penal
Publicidad del inicio.
Tiene sustento constitucional en el inciso 4 del artículo 139o de la carta magna, que señala: “Los
procesos judiciales por responsabilidad de funcionarios públicos, y por los delitos cometidos
por medio de la prensa y los que se refieren a derechos fundamentales garantizados por la
Constitución, son siempre públicos”.
Consideramos que el sustento de esta norma es encargar de alguna manera a la colectividad
el control jurisdiccional, y así legitimar la administración de justicia. De allí que Salas Beteta,
sustenta que "con la publicidad del juicio se asegura la transparencia de los actos judiciales y
de las decisiones judiciales correspondientes, puesto que estarán sometidas a un control po
pular. La publicidad tiende a asegurar la defensa en su sentido más amplio. Los juicios deben
ser esencialmente públicos porque no puede existir credibilidad en la justicia si el trám ite en
los expedientes se realiza a puerta cerrada”208.
Inmediación y contradicción.
La inmediación está referida a la percepción directa del juzgador de la actuación probatoria, es
decir, bajo este principio se obliga a que el desarrollo del proceso se realice en presencia del juez,
quien debe internalizar la prueba a través de los sentidos, por lo que es obvio que debe ver, oír
en tiempo real al órgano de prueba y la posición de cada sujeto procesal con su defensa técnica.
No puede pasar desapercibido el contexto actual (pandemia covidi9) que ha obligado a im-
plementar el uso de tecnologías de la información en el desarrollo del proceso penal, puesto
que el Consejo Ejecutivo del Poder Judicial ha autorizado el uso de estas herramientas para las
diversas audiencias. La pregunta es, ¿se respeta la inmediación de la prueba como uno de los
principios que erige el modelo procesal?
Al respecto el Tribunal Constitucional, ya tuvo oportunidad de em itir pronunciamiento, inclu
so mucho antes de avizorar el inicio de una pandemiay el paulatino reemplazo de la presen-
cialidad por la virtualidad.
El sistema de videoconferencia permite la comunicación bidireccional y simultanea de la
J S K Imagen y sonido en tiempo real, sin obstaculizar la percepción sensorial que puedan tener las
| f partes de las pruebas, admitiendo la Interacción visual y auditiva. Por ende, este mecanismo
19 H H H T tecnológico no puede ser rechazado por el hecho de que literalmente "no se encuentre presente
J H H f l físicamente" una persona, pues dicho sistema tiene el efecto de adecuar la audiencia de tal
manera que puede considerarse al procesado presente activamente. En ese sentido, el Tribunal
considera que su utilización no es incompatible con el principio de inmediación que informa el
proceso penal. (...)" STCN.0 0002738-2014-PHC/TC-lca.
La contradicción, otorga a la defensa técnica la posibilidad de refutar no solo la teoría acusa
dora del Ministerio Público, sino que en definitiva en un respeto al derecho de defensa, pude
contradecir la tesis asumida por el órgano jurisdiccional, de allí el sustento de los distintos
medios impugnatorios de acuerdo a la relevancia o nivel de decisión de la judicatura.
Si decimos que por principio de contradicción, la defensa tiene derecho a refutar absoluta
mente todo (no se confunda con entorpecer la investigación, puesto que toda defensa se fun
208 Salas Beteta, julio. En Salas Arenas, jorge Luis. Idem, p. 21.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 111 i

-- 1116 of 1506 --

UBILEX
da en los códigos de ética de la función, sobre la probidad y buena fe de los abogados). Por
tanto, no sería de recibo admitiractos de investigación sin conocimiento de la defensa técnica,
puesto que se atentaría directamente contra el derecho de contradecir.
Resulta claro que este principio coloca a todas las personas de manera homogénea ante la
ley, sin distingo alguno,y abarca todas las etapas del proceso, desde el inicio de las diligencias
preliminares, preparatoria, intermedia, juicio oral, impugnación.
Empero, para comprender los alcances del principio de manera específica consideramos que
deben ser analizados en un caso en concreto. Si nos ubicamos en un juicio oral, identifica
mos que los sujetos procesales básicos, están representados por la parte acusadora y la parte
acusada, esto es, el Representante del Ministerio Público y el Abogado de la defensa técnica-,
entonces la igualdad procesal aplica de manera específica para ambas partes, no puede existir
distingos en la actuación de cada uno.
Ahora bien, ¿es admisible algún trato diferenciado, o el principio es de estricto cumplimiento?
Al respecto, el Tribunal Constitucional sustenta que este principio “no supone necesariamente
un tratam iento homogéneo pues es constitucionalmente licito el trato diferenciado cuando
este se encuentra justificado, precisándose que existirá una discriminación cuando para su
puestos iguales se hayan previstos consecuencias jurídicas distintas, o cuando se haya reali
zado un trato semejante a situaciones desiguales y siempre que, para cualquiera de los dos
casos, se carezca de justificación” (STC 0007-2003-AI/TC; fundam entólo.).
Impugnación.
Recurso impugnatorio comprende diversas figuras procesales, como reposición, apelación,
casación y queja (artículo 413 del código procesal penal).
La impugnación representa uno de los alcances de la contradicción (refuta la posición del ór
gano jurisdiccional),y además del derecho de defensa en sí. Se fundamenta en el derecho a la
revisión de las decisiones judicialesy de la pluralidad de instancias.
Indemnización.
Finalmente, el artículo en comento se manifiesta sobre la indemnización, la cual, se encuentra
regulada en el inciso 7 del artículo 139° de la Constitución que la categoriza como principio de
la función jurisdiccional. Así pues, para entender el citado artículo de la Constitución debemos
remitirnos al literal c) del artículo 4 4 1o del Código Procesal Penal que señala como requisito de
la demanda de revisión, que la demanda contenga expresamente señalado el monto por in
demnización en caso de probarse el error judicial, tal como refiere el inciso 3 del artículo 4 4 4 °
del citado cuerpo normativo.
ARTICULO II.- PRESUNCION DEINOCENCIA
1. Toda persona imputada de la comisión de un hecho punible es considerada inocente, y
debe ser tratada como tal, mientras no se demuestre lo contrario y se haya declarado su
responsabilidad mediante sentencia firme debidamente motivada. Para estos efectos, se
requiere de una suficiente actividad probatoria de cargo, obtenida y actuada con las debi
das garantías procesales.
En caso de duda sobre la responsabilidad penal debe resolverse a favor del imputado.
BALOTARIO DESARROLLADO PARA LOS EXAMENES ESCRITOS DE SELECCION
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1117 of 1506 --

Tema 7: Especialidad Procesal Penal
2. Hasta antes de la sentencia firme, ningún funcionario o autoridad pública puede presentar
a una persona como culpable o brindar información en tal sentido.
COMENTARIO
Principio reconocido internacionalmente, en diversos instrumentos tales como i)Declaración
Universal de Derechos Humanos209, 2) Pacto Internacional de Derechos Civiles y políticos,
aprobado por la Asamblea General de Organización de las Naciones Unidas210, 3) Estatuto de
la Corte Penal Internacional211, 4) Convenio Europeo para la protección de los Derechos Hu
manos y de las libertad fundamentales, adoptado por los Estados miembros del Consejo de
Europa en Roma212, 5) Carta Africa na de Derechos Humanos y de los Pueblos213, 6) Declaración
Americana sobre Derechosy Deberes del Hombre214, 7) Pacto de San jóse de Costa Rica215.
La presunción de inocencia se puede definir como el derecho que comprende un trato, en
todas sus acepciones, igualitario al de una persona ¡nocente. Es decir, es el derecho que exige
que una persona sometida a una investigación (imputado, procesado, acusado), sea tratado
como un ser inocente, mientras que no exista sentencia firme que lo declare culpable.
La Constitución Política del Perú., en el literal e) del numeral 23, artículo señala que toda per
sona es considerada inocente mientras no se haya declarado judicial su responsabilidad.
No cabe duda, que la presunción de inocencia, descansa en el derecho constitucional de la
dignidad de la persona humana, por lo que todo investigado, procesado, inculpado, imputado,
acusado, es verdaderamente inocente, mientras no se haya demostrado su culpabilidad en un
proceso judicial previsto de todas las garantías constitucionales216.
209 Artículo 11.1. Toda persona acusada de delito tiene derecho a que se presuma su inocencia mientras no
se pruebe su culpabilidad, conforme a la ley y en juicio público en el que se le hayan asegurado todas las
garantías necesarias para su defensa.
210 Artículo 14.2. Toda persona acusada de un delito tiene derecho a que se presuma su inocencia mientras no se
pruebe su culpabilidad conforme a ley.
211 Artículo 66, parte VI. 1. Se presumirá que toda persona es inocente mientras no se pruebe su culpabilidad ante
la Corte de conformidad con el Derecho aplicable. 2. Incumbirá al fiscal probar la culpabilidad del acusado. 3.
Para dictar sentencia condenatoria, la Corte deberá estar convencida de la culpabilidad del acusado más allá
de toda duda razonable.
212 Artículo 6. Toda persona acusada de una infracción se presume inocente hasta que se culpabilidad haya sido
legalmente declarada.
213 Artículo 7.1. Todo individuo tiene derecho a que sea visto su caso, lo cual implica (...) el derecho a ser
considerado inocente hasta que un tribunal competente demuestre su culpabilidad.
214 Artículo XXVI. Se presume que todo acusado es inocente, hasta que se pruebe que es culpable.
215 Artículo 8.2. Toda persona inculpada tiene derecho a que se presuma su inocencia mientras no se establezca
legalmente su culpabilidad.
216 Haciendo un paréntesis, en la actividad profesional, en algún momento he podido observar alguna disposición
fiscal de archivo, que señala que de la investigación preliminar no se verifica siquiera presunción de que el
denunciado haya sido la persona autora del delito. Sin embargo, en derecho penal, la única presunción legal
admitida, es la de inocencia, por lo que admitir dicha formula fiscal aseveraría la existencia de presunción de
culpabilidad.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1118 of 1506 --

UBILEX
La presunción de inocencia, abarca desde la dimensión extraprocesal, de allí que se debe tra
tar a todo individuo como no responsable o no autor de un delito. En definitiva, abarca todo
el ámbito del proceso, desde el inicio de las diligencias preliminares, etapa de investigación
preparatoria, etapa intermediay juicio oral.
Sobre ello, el Tribunal Constitucional ha establecido que:
© u(.„) puede concluirse que el derecho a la presunción de inocencia se configura como una re-
gla de tratamiento del imputado y como una regla de juicio, Sobre la extensión de este derecho, \
¡L . conviene tener presente que el Tribunal Europeo ha precisado que "no se limita a una simple
■ garantía procesal en materia penal. Su alcance es más amplio y exige que ningún representante
■ del Estado o de la autoridad pública declare que una persona es culpable de una infracción
“ antes de que su culpabilidad haya sido establecida [en forma definitiva] por un tribunal" (Caso
Lizaso Azconobieta c. España, sentencia del 2 8 de junio de 2 0 1 1 )". (...) Como regla de juicio, la
presunción de inocencia impone que para declarar la responsabilidad, penal de una persona se "requiere de
una suficiente actividad probatoria de cargo, obtenida y actuada con las debidas garantías procesales. En caso
de duda sobre la responsabilidad penal debe resolverse a favor deíimputado" (inciso 1 del artículo IIdelTítulo:
Preliminar del Código Procesal Penal). Esta perspectiva de la presunción de inocencia determina que no puede
trasladarse la carga de la prueba a quien precisamente soporta la imputación, pues eso significaría que lo que
: se sanciona no es lo que está probado en el proceso o procedimiento, sino lo que el imputado, en este caso, no:
ha podido probar como descargo en defensa de su inocencia, Cfr. STC 02192-2004-AA/TC.
(2 ) Por dicha razón, en la STC 088 1 1 -2 0 0 5 -PHC/TC el Tribunal estableció que el derecho a la presunción de
inocencia reconocido en el artículo 2 o, inciso 2 4 , literal e) deéa Constitución,: obliga "al órgano jurisdiccional
a realizar una actividad, probatoria suficiente que permita desvirtuar el estado de inocente del que: goza todo:
imputado, pues este no puede ser condenado solo sobre la base de simples presunciones (..)". STC 00156-
2012-HC/TC, fj. 43 a 45.
Por su parte, Caro Coria, sustenta que “ya de inicio debe advertirse que el derecho a la presun
ción de inocencia no sólo es una garantía que impone la consideración del imputado como
inocente, sino que su efecto más importante radica en que exige que la persona que viene
afrontando un procedimiento criminal sea tratada, en los diversos sectores del ordenamiento
jurídico y la vida social, como una persona de la que aún no se ha comprobado responsabili
dad penal alguna.”217
ARTÍCULO 111.- INTERDICCIÓN DE LA PERSECUCIÓN PENAL MÚLTIPLE
Nadie podrá ser procesado, ni sancionado m ás de una vez por un mismo hecho, siempre que
se trate del mism o sujeto y fundamento. Este principio rige para las sanciones penales y adm i
nistrativas. El derecho penal tiene preeminencia sobre el derecho administrativo.
La excepción a esta norma es la revisión por la Corte Suprema de la sentencia condenatoria
expedida en alguno de los casos en que la acción está indicada taxativamente como proce
dente en este Código.
