-- 1119 of 1506 --

Tema 7: Especialidad Procesal Penal
sos distintos o, si se quiere, que se inicien dos procesos con el mismo objeto. Con ello se impide, por un lado,
la dualidad de procedimientos, así como el inicio de un nuevo proceso cuando concurra la referida triple
Identidad entre ambos procesos2l8”.
Para la aplicación del principio nebisin Ídem, debe existir una triple identidad, que en términos
del TC, esta referido a: el primer de ellos “(...) la de identidad de sujeto, lo que significa que la persona
física a la cual se le persigue tenga que ser necesariamente la misma”219. El segundo “la identidad objetiva
o identidad de hechos, no es más que la estricta identidad entre los hechos que sirvieron de fundamento
para la apertura tanto en una como en otra investigación, es decir, se debe de tra ta r de la misma conduc
ta material, sin que se tenga en cuenta para ello su calificación legal"220. Finalmente, el tercero, “debe
verificarse la concurrencia del elemento de identidad de la causa de persecución, el cual se presenta en el
caso de autos, por cuanto el fundamento de los ilícitos supuestamente realizados por el demandado está
referido, por igual, a bienes jurídicos f . . ) ”221.
En términos prácticos, debe hacerse un análisis comparativo entre ambos casos, para verificar
que se trata del mismo sujeto investigado, referido al mismo hecho o conducta, sobre idéntico
fundamento.
En similar sentido, la Corte Suprema de la República precisa que “no resulta correcto que un mis
mo hecho sea investigado paralelamente por distintas Fiscalías, más aun si una de ellas derivo la inves
tigación por razones territoriales, puesto que con ello se vulnera el derecho al debido proceso, al que se
deben circunscribir las actuaciones judiciales y fiscales222”.
De lo expuesto queda claro, que de investigarse a una persona por un hecho por el cual ya fue in
vestigado o se encuentra siendo investigado, atentaría gravemente contra el principio ne bis in Ídem.
En palabras de Caro Coria, esta garantía comporta la imposibilidad de que una persona sea
perseguida dos veces o más en razón de una misma imputación criminal. En contra del enten
dimiento que tradicionalmente se ha dado al ne bis in ídem, equiparándolo con el principio
de la cosa juzgada (ne bis in ídem m aterial), el contenido de esta garantía ha demostrado poseer
mayor amplitud, pues no sólo comporta la prohibición de una persecución subsiguiente, es
decir, cuando la imputación ya ha sido materia de un pronunciamiento final del órgano ju
risdiccional correspondiente, sino que también se encuentra referido a la prohibición de una
persecución paralela, es decir, que la persona sea perseguida al mismo tiempo en dos proce
sos diferentes (ne bis in ídem procesal) 223
ARTÍCULO IV.- TITULAR DE LA ACCIÓN PENAL
