UBILEX
2. El Ministerio Público está obligado a actuar con objetividad, indagando por intermedio de
la Policía Nacional del Perú los hechos constitutivos del delito, que determinen y acrediten
la responsabilidad o inocencia del imputado. Con esta finalidad, conducejurídicam ente los
actos de investigación que realiza la Policía Nacional del Perú.
3. La investigación que practica la Policía Nacional del Perú, con la conducción jurídica del
Ministerio Público, no tiene carácter jurisdiccional. Cuando fuera indispensable una deci
sión de esta naturaleza, la requerirá del órgano jurisdiccional competente, motivando debi
damente su petición.
4. La Policía Nacional del Perú tiene a su cargo la investigación preliminar del delito y, en tal
sentido, realiza las diligencias que, por su naturaleza, correspondan a dicha competencia,
de conformidad con sus leyes y reglamentos.
COMENTARIO
El contenido del Código Procesal Penal debe interpretarse bajo las directrices del título preli-
m inary del inciso 1 del artículo en comento se desprende una de las reglas más importantes.
Si bien se define al Ministerio Público como el titu lar del ejercicio de la acción penal, empero
ello no abarca todo el contenido del Código Penal.
Recordemos que el Código Penal peruano ha disgregado las faltas, de los delitos, y el título
prelim inarya aclaraqueel Ministerio Público esel titu lar de laacción penal en los delitos, por
lo que lo separa en definitiva de las faltas, por ello no sería posible que un fiscal penal se avo
que a la investigación de alguna falta, ya que es de acción privada (por el mismo interesado).
Ahora bien, la objetividad es exigible al Ministerio Público, más no una imparcialidad que está
reservada para el órgano jurisdiccional. El sustento radica en que en algún momento del pro
ceso (generalmente en el acto de form alizary continuar con la investigación preparatoria) el
fiscal decidirá investigar a una persona, por ende, asume una teoría basada en sospecha (de
acuerdo a los grados definidos), entonces no es imparcial ya que en representación de los de
rechos de las víctimas y del propio Estado, requiere que se sancione los actos del investigado
que son considerados delitos. La objetividad básicamente está referida a que toda decisión,
participación e intervención del fiscal debe basarse en actos de investigación, mas no en la
creencia o grado subjetivo del representante del Ministerio Público; este principio implica la
observancia de la garantía del respeto a los derechos del imputado, preservando el principio
de presunción de inocencia,evitando emitirdecisiones (disposicionesfiscales, requerimientos
fiscales) o programar diligencias fiscales sobre la base de algún tipo de presión social a fin de
obtener resultados o percepción arbitraria de culpabilidad del imputado por parte del fiscal.
A través de los cuatro numerales, se reconoce la participación conjunta del binomio Ministe
rio Público - Policía Nacional del Perú. Ello resulta necesario pues de acuerdo a la normativa
constitucional, la PN.P también cumple funciones de investigación, ya que el artículo 166° del
texto constitucional señala: “La Policía Nacional tiene por finalidad fundam ental garantizar, mante
ner y restablecer el orden interno. Presta protección y ayuda a las personasy a la comunidad. Garantiza
el cumplimiento de las leyes y la seguridad del patrim onio público y del privado. Previene, investiga y
combate la delincuencia. Vigila y controla las fronteras”. Y posteriormente, el Código Procesal Pe
nal en el artículo 67o señala: “7. La Policía Nacional del Perú en cumplimiento de sus funciones debe,
inclusive por propia iniciativa, tom ar conocimiento de los delitos y comunicar inmediatamente al Fiscal,
