debiendo realizar, los diligencias de investigación urgentes o inaplazables, que formarán parte de las di
ligencias preliminares y de la carpeta fiscal, para im pedir sus consecuencias, individualizar a sus autores
y partícipes, así como reunir y asegurar los elementos de prueba que puedan servir para la aplicación
de la ley penal. S im ilar función desarrollará tratándose de delitos dependientes de instancia privada o
sujetas a ejercicio privado de la acción penal."
Conforme podemos observar de la norma en comentario, se resalta que el Ministerio Público
es el encargado de “conducir jurídicamente" la investigación, así también precisa que la Policía
es el encargado de la investigación preliminar, ello conforme a la modificación practicada por
la Ley N° 32130 (Pub. io .10.2024), se hace énfasis a una participación más institucionalizada
de la Policía, al haberse emitido normas para el fortalecimiento de la investigación del delito
como función de la PNP y agilizar los procesos penales.
En ese contexto, el Ministerio Público aprueba la Resolución N °2 2 4 6 -2 0 2 4 -MP-FN, por la cual,
se aprueba el Reglamento denominado “Actuación fiscal en la investigación del delito", a través
del cual, se establecen lineamientos sobre la investigación fiscal, otorgando al fiscal la potes
tad de calificary dirigir la estrategia de investigación, en coordinación y coadyuvancia de la
Policía Nacional del Perú.
Ww ARTÍCULO COMPETENCIA JUDICIAL
1. Corresponde al órgano jurisdiccional la dirección de la etapa intermedia y, especialmente,
del juzgamiento, a sí como expedir las sentencias y demás resoluciones previstas en la Ley.
2. Nadie puede ser sometido a pena o medida de seguridad sino por resolución del órgano
jurisdiccional determinado por la Ley.
COMENTARIO
Este artículo debe ser entendido en concordancia con el segundo párrafo del numeral 3 del ar
tículo 139o de la constitución, el cual consagra entre otras garantías procesales la del juez legal
-denominado por un sector de la doctrina “juez natural", bajo el enunciado “ninguna persona
puede ser desviada de la jurisdicción predeterminada por la ley”.
Así pues,“El poderotorgado porel pueblo para im partir justicia supone una de las principales
finalidades del Estado. Asimismo, garantizar la protección de los derechos constitucionales
y procesales que corresponden a cada ciudadano constituye una responsabilidad que debe
ser prevista dentro de un proceso; por ello, el Poder Judicial, como órgano conferido para el
ejercicio de esta potestad, procura proveer los instrumentos jurídicos que aseguren decisiones
judiciales imparciales, a través de los operadores del Derecho.”224
Así, el Código Procesal Penal “(...) entrega la investigación ai fiscal, en consecuencia, el juez en
esta etapa solo decide sobre los requerimientos que los sujetos procesales le pueden hacer,
pero no investiga. Será luego, en la etapa intermedia o juicio oral, cuando el juez asuma la
dirección de la causa. (...). En esta etapa, el juez tiene como función principal dirigir la audien
cia preliminar, a estos efectos se prepara este espacio de discusión, donde principalmente se
224 Ibid., p. 67.
