UBILEX
decidirá sobre el mérito de la acusación o el requerimiento de sobreseimiento, es decir, si es
viable o no abrir el juicio oral. Además, puede decidir devolver la acusación por errores for
males, resolver excepciones y otros medios técnicos de defensa, pronunciarse sobre medidas
de coerción, algún criterio de oportunidad, decidir la adm isibilidad o no de pruebas para su
actuación en el juicio oral, decidirsobre convenciones probatorias y prueba anticipada. Al ter
minar esta etapa,y si decide que se inicie el juicio oral, emite el auto de enjuiciamiento. Si esto
ocurre, pasamos a la etapa más importante del proceso penal, como es el juicio oral; ello es
así por cuanto en esta se decidirá sobre la responsabilidad del imputado, pues, luego del acto
oral, donde se actuarán las pruebas, el juez decidirá acerca desuvalorysi es que está probado
el hecho que se le imputa, lo que puede repercutir en una condena.’’225
En suma, el papel del juez en la etapa de juzgamiento es sumamente importante, siendo el
director de aquella, impidiendo que la causa se desvíe, manteniendo el orden y respeto en la
sala de audiencias; más importante aún essufunción decisora plasmadaen unasentencia,sin
desmerecer su labor en la emisión de autos y decretos.
Siendo el juzgamiento la fase estelar del proceso penal, a través del cual, el Juez se desenvuel
ve con imparcialidad, garantizando diversos principios que rigen dicha etapa, como la orali-
dad, la inmediación, publicidad, contradictorio y principio acusatorio.
íS ARTÍCULO VI.- LEGALIDAD DE LAS MEDIDAS LIMITATIVAS DE DERECHOS
Las medidas que limitan derechos fundamentales, salvo las excepciones previstas en la Cons
titución, sólo podrán dictarse por la autoridad judicial, en el modo, forma y con las garantías
previstas por la Ley. Se impondrán mediante resolución motivada, a instancia de la parte pro
cesal legitimada. La orden judicial debe sustentarse en suficientes elementos de convicción,
en atención a la naturaleza y finalidad de la medida y al derecho fundamental objeto de limita
ción, a sí como respetar el principio de proporcionalidad.
COMENTARIO
En el artículo IV antes descrito, se ha señalado de manera general que el Ministerio Público es
el titu lar de la acción penal, sin embargo, solo está facultado a investigar, mas no a restringir
algún derecho fundamental, ya que el único ente autorizado a restringir algún derecho es el
órgano jurisdiccional, siempre bajo una decisión motivada. La única excepción es la participa
ción de la RN.R en caso de flagrancia que puede proceder con una detención (restricción del
derecho fundamental libertad), pero siempre en legalidad, para lo cual el Ministerio Público
se encuentra facultado a verificarlo.
Del referido artículo es posible reconocer ciertas reglas, como:
i) Las medidas restrictivas de derechos solo podrán ser dictadas por autoridad judicial.
Como decíamos, solo el órgano jurisdiccional tiene la posibilidad de restringir derechos
fundamentales.
225 Ibid., p. 68.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1123 of 1506 --

Tema 7: Especialidad Procesal Penal
En caso de flagrancia delictiva la RN.R tiene posibilidad de proceder a restringir la libertad
del individuo, pero esto se sujeta a un control inmediato posterior del Fiscal Provincial
Penal a quien se le da cuenta de la detención de la persona.
Ahora bien, es posible también restringir el derecho a la inviolabilidad del domicilio, o
derecho de propiedad, en caso de urgenciay peligro en la demora, por parte de la RN.R o
del M.R empero, siempre se requerirá una confirmatoria judicial.
ii) Las medidas restrictivas de derecho se dictarán en la forma, modo y con las garantías pre
vistas por ley. íntimamente relacionado al principio de legalidad, lo que obliga al órgano
jurisdiccional a dictar las restricciones pertinentes de la manera prevista en la norma y
sobre todo en respeto irrestricto a las garantías previstas.
iii) Solo se dictarán mediante resolución motivada. En consonancia con el ordenamiento
constitucional referido a la obligación de fundamentar u exteriorizar las razones por las
que el juzgador decide de tal o cual manera.
iv) Solo se dictarán a solicitud del legitimado. La propia norma ha previsto quien es el legiti
mado para ciertas medidas, por ejemplo, no sería admisible de ninguna manera adm itir
a trám ite una petición de restricción de la libertad (detención preliminar, prisión preven
tiva, impedimento de salida entre otros) de un tercero ajeno al Ministerio Público, pues
solo dicho sujeto es el legitimado a pedirla.
v) La resolución judicial debe sustentarse en elementos de convicción. Queda claro que la re
solución judicial motivada, debe fundarse en los elementos de convicción adjuntados, lo
que trae como lógica consecuencia el deber del Ministerio Público, como legitimado para
adjuntar a sus requerimientos los elementos de convicción que sustentan su petitorio.
vi) Respeto irrestricto al principio de proporcionalidad. El fundamento 41 de la Sentencia
emitida por el Tribunal Constitucional en el Expediente N° 045-2004-PI/TC, en el análisis
del Principio de Proporcionalidad deben aplicarse los subprlncipios de idoneidad, nece-
sidady proporcionalidad en sentido estricto o ponderación de manera sucesiva.
Primero, se ha de examinar la idoneidad de la intervención: si bien se establece que la prisión
preventiva afecta el derecho fundamental de la libertad personal de los imputados, esta re
sulta adecuada para la obtención de un fin legítimo que es el aseguramiento del resultado de
un proceso seguido por la comisión de delitos graves y pluriofensivos, por tanto la interven
ción en la igualdad-el trato diferenciado- es idónea, constitucional y arreglada a ley.
Segundo, se debe analizar el subprincipio de necesidad: bajo este test ha de analizarse si
existen medios alternativos al optado por el legislador que no sean gravosos o, al menos,
que lo sean en menor intensldady este análisis se efectúa con relación al objetivo del trato
diferenciado y si resulta idóneo para la consecución del objetivo del trato diferenciado.
Tercero, finalmente, en el análisis de la proporcionalidad se debe analizar la proporciona
lidad en sentido estricto: Cuanto mayor es el grado de la no satisfacción o de la afectación
de un principio, tanto mayor tiene que ser la importancia de la satisfacción del otro. Este
análisis está sentado en la necesidad que tiene el Estado dentro de su facultad persecu
torio, buscar una sanción dentro del marco de un debido proceso, y este no debe estar
interrumpido por una conducta obstruccionista por parte del imputado, quien al estar en
libertad podrían sustraerse de la acción de la justicia o entorpecer el proceso.
