Tal como indica el intitulado del artículo "legalidad de las medidas restrictivas de derecho” si
no se aplicara uno de estos principios o criterios, simplemente la medida lim itativa devendría
en ilegal.
ARTÍCULO VIL- VIGENCIA E INTERPRETACIÓN DE LA LEY PROCESAL PENAL
1. La Ley procesal penal es de aplicación inmediata, incluso al proceso en trámite, y es la que
rige al tiempo de la actuación procesal. Sin embargo, continuarán rigiéndose por la Ley
anterior, los medios impugnatorios ya interpuestos, los actos procesales con principio de
ejecución y los plazos que hubieran empezado.
2. La Ley procesal referida a derechos individuales que sea m ás favorable al imputado, expe
dida con posterioridad a la actuación procesal, se aplicará retroactivamente, incluso para
los actos ya concluidos, si fuera posible.
3. La Ley que coacte la libertad o el ejercicio de los derechos procesales de las personas, así
como la que limite un poder conferido a las partes o establezca sanciones procesales, será
interpretada restrictivamente. La interpretación extensiva y la analogía quedan prohibidas
mientras no favorezcan la libertad del imputado o el ejercicio de sus derechos.
4. En caso de duda insalvable sobre la Ley aplicable debe estarse a lo m ás favorable al reo.
COMENTARIO
Queda claro que en materia procesal rige el princípió tempus regitactum , que se traduce en la
aplicación de la ley procesal vigente al momento de los hechos; esto se encuentra relacionado
con los actos procesales y no con el hecho delictivo, evidenciándose que la ley procesal es de
aplicación inmediata, presentando tres situaciones excepcionales: a) Los medios impúgnate
nos, b) Los actos procesales con principio de ejecución ye) Los plazos que hubieran empezado.
Cuando la norma procesal hace referencia a la aplicación de la ley procesal referida a dere
chos individuales, señala su aplicación retroactiva siempre que sea favorable al imputado, de
bemos señalar que dentro de los derechos individuales se encuentran: la vida, la libertad, la
igualdad ante la ley, etc.
Un ejemplo muy frecuente es la aplicación de las normas frente a detenciones, prisión pre
ventiva, libertad dom iciliariay otros supuestos en que las nuevas normas amplíen derechos o
señalen consecuencias menos gravosas.
La norma procesal también hace referencia a la prohibición de la interpretación extensiva y
analógica de ley procesal en contra del imputado. Así pues, “Es de larga data que para el Dere
cho Penal sustantivo existe una prohibición en tal sentido, que motiva al juez quedar vedado
de extender la ley más allá de su núcleoy del objeto de protección, o crear una situación fácti-
ca no contenida en la ley a título de analogía siempre en ma\am partem. Esta disposición se re
dime en la medida que establece una regla a título de excepción. La interpretación extensiva
y la analogía en materia procesal penal se aceptan solo en cuanto “favorezcan" la libertad del
imputado o el ejercicio de sus derechos.”226
226 Ibid., p. 84.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1125 of 1506 --

Tema 7: Especialidad Procesal Penal
ARTÍCULO VIII.- LEGITIMIDAD DE LA PRUEBA
1. Todo medio de prueba será valorado sólo si ha sido obtenido e incorporado al proceso por
un procedimiento constitucionalmente legítimo.
2. Carecen de efecto legal las pruebas obtenidas, directa o indirectamente, con violación del
contenido esencial de los derechos fundamentales de la persona.
3. La inobservancia de cualquier regla de garantía constitucional establecida a favor del pro
cesado no podrá hacerse valer en su perjuicio.
COMENTARIO
Rosas Yataco, citando a Ortiz Rodríguez, señala que son pruebas legalmente producidas las
que han sido ordenadas o decretadas mediante auto proferido por autoridad competente y
que además, han sido recogidas, practicadas y aseguradas conforme a las disposiciones que
regulan, en particular, la recolección, practica y aseguramiento de la respectiva prueba. Por
tanto, es ilegal y no puede apreciarse la prueba que no fue previamente decretada, o que se re
cogió o practico sin observancia de las disposiciones legales que regulan la actividad procesal.
Tampoco pueden apreciarse pruebas ilegalmente admitidas, como cuando se admite alguna
por un medio probatorio distinto a los mencionados en la ley227.
Por su parte, el Tribunal Constitucional en la sentencia 1014-2007-PHC/TC, sustenta que con
forme al derecho a la legitimidad a la prueba se exige la constitucionalidad de la actividad
probatoria, la cual implica la proscripción de actos que violen el contenido esencial de los de
rechos fundamentales o transgresiones al orden jurídico en la obtención, recepción y valora
ción de la prueba.
ARTÍCULO IX.- DERECHO DE DEFENSA
1. Toda persona tiene derecho inviolable e irrestricto a que se le informe de sus derechos, a
que se le comunique de inmediato y detalladamente la imputación formulada en su contra,
y a ser asistida por un Abogado Defensor de su elección o, en su caso, por un abogado de
oficio, desde que es citada o detenida por la autoridad. También tiene derecho a que se le
conceda un tiempo razonable para que prepare su defensa; a ejercer su autodefensa mate
rial; a intervenir, en plena igualdad, en la actividad probatoria; y, en las condiciones previstas
por la Ley, a utilizar los medios de prueba pertinentes. El ejercicio del derecho de defensa
se extiende a todo estado y grado del procedimiento, en la forma y oportunidad que la ley
señala.
2. Nadie puede ser obligado o inducido a declarar o a reconocer culpabilidad contra sí mismo,
contra su cónyuge, o sus parientes dentro del cuarto grado de consanguinidad o segundo
de afinidad.
3. El proceso penal garantiza, también, el ejercicio de los derechos de información y de par
ticipación procesal a la persona agraviada o perjudicada por el delito. La autoridad pública
está obligada a velar por su protección y a brindarle un trato acorde con su condición.
227 Ortiz Rodríguez Alfonso, citado por Rosas Yataco, jorge. Derecho Procesal Penal Doctrina, jurisprudencia y
legislación actualizada. Ceides 2018. p. 461.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

