UBILEX
COMENTARIO
Regulado en tratados internacionales de los que el Perú es parte, así tenemos:
Artículo n ° de la Declaración Universal de los Derechos Humanos. Toda persona acusada de
delito tiene derecho a que se presuma en inocencia mientras no se pruebe su culpabilidad,
conforme a la ley y en juicio público en el que hayan asegurado todas las garantías necesarias
para su defensa.
Inciso 3 del artículo 14o del Pacto Internacional de Derechos civiles y políticos. Durante el pro
ceso, toda persona acusada de un delito tendrá derecho, en plena igualdad, a las siguientes
garantías mínimas:
a) A ser informada sin demora, en un idioma que comprensa y en forma detallada, de la
naturalezay causas de la acusación formulada contra ella;
b) A disponer del tiempo y de los medios adecuados para la preparación de su defensa y
comunicarse con un defensor de su elección;
c) A ser juzgado sin dilaciones indebidas;
d) A hallarse presente en el proceso y a defenderse personalmente o ser asistida por un de
fensor de su elección; a ser informada, si no tuviera defensor, del derecho que le asiste a
tenerlo, y,
e) A interrogar o hacer interrogar a los testigos de cargo y a obtener la comparecencia de
los testigos de descargoy que estos sean interrogados en las mismas condiciones que los
testigos de cargo;
f) A ser asistida gratuitamente por un intérprete, si no comprende o no habla el idioma em
pleado en el tribunal;
g) A no ser obligada a declarar contra su misma ni a confesarse culpable.
Artículo 8 .z de la Convención Americana de Derechos Humanos. Durante el proceso, toda per
sona tiene derecho, en plena igualdad, a las siguientes garantías mínimas:
a) Derecho del inculpado de ser asistido gratuitamente por el traductor o interprete, si no
comprende o no habla el idioma del juzgado o tribunal;
b) Comunicación previa y detallada al inculpado de la acusación formulada;
c) Concesión al inculpado del tiempo y de los medios adecuados para la preparación de su
defensa;
d) Derecho del inculpado de defenderse personalmente o de ser asistido por un defensor de
su elección y de comunicarse libre y privadamente con su defensor;
e) Derecho irrenunciable de ser asistido por un defensor proporcionado por el Estado, re
munerado o no según la legislación interna, si el inculpado no se defendiere por sí mismo
ni nombrare defensor dentro del plazo establecido por ley;
f) Derecho de la defensa de interrogar a los testigos presentes en el tribunal y de obtener la
comparecencia, como testigos o peritos, de otras personas que pueden arrojar luz sobre
los hechos;
