Tema 7: Especialidad Procesal Penal
g) Derecho a no ser obligado a declarar contra sí mismo ni a declararse culpable, y
h) Derecho de recurrir al fallo ante juez o tribunal superior.
En el marco constitucional ha sido regulado en el inciso 4 del artículo 139 el cual señala:
El principio de no ser privado del derecho de defensa en ningún esiado del proceso. Toda persona
será informada inmediatamente y por escrito de la causa o de las razones de su detención. Tiene
derecho a comunicarse personalmente con un defensor de su elección y a ser asesorada por este
desde que es citada o detenida por cualquier autoridad.
A decir de Neyra Flores, el derecho de defensa por la importancia y por el contenido que abar
ca, se constituye en •. un principio que inform atodo el ordenamiento procesal, un derecho sub
jetivo individual, de carácter público, de intervenir en el proceso penal en todo momento para
decidir acerca de una posible reacción penal, y una garantía que le asiste a todo imputado
en todos los estados del proceso, de poder ofrecer los elementos probatorios que considere
necesarios, a contradecir prueba, invocar prueba prohibida y exponer los elementos facticos y
jurídicos que permitan al Tribunal declarar su absolución228.
El Tribunal Constitucional, sobre el derecho de defensa, reseña lo siguiente:
(L) La Constitución reconoce el derecho de defensa en su artículo 139, inciso 74,;(eMmrttídídef
cual se garantiza que los justiciables, en la protección de sus derechos y obligacioftespcualm
quiera que sea su naturaleza (civil, mercantil, penal, laboral, etcétera), no queden emestadcrdm
indefensión. El contenido constitucionalmente protegido del derecho de defensa quédaiafectadm
cuando, en el seno de un proceso judicial, cualquiera de las partes resulta im pedídw p^Eaeto^
concretos de los órganos judiciales, de ejercer los medios necesarios, suficientes y eficaces p a m
defender sus derechos e intereses legítimos. Sentencias 00582-2006-PA/TC y 05175-2007-HC/TC.
í f ) El ejercicio del derecho de defensa, de especial relevancia en el proceso penal, tiene una doble dimensión:
una material, referida al derecho del imputado de ejercer su propia defensa desde el mismo instante en el que
toma conocimiento de que se le atribuye la comisión de determinado hecho delictivo: y otra formal, lo cual su
pone el derecho a una defensa técnica, esto es, al asesoramiento y patrocinio de un abogado defensor durante
todo el tiempo que dure el proceso. Ambas dimensiones del derecho de defensa forman parte del contenido
constituclonalmente protegido del derecho en referencia. En ambos casos, se garantiza el derecho a no ser
postrado a un estado de indefensión. Sentencia 02028-2004-PHC/TC.
El derecho a no quedar en estado de Indefensión se conculca cuando los titulares de los derechos e in
tereses legítimos se ven impedidos de ejercer los medios legales suficientes para su defensa. No obstante,
no cualquier imposibilidad de ejercer esos medios produce un estado de indefensión que atenta contra el
contenido constitucionalmente protegido de dicho derecho, sino que es constitucionalmente relevante cuando
se genera una indebida y arbitraria actuación del órgano que investiga o juzga al individuo. Sentencias QBBS2-
2006-Pñ/TCy 05175-2007-PHC/TC.
De lo brevemente reseñado, se advierte que el derecho de defensa es reconocido a nivel in
ternacional por diversos pactos y tratados, además es recogido por el texto constitucional y
finalmente se constituye como una de las bases del proceso penal.
El derecho de defensa debe ser respetado en todas las instancias del proceso penal, desde
que se conoce el nombre del presunto autor de los hechos, es decir, desde el inicio de las d ili
gencias preliminares que representan sospecha inicial que funda el inicio de la investigación.
