Todo acto de investigación, diligencia, o actividad procesal (cualquiera que fuese) será nula si
se ha transgredido de alguna manera el derecho de defensa.
En la práctica profesional, es común conocer que una persona se presenta a la autoridad poli
cial a form ular una denuncia por un hecho delictuoso en la que identificar al presunto autor,
y de manera automática la respuesta de la entidad policial es tom ar la declaración de la de
