constituye sospecha inicial de delito y no un elemento de convicción propiamente dicho que
pueda ser valorado por ejemplo en una audiencia de prisión preventiva, puesto que al conocer
el nombre del presunto autor se tenía que asegurar su derecho de defensa por lo m ejor con la
participación de la defensa pública.
ARTÍCULO X.- PREVALENC1A DE LAS NORMAS DE ESTE TÍTULO
Las normas que integran el presente Título prevalecen sobre cualquier otra disposición de este
Código. Serán utilizadas como fundamento de interpretación.
COMENTARIO
Como corolario del título preliminar tenemos el últim o artículo que es imperativo pues orde
na que todo el contenido procesal penal debe ser interpretado de acuerdo a lo desarrollado
en el título preliminar.
Si bien el código procesal penal a lo largo desús títulos y capítulos desarrolla por ejemplo, los
sujetos procesales, los derechos que le asiste al abogado del imputado, al imputado, empero
todo ello debe ser siempre interpretado de acuerdo al título preliminar.
2. ACCIÓN PENAL Y ACCIÓN CIVIL, OBJETO PROCESAL
Acción penal: Rosas Yataco, citando a Pérez-Cruz Martin, Agustín-Jesús y otros, indica que la
acción penal por su particular función y sus particulares aspectos se presenta a una primera
visión empírica como la actividad de un órgano del Estado encaminada a obtener una deci
sión del juez penal en relación a un hecho que constituye delitoy que se supone cometido por
alguien229.
En palabras de Oré Guardia.- “(...) la acción penal es la potestad jurídica de promover la decisión
del órgano jurisdiccional respecto a una determinada relación de Derecho penal. El ejercicio
de la acción penal domina y da carácter a todo el proceso: lo inicia y lo hace avanzar hasta su
meta (la resolución del conflicto generado por el delito). El proceso, sin el ejercicio legítimo de
la acción penal no puede surgir ni continuar."230
Así, entendemos a la acción penal como aquella potestad jurídica que se sigue contra una
persona que infringe la ley penal, esto, con la finalidad de aplicar una pena y lograr el resarci
miento de los daños ocasionados por la comisión del delito. En el caso peruano la titularidad
