Tema 7: Especialidad Procesal Penal
de la acción penal corresponde al Ministerio Público, que se concreta en la expedición de la
disposición de formalización y continuación de la investigación preparatoria-en el caso de los
delitos públicos-,y en los delitos privados al perjudicado porel delito.
Acción civil: Oré Guardia citando a Arangones señala: “La acción civil en el proceso penal supo
ne la promoción del ejercicio de la acción con el fin de amparar el interés privado consistente
en la reparación por los daños y perjuicios generados a la víctima (ilícito civil) a raíz de una
conducta que podría constituir, además, un ilícito penal”.231
Debe partirse de la idea de que la responsabilidad civil que se exige en el proceso penal no
deriva de la comisión de un hecho delictivo: el delito tiene como consecuencia una pena; el
ilícito civil, una consecuencia de esa naturaleza.
La responsabilidad civil nace porque el hecho produce el daño o porque implica un menosca
bo patrimonial de la víctima. En consecuencia, lo que interesa— o lo que debe interesar— al
actor civil es que exista un daño reparable, no que el hecho del que deriva sea delito. El Código
Procesal Penal se pronuncia en ese sentido estableciendo que el ejercicio de la acción civil de
rivada del hecho punible corresponde al Ministerio Público y, especialmente, al perjudicado
porel delito; además, estipula que si éste últim o se constituye en actor civil, cesa la legitima
ción del Ministerio Público para intervenir en el objeto civil del proceso: artículo 11o, apartado
i), del citado Código adjetivo. En tal virtud, la participación del Ministerio Público será porsus-
titución, esto es, representa un interés privado. Por ello, su intervención cesa definitivamente
cuando el actor civil se apersona al proceso.
Mientras que la acción penal procura satisfacer el interés de la sociedad (interés público) a
través de la imposición de una pena (pretensión punitiva) a quien comete un delito, la acción
civil es el derecho que asiste a la víctima (interés privado) a fin de ser indemnizada porel daño
causado porel delito (pretensión resarcitoria).
Objeto procesal: El profesor Cesar San Martín Castro enseña que “La determinación del objeto
procesal -el hecho punible imputado a una persona- es esencial: (i) delim ita los poderes del
órgano jurisdiccional en orden a la conformación de la sentencia, pues definido el objeto no
puede alterarse: congruencia y limitación del ámbito cognoscitivo y decisorio del Tribunal;
(¡i) las partes, deducidas la acusación y la defensa, no pueden alterarlas introduciendo varia
ciones esenciales— la mutación o ampliación de la pretensión— ; (iii) identifica los efectos
derivados de la cosa juzgada en relación con el nebisin ídem, que incluye la litispendencia.
Resaltan, así, las notas de:
A. Inmutabilidad. No cabe cambiarlo ni eliminarlo. Vale decir, que una vez identificado no
puede ser sustituido por otro, se trate de una sustitución objetiva (de un hecho por otro
hecho) o subjetiva (de un imputado por otro). La inmutabilidad debe subsistir hasta la con
clusión del proceso, pues debe constituiré! mismo tema de investigación y de decisión.
B. Indisponibilidad. Tanto desde el (i) punto de vista fáctico, pues el hecho comprende to
dos los actos preparatorios, accesorios, particulares y posteriores, como del (ii) jurídico,
pues el proceso considera el hecho desde todos los puntos de vista posibles.
