C. Indivisibilidad. Debe agotarse hasta su total esclarecimiento, y la sentencia ha de resol
ver sobre la totalidad e integridad del mismo, siempre que la pretensión quede sin mo
dificar. El objeto procesal no puede dividirse en parcelas— las fases procesales discurren
en un mismo objeto— . Lo que trae como consecuencia el que procedería la excepción de
cosa juzgada, entendida m bis in ídem procesal (si le proceso estuviera en trámite) o ne bis
in ídem material (si estuviese terminado).
D. Delimitación progresiva. A diferencia del proceso civil, donde con la interposición de la
demanda se tiene fijado el hecho sobre el cuál versará el proceso, el inicio de un proceso
penal es poco lo que se conoce del hecho y de su autor. Es más, la denominación “investi
gación preparatoria” es justamente para preparar el acto en el cual se fije regularmente el
objeto del proceso. El objeto del proceso penal resulta así construido, hasta quedar fijo en
la acusación.
El poderjurídico de acción es un mecanismo, constitucionalmente garantizado, de acceso
a la jurisdicción penal. Si es admitido, el efecto principal es convertir a las partes que la
promovieron en acusadoras para que puedan deducir la pretensión; el fiscal o el quere
llante deducirán la pretensión penaly lavíctima,si así lo estima procedente al convertirse
en actor civil, deducirá la pretensión civil resarcitoriá’. 232
La persecución de la acción civil en muchos casos, la condición de agraviado no solo recae en la
víctima, en otros casos, el Estado al ser el agraviado, dicha representación recae en las Procura
durías Especializadas del Estado, en caso que los intereses lesionados tengan relación con los
intereses del Estado, por ejemplo, la Procuraduría Pública Especializada en Delitos Cometidos
por Funcionarios Públicos.
3. MEDIOS TÉCNICOS DE DEFENSA
En todo proceso penal es imprescindible la existencia irrestricta de recursos que hagan posi
ble el ejercicio del derecho a la defensa, consagrado en la Constitución y los Instrumentos In
ternacionales de los Derechos Humanos. Estos recursos deben perm itir efectuar una defensa
sobre el fondo de la imputación delictiva (autodefensa) como de la adecuada consecución del
proceso (defensa técnica), es decir, en este últim o caso, adecuadas a sus requisitos formales
y procedimentales. En ese contexto, se incorpora los medios de defensa técnica, como reme
dios que permitirán llevar un proceso con todos los requisitos exigidos por él, subsanándolos
o simplemente eliminándolos. Pues, tal como lo afirma Manuel CatacoraGonzáles el ejercicio
de la acción penal, como toda institución jurídica, está sujeta a ciertas reglas, tanto para la ini
ciación como para su desarrollo durante el proceso. Por lo tanto, existen requisitos que deben
cumplirse para la iniciación, y su ausencia los convierte en obstáculos. Algunos de estos obs
táculos son insalvablesy tienen carácter absol uto, y otros que pueden superarse. Los primeros
determinan la devolución de la denuncia y se declaran con carácter previo; los otros pueden
proponerse en el curso del proceso ya comenzado.
En el Código Procesal Penal estos medios de defensa técnica se interponen una vez que el Fis
cal haya decidido continuar con la Investigación Preparatoria o al contestar la querella, tra
