tándose de delitos que requieran el ejercicio de acción privada, los mismos que se resolverán
antes de culminar la Etapa Intermedia (Art. 7.1 del Código Procesal Penal, en adelante CPP). Tal
interposición puede ser realizada por cualquiera de los sujetos procesales, incluso declarada
de oficio por el Juez (Art. 7 3 del CPP).
¿Cuáles son los medios técnicos de defensa establecidos en el Código Procesal Penal (2004)?
Los medios de defensa de conformidad con lo dispuesto por los artículos 4°, 5°y 6o del Código
Procesal Penal, son los siguientes:
Las cuestiones previas.
Las cuestiones prejudiciales.
Las excepciones.
A. Cuestión Previa: La cuestión previa es aquel medio de defensa técnica que procede cuando
se decide continuar con la Investigación Preparatoria omitiendo un requisito de procedíbiIi-
dad explícitamente previsto en la ley (Art. 4.1o del CPP). Villagaray Hurtado lo define como el
obstáculo o medio defensivo del que hace uso el imputado cuando se le inicia ‘instrucción (en el nuevo
CPP cuando el Fiscal decide continuar con la Investigación Preparatoria) sin hallarse expedita la acción
penal, por fa lta r algún elemento o requisito de procedibilldad previsto, en casos excepcionales, por el Có
digo Penal o por leyes especiales. Y los requisitos de procedibilidad, siguiendo Ciovanni Leone,
podemos definirla como todas aquellas causas que condicionan el ejercicio de la acción penal y sin
cuya presencia no es posible promoverla.
¿En qué casos procede la cuestión previa?
Este medio de defensa procede cuando:
En delitos sometidos al ejercicio privado de la acción penal, pues la denuncia del agra
viado constituye un requisito para que el Ministerio Público pueda promover la acción
penal, tal es el caso de las lesiones culposas leves, competencia desleal y delitos contra el
sistema crediticio, en este últim o lo puede promover también el INDECOPI.
En delitos de ejercicio mixto de la acción penal, cuando se requiere una autorización pre
via de la autoridad estatal, tal es el caso de los delitos Tributarios y cometidos por altos
funcionarlos; o, cuando la ley exige que una determinada autoridad emita pronuncia
miento previo, en este caso tenemos los delitos contra la ecología o los recursos naturales
y el medio ambiente, delitos financieros y los delitos contra los derechos de autory cone
xos, contra la propiedad industrial y contra el orden económico.
En delitos de ejercicio público de la acción penal, tal es el caso del delito de omisión a la
asistencia fam iliar (se exige la resolución judicial que establece la obligación, junto a la
notificación debida bajo apercibimiento de ser denunciado), delito de quiebra fraudu
lenta (se exige la declaración de quiebra o estado de liquidación) y el delito de libramien
to indebido (se exige que el agente sea Informado de la falta de pago mediante protesto
u otra forma documentada de requerimiento).
Características.- Entre las principales tenemos:
Es una institución eminentemente procesal, porque se interpone dentro de ella, advir
tiendo la falta de un requisito de procedibilidad.
