Se encuentran señaladas expresamente por ley.
Son Independientes del hecho m lsm oy no tienen que ver con latipicidad, p o rlo ta n to no
se les puede confundir con los elementos constitutivos del delito.
Tienden a impedir la iniciación y prosecución de una causa nula.
Su decisión corresponde al Juez Penal, de oficio o a petición de parte.
P ro cedim ien to :
Este medio de defensa se plantea una vez que el Fiscal haya decidido continuar con la
Investigación Preparatoria o al contestar laQuerellay se resolverán necesariamente antes
de culminar la Etapa Intermedia (Art. 7.1 del CPP), también puede deducirse en esta Eta
pa, en la oportunidad fijada por la Ley (Art. 7.2 del CPP). E incluso puede ser declarada de
oficio (Art. 7 3 del CPP).
Se plantea mediante solicitud debidamente fundamentada ante el Juez de la Investiga
ción Preparatoria que recibió la comunicación señalada en el artículo 3o, adjuntando, de
ser el caso, los elementos de convicción que correspondan (Art. 8.1 del CPP).
El Juez, previo informe del Fiscal acerca de los sujetos procesales apersonados en la causa,
notificará la admisión del medio de defensa deducido y señalará fecha para la realización
de la audiencia dentro del tercer día. La audiencia se realizará con la asistencia obliga
toria del Fiscal, que exhibirá el expediente para su examen inmediato por el Juez en ese
acto, y quienes concurran a la misma (Art. 8.2 del CPP).
Instalada la audiencia, el Juez escuchará por su orden, al abogado defensor que propuso
el medio de defensa, al Fiscal, al defensor del actor civil y defensor de la persona jurídica
según lo dispuesto en el artículo 90oy del tercero civil; quienes harán mención a los ele
mentos de convicción que consten en autos o que han acompañado en sede judicial. Si
asiste el imputado tiene derecho a intervenir en últim o térm ino (Art. 8.3 del CPP).
El Juez resolverá inmediatamente mediante auto debidamente fundamentado o, en todo
caso, en el plazo de dos días luego de celebrada la vista; excepcionalmente, para resolver
la cuestión previa deducida, podrá retener el expediente Fiscal hasta por veinticuatro ho
ras (Art. 8.4 del CPP).
Contra el auto expedido por el Juez procede recurso de apelación. Concedido el recurso
el Juez dispondrá que dentro del quinto día se agreguen a los actuados formados en sede
judicial copias certificadas pertinentes del expediente Fiscal, luego de lo cual elevará a la
Sala Penal Superior. Si vencido este plazo no se han adjuntado las copias correspondien
tes, el Juez inmediatamente elevará los actuados a la Sala, la que sin perjuicio de poner
este hecho en conocimiento del Fiscal Superior instará al Fiscal Provincial que complete
el cuaderno de apelación (Art. 9 del CPP).
En caso de haber sido planteada durante la Etapa Intermedia se resolverá conforme a lo
dispuesto en el artículo 357° (Art. 8.5 del CPP).
E fe c to s.-Si el órganojurisdiccional declara fundada la cuestión previa anulará lo actuado (Art.
4.1 in fine del CPP), empero, por ningún motivo dicha resolución constituye cosa juzgada. Así,
