Tema 7: Especialidad Procesal Penal
si el requisito om itido es satisfecho podrá reiniciarse la Investigación Preparatoria (Art. 4.2 del
CPP). Finalmente, la cuestión previa deducida a favor de uno de los imputados beneficia a los
demás, siempre que se encuentren en igual situación jurídica (Art. 8.6 del CPP).
B. C u e stió n P re ju d ic ia l. La cuestión prejudicial es aquel medio de defensa técnica que pro
cede cuando el Fiscal decide continuar con la Investigación Preparatoria, pese a que existe
pendiente una declaración en la vía extra penal vinculada al carácter delictuoso del hecho
incriminado (Art. 5.1 del CPP). Pues de lo resuelto en dicha vía dependerá la prosecución o el
sobreseimiento de la causa (Art. 5.4 del CPP).
El maestro Florencio Mixán Mass señala que constituye cuestión prejudicial de naturaleza extrapenal:
aquel hecho jurídico o acto jurídico preexistente de carácter autónomo, eventual, que resulta especial e ínti
mamente vinculado, en situación de antecedente lógico-jurídico, el acto u omisión (hecho) imputado que es
objeto del procedimiento penal en concreto; que sea capaz de generar duda sobre el carácter delictuoso del
acto, duda, que, a su vez, determina la necesidad de suspender (archivar provisionalmente) la ‘instrucción
para rem itirla a la correspondiente vía jurisdiccional o administrativa para su esclarecimiento y resolución
definitiva; solución final que al ser traída al proceso penal en suspenso servirá de valioso elemento de juicio
para que el Juez Penal pueda resolver,ya sea ordenando el archivamiento definitivo o el desarchivamientoy
continuación del mismo. Así, Pablo Sánchez Velarde refiere que lo que se va a esclarecer en la vía extra-pe-
nal es la existencia de algún elemento constitutivo del delito; sin embargo, cabe aclarar, que la cuestión
prejudicial no supone de ninguna manera resolver el fondo del asunto.
¿C a so s en q u e procede la c u estió n p r e ju d ic ia l?
Este medio de defensa procede, en los siguientes casos:
En el delito de bigamia o matrimonio ilegal, cuando es necesario recurrir a la vía civil para
determinar la validez legal del primer matrimonio.
En el delito contra el estado civil, cuando se requiere la declaración de paternidad.
En delito apropiación ilícita, cuando sea necesario establecer el derecho de propiedad o
de retener.
En el delito de usurpación, cuando sea necesario establecer el derecho de posesión.
En el delito de estafa, cuando sea necesario establecer la validez del contrato.
C a ra cte rística s.-
El procesado sin negar los hechos que se imputan, alega que esos hechos no son más que
el ejercicio de un derechoy que ha podido hacer legalmente lo que ha hecho (feci sed jure
feci), por lo que el delito desaparece desde que se reconoce la causa de justificación.
La admisión de los hechos, condicionada por la defensa de legitimidad, debe plantear un
problema de naturaleza extra- penal, siempre que no se trate de una simple interpreta
ción de la ley extra-penal cuestionada en el proceso.
Un hecho anterior distinto de la infracción,y cuya prueba puede hacerse separadamente.
La existencia de duda sobre el carácter delictuoso del hecho.
La resolución judicial extra-penal sea susceptible de incidir en la resolución de la causa
penal, en la cual fue planteada la cuestión prejudicial, determinando la configuración del
delito o su exclusión.
