UBILEX
P ro c e d im ie n to ." Es el mismo que el establecido para la cuestión previa. No obstante, para
el proceso en la vía extra-penal si la parte legitimada no lo ha promovido, se le notificará y
requerirá para que lo haga en el plazo de treinta días computados desde el momento en que
haya quedado firme la resolución suspensiva. Si vencido dicho plazo no cumpliera con hacerlo
el Fiscal Provincial en lo Civil deberá promoverlo con citación de las partes interesadas; asimis
mo, se le autoriza a éste a interveniry continuar con el proceso hastasuterminación, así como
sustituir al titu la r de la acción si éste no lo persigue, en ambos casos siempre que se trate de un
hecho punible perseguible por ejercicio público de la acción penal (Art. 5 3 del CPP).
Efectós.- Si el órgano jurisdiccional declara fundada la cuestión prejudicial se suspenderá la
Investigación Preparatoria hasta que en la otra vía recaiga resolución firme (Art. 5-2 del CPP),
caso contrario se seguirá normalmente con el desarrollo del proceso. E, igualmente, la cues
tión prejudicial deducida a favor de uno de los imputados beneficia a los demás, siempre que
se encuentren en igual situación jurídica (Art. 5.2 in fm ey art. 8.6 del CPP).
C. Las Excepciones: De acuerdo al Art. 6.1 del CPP, las excepciones que pueden deducirse son
las siguientes:
a) Naturaleza de juicio, cuando se ha dado al proceso una sustanciación distinta a la prevista
en la Ley.
b) Improcedencia de acción, cuando el hecho no constituye delito o no es justiciable penal
mente.
c) Cosa juzgada, cuando el hecho punible ha sido objeto de una resolución firme, nacional
o extranjera contra la misma persona.
d) Amnistía.
e) Prescripción, cuando por el vencimiento de los plazos señalados por el Código Penal se
haya extinguido la acción penal o el derecho de ejecución de la pena.
Así también, las excepciones tienen el mismo procedimiento previsto para la cuestión previa
y prejudicial.
a) Excepción de Naturaleza de Juicio.- Esta excepción procede cuando se ha dado al proce
so una sustanciación distinta a la prevista en la Ley (Art. 6.1 a) del CPP). Así, el tratadista
César Eugenio San Martín Castro sostiene que se trata sin duda de un remedio procesal que no
entra al fondo del asunto, solo al procedimiento a seguir. Tiene lugar cuando el delito o delitos obje
to del proceso penal se les asigna un procedimiento distinto del que por ley les corresponde. Hay que
anotar que la palabra sustanciación tiene que entenderse como sinónimo de trám ite y de acuerdo
a la m agnitud de error la regularización puede significar la anulación de determinadas diligencias
que hayan resultado desnaturalizadas.
b) Excepción de Im p ro ce d e n cia d e A cció n .- Esta excepción procede cuando el hecho no
constituye delito o no es justiciable penalmente (Art. 6.1 b) del CPP). Inicialmente ha sido
incorporada con el nomen juris de excepción de naturaleza de acción al C de PP a partir
del 15 de junio de 1981, mediante el Decreto Legislativo Nro. 126, empero, al igual que los
demás medios de defensa técnica se aplicaba a nivel jurisprudencial ya con anterioridad.
Por ello, en aquella oportunidad la Corte Suprema se vio en la necesidad de adjudicar una doble
acepción y función a la naturaleza de juicio: a) Para el caso de que la conducta denunciada no esté
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1135 of 1506 --

Tema 7: Especialidad Procesal Penal
descrita en forma expresa e inequívoca como delito en la ley penafy, b) Para el caso de que al proceso
penal se le haya dado, dentro de la misma órbita de la competencia del fuero penal, una tram itación
distinta de la que corresponda al caso concreto. La primera acepción es en realidad la excepción in
comento; por lo que, se puede afirm ar que la excepción de improcedencia de acción tiene como p rin
cipal fundamento el principio de legalidad (nullum crimen, nulla poena sine lege), es decir, si el he
cho imputado como delito está establecida en una lex previa (exclusión de la aplicación retroactiva
de las leyes penales)y en una lexscripta (exclusión de la aplicación retroactiva de las leyes penales),
que reúna las condiciones de una lex certa (exclusión de cláusulas generales), interpretada como
una lexstricta (exclusión de la extensión analógica de la ley pena!); y, los hechos no ju sticia b le s pe
nalm ente, es decir, los casos al que la propia ley penal le quita expresa y específicamente
la punibllidad, ya que, si bien es cierto, siguen siendo hechos típicos, no son justiciables
penalmente porque ostentan una causa de justificación, la concurrencia de una excusa
absolutoria o cuando falta una condición objetiva de punibilidad, en todos los casos pre
vista por leyy eliminando la antijuricidad del hecho.
Las excusas absolutorias son las previstas en el artículo 208 del Código Penal (CP), donde
se refiere que no son reprimióles los hurtos, apropiaciones, defraudaciones o daños que
se causen: Los cónyuges, los hermanos, etc. A su turno, las causas de justificación están
contempladas en el artículo 20 del CP bajo el nom enjuris de “Causas que eximen o ate
núan la responsabilidad penal", entre las cuales tenemos: las causas de inim putabilidad,
minoría de edad, legítima defensa, etc., que a decir de Fidel Rojas Vargas son permisos
legales que concede el Estado para obrar típicamente, vulnerando bienes jurídicos de
otras personas. Finalmente, las condiciones objetivas de punibilidad, a decir de Ignacio
Berdugo Gómez de la Torre, son requisitos que el legislador ha añadido en los correspon
dientes preceptos legales, pero que no pertenecen al tipo del injusto ni a la culpabilidad
se caracterizan por su formulación positiva, condicionan directamente la pena o la enti
dad de la pena, sin que deban ser abarcados por el dolo del autor. Verbigratia, el delito
de falsificación de documentos cuando exigen la condición ''perjuicio'', el delito de tráfico
ilícito de drogas cuando exige determinadas cantidades, pues de lo contrario podría tra
tarse del autoconsumo que no es penado, o el delito de contrabando cuando establece su
punibilidad cuando sobrepasen las cuatro unidades impositivas tributarias.
c) Excepción d e Cosa Ju z g a d a .- Esta excepción procede cuando el hecho punible ha sido
objeto de una resolución firme, nacional o extranjera contra la misma persona (Art. 6.1
c) del CPP). Siguiendo a Miguel Fenech debemos entender como cosa juzgada al efecto
de un proceso terminado, no de un acto procesal como es la sentencia, sólo así podemos hablar de la
procedencia del recurso de revisión. La Constitución consagra en el artículo 139o inciso 13: Son
principios y funciones de la función jurisdiccional: (...) La prohibición de revivir procesos
fenecidos con resolución ejecutoriada. La amnistía, el indulto, el sobreseimiento defini
tivo y la prescripción producen los efectos de la cosa juzgada. A su turno, el Código Penal
señala en el artículo 78 inciso 2: La acción penal se extingue por autoridad de cosa juzgada-, y, en
el artículo 90o: Nadie puede ser perseguido por segunda vez en razón de un hecho punible sobre el
cual se falló definitivamente. Finalmente, el CPP refiere en el artículo III del Título Preliminar:
Nadie puede ser procesado, ni sancionado más de una vez por un mismo hecho, siempre que se trate
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1136 of 1506 --

del mismo sujeto y fundamento. Este principio rige para las sanciones penales y administra
tivas. El derecho penal tiene preeminencia sobre el derecho administrativo.
d) Excepción de A m n is tía .- La amnistía proviene de un vocablo griego amnestia que signi
fica amnesia, pérdida de la memoria u olvido. Y ha sido conceptuada como el olvido que
la ley otorga al delito como a la pena, renunciando el Estado al lus Puniendi, generalmente
por consideraciones políticas o político-sociales. Reconocido a nivel constitucional como
una atribución exclusiva del Congreso de la República (Art. 102.6); en el CP figura como
una causa de extinción de la acción penal (Art. 78.1), explicando como consecuencia que
eNmina legalmente el hecho punible a que se refiere e implica el perpetuo silencio res
pecto a él (Art. 89).
e) Excepción de P re scrip ció n .- Esta excepción procede cuando por el vencimiento de los
plazos señalados por el Código Penal se haya extinguido la acción penal o el derecho de
la ejecución de la pena (Art. 6.1 e) del CPP). La prescripción como impedimento procesal
tiene un doble fundamento: el transcurso del tiempo y la conducta observada por el suje
to.
En la legislación encontramos dos tipos de prescripción: la ordinaria y la extraordinaria.
La primera regulada por el artículo 80o del CR que señala como plazo de prescripción igual
al máximo de la pena fijada por la ley para el delito que no será mayor de veinte años, si es
privativa de libertad; de treinta años tratándose de delitos sancionados con pena de cade
na perpetua; y, de dos años tratándose de otras penas. En los casos de delito de omisión
de asistencia familiar, el plazo de prescripción se duplica. Por lo dispuesto en el artículo
83o del CP habiéndose interrumpido el plazo por intervención del Ministerio Público o las
autoridades judiciales empieza a correr nuevamente a partir del día siguiente de efectua
da la últimadil¡gencía,dejandosin efectoel anterior. La secunda se da cuando habiéndose
interrumpido el tiempo sobrepasa en una mitad el plazo ordinario de prescripción (Art.
83o in fine). Otro tipo de prescripción extraordinaria sucede cuando el agente se encuentra
en una situación de im putabilidad restringida, en cuyo caso los plazos de prescripción se
reducen a la mitad (Art. 81 del CP); asimismo, cuando se trata de la comisión de delitos
contra el patrimonio del Estado o de organismos sostenidos por éste, se duplica el plazo
de prescripción ordinario.
Algunas reglas establecidas para la aplicación de la prescripción de la pena y la acción
penal son:
El plazo de prescripción empieza a transcurrir según el artículo 82o del CP: desde el
día en que cesó la actividad delictuosa en la tentativa; a partir del día en que se con
sumó en el delito instantáneo; desde el día en que term inó la actividad delictuosa
en el delito continuado; y, a partir del día en que cesó la permanencia en el delito
permanente.
En caso de concurso real de delitos la contabilización del plazo de prescripción se
fijará por separado o paralelamente, tratándose de concurso ideal de delitos se con
tabiliza el plazo de prescripción prevista para el delito más grave, estamos ante la
regla de absorción.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1137 of 1506 --

Tema 7: Especialidad Procesal Penal
Finalmente, tratándose de delitos sancionados con penas conjuntas debe fijarse
atendiendo al plazo que corresponda al elemento más grave integrado a la sanción,
y en caso de penas alternativas cuando se haya cumplido el plazo más largo que re
sulte de las penas susceptibles de imposición.
Cabe anotar que esta excepción es improcedente tratándose de delitos de lesa humanidad,
pues estos son imprescriptibles, igualmente cuando haya renuncia expresa por parte del
imputado (Art. 91 del CP).
Efecto s.- De declararse fundada las excepciones de Improcedencia de Acción, Cosa juz
gada, Amnistía y Prescripción el proceso será sobreseído definitivamente; en cambio, si
se declara fundada la excepción de naturaleza de juicio sólo se regularizará el proceso al
trám ite reconocido en el auto que lo resuelva (Art. 6.2 del CPP).
Asimismo, cabe señalar que la figura procesal de la Prescripción ha sido objeto de diversas
modificaciones a lo largo de los últimos tres años, entre ellas podemos apreciar:
a) Acuerdo Plenario N° 05-2023/CIJ-112, de fecha 28 de noviembre del 2023 denominado
"suspensión de la prescripción de la acción penal Ley 31751, de 25 de mayo del 2023, a
través del cual, se ha planteado la inconstitucionalidad de la mencionada ley, indicando
que, “La Ley 31751 es desproporcionada y, por consiguiente inconstitucional. Por ello, los
jueces, conforme al artículo 138, segundo párrafo, de la Constitución, no deben aplicarla:
deben preferir la norma constitucional referida a la protección de seguridad pública o ciu
dadana, al valor justicia material y a la tutela jurisdiccional-en este caso de la víctima- (ex
artículos 44y 139, numeral 3, de la Constitución). Siendo así, rige, por ser conforme a la Ley
Fundamental, lo dispuesto en el Acuerdo Plenario 3-2012/0-116 ,y en todo caso la reglaya
asumida en esa ocasión de que en la aplicación del artículo 84o del Código Penal, como
límite a la suspensión del plazo de suspensión de la acción penal es cuando se sobrepasa
en una mitad el plazo ordinario de prescripción.
Se observa entonces que mediante el mencionado Acuerdo Plenario se ha decidido declarar la
inconstitucionalidad de la referida Ley 31751, señalando que, en todo caso, rige lo establecido
en el anterior Acuerdo Plenario 3-2012/0-116, a través del cual, se establecen criterios para la
determinación y cómputo del plazo de la suspensión de la acción penal, estableciéndose en
su fundamento 11 que, “En adelante debe entenderes que la suspensión de la prescripción
en el caso del artículo 339° inciso 1, no podrá prolongarse más allá de un tiempo acumulado
equivalente al plazo ordinario de prescripción más una mitad de dicho plazo”, constituyendo
el plazo de suspensión, -en caso se verifique su concurrencia-, un factor determinante para
evaluar la extinción de la acción penal mediante la figura de la prescripción penal.
4 . C O M P E T E N C IA
Oré Guardia citando a Maier señala que: “La jurisdicción es la función pública por la cual el
Estado, a través de sus diferentes órganos reconocidos constitucionalmente, decide o da solu
ción a los conflictos sociales."233
233 ORÉ GUARDIA, Arcenlo (2016). Derecho Procesal Penal Peruano. Tomo I. Gaceta Jurídica, p. 199.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1138 of 1506 --

La competencia, en cambio, denota la potestad otorgada por ley al órgano jurisdiccional para
conocer determinados conflictos (civil, penal, laboral, militar, constitucional, etc.). De ahí que
también sea entendida -en sus fines prácticos— como el instrumento mediante el cual se
procura el ordenado reparto de las causas entre jueces para conocer asuntos en materia penal.
Resulta necesario hacer una distinción entre jurisdicción y competencia, así pues, cuando
hablamos de la jurisdicción nos referimos al poder genérico recaído en la autoridad judicial,
llámese “juez”, para administrar justicia, pero no hablamos de una cualidad irrestricta e ilim i
tada, dado que su contrapeso resulta sen la competencia; que resulta canalizar el ejercicio de
la jurisdicción a través de criterios, tales como: materia, cuantía, grado, turno o territorio; solo
por mencionar algunos por su reconocido valor doctrinario. Entonces, tras lo planteado, con
viene proponer que "todos los jueces tienen jurisdicción, pero no todos competencia”.
Así pues, la potestad jurisdiccional no funciona en forma ilimitada, sino que su ejercicio está res
tringido por la serie de requisitos que la ley impone para asegurar su control que es necesario para
la seguridad del procedimiento penal. Entre estos requisitos se destaca el que se refiere a la com
petencia, que en materia penal condiciona el poder de los órganos para ejercer la jurisdicción y
para realizar la potestad represiva, de ahí que se diga que la competencia constituye el límite de la
jurisdicción. La competencia recae en el órgano jurisdiccional que, además de haber cubierto los
requisitos para pertenecer al poder judicial, necesita obtener facultades jurisdiccionales.
C o m p e te n cia o b je tiv a
El criterio objetivo está compuesto por un conjunto de normas procesales que distribuyen
el conocimiento de los asuntos penales entre los órganos jurisdiccionales, teniendo en
cuenta la menor o mayor gravedad de la infracción penal (criterio rationae materiae) y la
calidad del presunto autor de la comisión del hecho delictivo (criterio rationae personae).
A) C riterio r a tio n a e materiae
Asigna la competencia a determinados órganos jurisdiccionales en función de la gra
vedad de la infracción penal. Así, tenemos que nuestra legislación diferencia entre
“(...) delitos y faltas, que permite identificara los juzgados de la investigación prepa
ratoria, penalesy de paz, letradosy no letrados. Un criterio diferencial adicional den
tro de este orden y circunscripto a los delitos, se establece a partir de su gravedad,
según estén o no conminados en su extremo m ínim o con pena privativa de libertad
mayor de seis años, criterio que solo rige para la etapa procesal de enjuiciamiento y
define si el juzgado Penal será colegiado o unipersonal.”234
B) C riterio r a tio n a e personae
Este criterio “se define a partir de la cualidad del sujeto pasivo de la imputación pe
nal. Atiende al cargo o la función que ejerce el sujeto sospechoso.”235 Por ello, en el
proceso respectivo se aplican normas especiales que competen a órganos jurisdic
cionales distintos a los que, normalmente, hubieran dirigido el proceso.
Así pues, “(...) el procesamiento se reserva a una jerarquía superior de órganos juris
diccionales. Según los arts. 4 5 0 °.3 y 4 5 4 °-4 y 3o CPP, los altos funcionarios públicos
