Tema 7: Especialidad Procesal Penal
que designa el art. 99 de la Constitución son procesados por la Corte Suprema de
justicia, así como los jueces superiores, fiscales superiores, miembros de Tribunal
Supremo M ilitar y procuradores públicos del Estado; mientras que los jueces espe
cializados, jueces de paz letrado, fiscales provincialesy fiscales adjuntos provinciales
son procesados por las Cortes Superiores de justicia respectivas.”236
— C o m p e te n cia Fu n cio nal
Este criterio competencial resulta de la división del trabajo que en busca de garantizar la
imparcialidad del juzgador, así como la labor especializada y, en consecuencia, eficiente
de los funcionarios estatales (juez penal y fiscal) que participan en el proceso penal.
Este criterio precisa que las causas penales serán analizadas por determinados órganos
jurisdiccionales conforme a la jerarquía preexistente, concordante con el artículo 16 del
Código Procesal Penal de 2004, siendo la siguiente:
La S a la Penal de la Corte S u p re m a : se encarga de resolver recursos de casaciones,
quejas en denegatoria de apelación, cuestiones de competencia, extradiciones y los
que la ley señala.
Las s a la s p e n a le s d e las cortes su p erio res: atienden las apelaciones de resoluciones
emitidas por los jueces de Investigación preparatoria, las recusaciones, entre otros.
Los ju z g a d o s p e n ale s, constituidos en órganos colegiados o unipersonales, según la
competencia que le asigna la ley: resuelven los casos en primera instancia, sus inci
dentes y lo que la ley le confiere.
Los ju z g a d o s de la in vestig a ció n p rep arato ria: conducen la etapa de investigación
preparatoria, la etapa intermedia y la ejecución de sentencias.
Los ju z g a d o s d e p a z letrado s, con las excepciones previstas por la ley para los juzga
dos de paz: resuelven los procesos por faltas.
Sin embargo, tal filtro no es estático, sino que la legitimidad puede variar, según la etapa
del proceso, guardando relación con el principio de preclusión de las etapas procesales.”237
— C o m p e te n cia territo rial:
Está referida al lugar donde el proceso debe desarrollarse, como hemos visto, los órganos ju
risdiccionales, además de presentar una división vertical o jerárquica, han seguido un criterio
de división horizontal. La finalidad de esta división es que el poder jurisdiccional que se distri
buye por todo el territorio del país garantice el acceso a la justicia a todo ciudadano.
Valderrama Macera citando a Rosas Yataco señala que la competencia territorial “Está referida
al lugar donde debe desarrollarse el proceso y sirve además para determinar el conocimiento
de los procesos en casos en que existen multiplicidad de órganos jurisdiccionales de la misma
categoría. La competencia por razón de territorio se establece el art. 21 del Código Procesal
Penal en el siguiente orden:
