UBILEX
A ) P o r e! lu g a r d e c o m is ió n d e l d e lito
En donde se cometió el hecho delictuoso o donde se haya realizado el hecho en tentativa,
como también en donde se cesó la continuidad o la permanencia del delito, por el lugar
donde se realizó el hecho de carácter delictuoso, esto es, el iocusdelicti commissi.
B) Por el lu g a r d e los efectos del d e lito
Conocida como la teoría del resultado, se presenta en el supuesto en que por ejemplo se
haya cometido el delito en Lima pero sus efectos se produjeron en Arequipa, ante esto, si
el documento por el cual se falsificó la firma del supuesto vendedor se realizó en la plaza
Ázángaro, pero dicha minuta fue inscrita en los Registros Públicos de la ciudad de Arequipa
en razón a que le inmueble que se pretendió registrar también se encontraba en Arequipa,
tendremos que conducirnos a la aplicación espacial de la ley penal por cuanto el lugar de
comisión del delito es aquel en que se producen sus efectos (principio de ubicuidad)
C) Por el lu g a r d e las p ru e b as d e scu b ie rta s
En el lugar en donde se hayan develado las pruebas materiales del delito, como por ejem
plo puede ocurri r en el caso de robo a mano armada, en el que se trata de individualizar a
los autores luego de haberse descubierto que las armas blancas con las que fueron ame
nazadas las víctimas fueron encontradas en un dom icilio ubicado en el distrito judicial de
Lima-Norte.
D) Por el lu g a r d e d e te n ció n del im p u ta d o
Se trata del forum aprehensionis o lugar donde el imputado fue intervenido y detenido, así
por ejemplo, puede darse el caso en que luego de haberse producido un delito de robo
agravado perpetrado en la ciudad A, los malhechores deciden emprender huida y son
capturados en la ciudad B; en dicho caso, el juez de esta últim a jurisdicción será el encar
gado de avocarse al proceso.
E) Por el lu g a r d e d o m ic ilio d el im p u ta d o
También denominado el forum domicilü, es decir que también puede tomarse como lugar
de competencia para conocer el caso de un proceso penal, verificando el dom icilio o lugar
donde habitualmente vive el im putado.”238
Con fecha 21 de diciembre de 2023 a través del D. Leg. 1605, se modificó el artículo 24 del Có
digo Procesal Penal, esta reforma “únicamente ha incorporado que la competencia nacional
también alcanzará a los delitos de terrorismo, trata de personas y sicariato; es decir, si lo que
se quiere cuestionar es que esta modificación vulnera la competencia territorial e incluso el
principio de juez predeterminado por ley-que en realidad sí la hace-, se debe tener en consi
deración que dicha vulneración ya estaba presente desde un inicio. En otros términos, lo que
ha generado la modificación es que tal afectación se presente también cuando se procesen los
delitos mencionados’’239.
