Tema 7: Especialidad Procesal Penal
— C o m p e te n c ia p o r c o n e x ió n :
Por lo general, ante la presunción de comisión de un delito, el sistema penal responde con la
iniciación de un proceso; de ahí que se diga que habrá tantos procesos como delitos existan.
Sin embargo, los casos de conexión constituyen una excepción a lo señalado, conforme a la
cual dos o más delitos pueden ser investigados y juzgados en un único proceso, como con
secuencia de la existencia de elementos de conexidad referidos a los hechos o a los sujetos
imputados.
Así, “El artículo 31 CPP reconoce cuatro supuestos de conexidad procesal: conexidad subjetiva,
conexidad objetiva, conexidad mixta o analógicay conexidad por reciprocidad.
1. C o n e x id a d su b je tiv a . Está prevista en los incisos, 2 y 3, Se refiere a los delitos cometidos
simultáneamente por dos o más personas -supuestos de codelincuencia— , y a una plu
ralidad de delitos cometidos por dos o más personas vinculadas entre sí por una misma
voluntad crim inal— existencia de concierto-, y en tiempos y lugar diferentes.
2. C o n e x id a d o b je tiv a . Está prevista en el inciso 4°. Obedece a motivos estrictamente te-
leológicos. Comprende los supuestos de: a) comisión mediata: delitos cometidos para
facilitar otro delito, como medio de su comisión ulterior; y b) comisión para impunidad:
delitos cometidos para asegurar o procurar la impunidad.
3- C o n e x id a d m ix ta o a n a ló g ica . Está prevista en el inc, 1. Comprende los diversos delitos
cometidos por una persona. Se requiere que estos delitos tengan analogía o relación en
tre sí; esto es, delitos semejantes, unidad de bien jurídico violado, homogeneidad en el
modo de actuar del agente y relación de temporalidad, atendidas las circunstancias del
caso.
4 - C o n e x id a d por re cip ro cid ad . Está prevista en el inc. 5. Comprende las imputaciones re
cíprocas. Se basa en la reciprocidad delictiva. Como tal, aporta una gran economía ju
risdiccional en los hechos en lo que los imputados asumen entre sí y simultáneamente
el doble carácter de víctimas y victimarios -lesiones recíprocas, injurias o difamaciones
recíprocas-, a la vez que logra un efecto disuasivo para los casos en los que el personal in
vestigador se excede en sus funciones (por ejemplo: violación de dom icilio cometida por
un policía comisionado para la investigación de un robo o la incorporación de elementos
falsamente en un acta de incautación).240
5. SUJETOS PROCESALES
A) M in iste rio P ú b lico : Se reconoce al M inisterio Público como un organismo extra poder
al asignarle la función de persecución del delito, tiene la titularidad del ejercicio de la ac
ción penal y de la carga de la prueba. El máximo intérprete de la Constitución ha señalado
que "Conforme a lo dispuesto en los artículos 158°y 159° de la Constitución, el M inisterio Público es
un órgano autónomo, que tiene entre sus atribuciones promover la acción jud icia l en defensa de la
legalidad y de los intereses públicos tutelados por el derecho, velar por la Independencia de los órganos
jurisdiccionales y por la recta im partición de justicia, representar en los procesos judiciales a la socie-
