UBILEX
I■ I I dad, conducir desde su inicio ¡a investigación del delito, ejercitar la acción penal de oficio o a petición
de parte, entre otros”.241
El artículo 65.1 del CPP (Modificado por la Ley N° 32130) señala que el Ministerio Público, en la
investigación del delito destinada a ejercitar la acción penal, deberá obtener los elementos de
convicción necesarios para la acreditación de los hechos delictivos, así como para identificar
a los autores o partícipes en su comisión. Con la finalidad de garantizar la mayor eficacia en
la persecución y represión del delito, el M inisterio Público y la Policía N acional deben coo
perar y actuar de form a conjunta y coordinada, debiendo diseñar protocolos de actuación.
Corresponde decidir al Fiscal la estrategia jurídica y a la Policía la estrategia operativa en la
investigación del delito.
Tenemos también al reformado artículo 60.2 del CPP que dispone “el Fiscal conduce jurídica
mente la investigación preliminar, la cual es llevada a cabo por la Policía Nacional del Perú,
así como la Investigación Preparatoria, de acuerdo al principio de legalidad”.
Conduce jurídicamente la Investigación Preparatoria. Dispone de inmediato, en caso de de
lito flagrante o de existir detenido, el inicio de la investigación preliminary, en el térm ino no
mayor de 24 horas en los casos de delitos de tráfico ilícito de drogas, terrorismo, sicariato, ex
torsión, secuestro, feminicidio y criminalidad organizada. En caso de no existir detenido ni
flagranciay, en otro ti pode delitos, lo hará en el térm ino no mayor de 48 horas a fin de indagar
por intermedio de la Policía no sólo las circunstancias que permitan comprobar la imputación,
sino también las que sirvan para eximir o atenuar la responsabilidad del imputado.
Interviene en la emisión de la disposición para la investigación preliminar que está a cargo de
la Policía, e interviene permanentemente desde la formallzación de la Investigación Prepara
toria y durante todo el desarrollo del proceso. Tiene legitimación para interponer los recursos
y medios de impugnación que la Ley establece.
El Ministerio Público, en el ámbito de su intervención en el proceso, de conformidad con lo dis
puesto en los artículos 6 4 y i 22 del Código Procesal Penal, dictará disposicionesy providencias
y formulará requerimientos.
“Las disposiciones se dictan para decidir:
A. El inicio, la continuación o el archivo de las actuaciones.
B. La conducción compulsiva de un imputado, testigo o perito, cuando pese a ser emplazado
debidamente durante la investigación no cumple con asistirá las diligencias de investiga
ción.
C. La intervención de la policía a fin de que realice actos de investigación.
D. La aplicación del principio de oportunidad.
E. Toda otra actuación que requiera expresa motivación dispuesta por la ley.
Porsu parte, las providencias se dictan para ordenar materialmente la etapa de investigación y
los requerimientos se formulan para dirigirse a la autoridad judicial solicitando la realización
241 STC02920-2012-PH C/TC.
