Tema 7: Especialidad Procesal Penal
de un acto procesal. Las disposicionesy los requerimientos deben estar motivados, de manera
que se basten a sí mismos, sin remitirse a las decisiones del juez, ni a disposiciones o requeri
mientos anteriores. Los requerimientos, de ser el caso, estarán acompañados de los elementos
de convicción que lo justifiquen."242
Como podemos observar, el fiscal, en su condición de titu la r del ejercicio de la acción
penal, interviene permanentem ente y en form a activa en todo el desarrollo del proce
so penal, tiene legitim ación para ejercer las facultades discrecionales, como archivar los
actuados, aplicar principio de o p o rtu n id a d y acuerdos reparatorios, esto es, salidas alter
nativas para la solución del conflicto penal; con ello debe mantener la carga procesal en
niveles razonables. Solo el fiscal promueve la acción penal y tiene la facultad exclusiva y
excluyente para acusar a los imputados. También tiene legitim ación exclusiva para solici
tar la imposición de medidas coercitivas de carácter personal; esto quiere decir que si con
sidera que en el desarrollo de la investigación debe restringirse la libertad del imputado,
solicitará al juez las medidas que considere necesarias, form ulando sus requerim ientos
debidam ente fundam entados.
El fiscal también está legitimado para incoar procesos especiales como mecanismos de cele
ridad procesal, tales como el proceso inmediato, la terminación anticipada y la colaboración
eficaz. Por lo demás, el fiscal interviene en la etapa intermedia en las audiencias preliminares
de control de la acusación y de control del requerimiento de sobreseimiento.
También interviene activamente en la etapa de juzgamiento, en la que sostendrá su teoría del
caso y perseguirá que se aplique a los acusados la sanción prevista en la ley. Finalmente, está
legitimado para interponer los recursos y medios de impugnación que la ley establece. Todas
estas facultades las ejerce el fiscal porque, conforme a la Constitución Política del Estado, es el
titu la rd e l ejercicio de la acción penal.
El Fiscal, en cuanto tenga noticia del delito, dispone de forma inmediata que la Policía realice
las diligencias preliminares.
B) Policía N acional: La Policía Nacional es una institución profesional deservicio público cuya
existencia está contemplada en el artículo 166o de la Constitución Política del Perú. Teniendo
como su principal función preservar el orden internoy garantizar la seguridad ciudadana. Sin
embargo, es importante señalar que si bien esa es su función principal el CPP establece de
manera clara que lafunción de la PNPtambién es lade contribuiry aportaren la investigación
del delito bajo la dirección del Ministerio Público.
Así pues, Angulo Arana243, citando a Villavicencio, señala que la policía es la obligada a investi
gar los delitos previstos en el Código Penal, desarrollando ello mediante el concurso de perso-
