nal especializado en diversas actividades criminalísticas, tales como peritajes balísticos, quí
micos, biológicos, toxicológicos, de ingeniería forenses, médicos, psicológicos, grafotécnicos,
de identificación humana, técnicos vehiculares, contables, etc. También debe, en función a la
investigación, custodiar, asegurar, trasladar, así como estudiar indicios y evidencias del delito,
bajo plazos establecidos en la ley y cumpliendo con la cadena de custodia que otorgue legiti
midad y legalidad a tales elementos. Otra tarea es la confección y el resguardo de archivos de
autores de ilícitos, así como el registro de antecedentes policiales de los ciudadanos y de las
requisitorias judiciales.
Según el artículo 65.2 del Código Procesal Penal, modificado por la Ley N° 32130 (Pub.
10.10.2024) se ha establecido que en cuanto el fiscal tenga conocimiento de un delito deberá
disponer de forma inmediata que la Policía realice las diligencias preliminares. Cuando el Fis
cal dispone el inicio de la investigación preliminardeberá precisar el objeto, los plazos y, de ser
el caso, las formalidades específicas que deben reunir los actos de investigación realizados por
la policía para garantizar su validez (Artículo 65.3 CPP).
Para optim izar la labor de investigación del delito, la Policía puede solicitary proponer la rea
lización de diversas diligencias fiscales y luego del previo análisis, evaluación y anuencia del
Fiscal, coordinará la programación de actos de investigación adicionales que pueden ser incor
porados a la disposición fiscal. (Art. 331.2 CPP)
Como se puede observar sus funciones siguen siendo de carácter auxiliar de las labores de in
vestigación del Ministerio Público, aunque a criterio de diferentes juristas la reforma ha resuci
tado los poderes que tenía la Policíay que fueron abolidos por el actual Código Procesal Penal.
El artículo 67244 del CPP prescribe que la Policía al tom ar conocimiento de los delitos debe dar
cuenta inmediata-es decir, en el plazo más breve posible-al fiscal. Sin perjuicio de ello, la poli
cía por iniciativa propia puede realizar diligencias de urgencia e imprescindibles, que formarán parte de
las diligencias prelim inaresydela carpeta fiscal, siempre que éstas busquen:
1. Impedir las consecuencias lesivas del delito-cuya acreditación concomitante es obvia.
2. Individualizar a sus autores y partícipes.
3. Reuniry asegurar los elementos de prueba-en puridad, las fuentes de prueba-,
Similarfunción desarrollará tratándose de delitos dependientes de instancia privada o sujetas
a ejercicio privado de la acción penal.
244 Artículo recientemente modificado mediante Ley 32130, publicada el 10 de octubre del 2024, que estableció,
"1. La Policía Nacional del Perú en cumplimiento de sus funciones debe, inclusive por propia iniciativa, tomar
conocimiento de los delitos y comunicar inmediatamente al Fiscal, debiendo realizar, las diligencias de inves
tigación urgentes o inaplazables, que formarán parte de las diligencias preliminaresy de la carpeta fiscal, para
impedir sus consecuencias, individualizar a sus autores y partícipes, así como reuniry asegurar los elementos
