formalizada. El cumplimiento de las disposiciones fiscales en la investigación prelim inardel delito no genera
relación de subordinación por parte de los miembros de la Policía Nacional del Perú. 3. La investigación del
delito a ejecutarse por personal de la Policía Nacional en la etapa de la Investigación Preparatoria, será a re
querimiento del Fiscal competente para el caso concreto”.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1145 of 1506 --

Tema 7: Especialidad Procesal Penal
San Martín Castro245 citando a Gómez Colomer señala que estas diligencias de prevención"(...)
han de practicarse una vez descubierto el hecho delictivo, las cuales deben comunicarse al
fiscal,y cuya realización cesa cuando el fiscal se hace cargo efectivo de la investigación, a quien
entregará todo lo practicado -la actividad de investigación autónoma de la Policía, por cierto,
no culmina con la comunicación de la noticia del delito al fiscal, pero sí con su avocamiento
efectivo-. En concreto, lo que la Policía realizará son todas aquellas diligencias conducentes al
buen fin de la investigación, salvo las reservadas al fiscal.”
Con fecha 21 de diciembre de 2023 se modificó el artículo 67o del Código Procesal Penal a tra
vés del D. Leg. 1605, con esta reforma se ha añadido que las diligencias llevadas a cabo por la
Policía formarán parte de las diligencias preliminares y que la investigación del delito a ejecu
tarse por la Policía en la etapa de la Investigación Preparatoria, será a requerimiento del Fiscal
competente para el caso concreto. Posteriormente a través de la Ley N°32i30 (Pub. 10.10.2024)
el artículo en comentario vuelve a ser objeto de modificaciones en sus numerales 1 y 2, siendo
una de las principales modificaciones el rol que asume la Policía Nacional del Perú en la investiga
ción prelim inar Ahora, la investigación preliminar estará a cargo de la Policía. En esa línea, se
establece que Fiscalíay la Policía program arány coordinarán, de manera conjunta el empleo de pautas,
técnicasy medios indispensables para la eficacia de la investigación.
Por otro lado, se enfatiza la negación de la subordinación de la Policía al Ministerio Público,
puesto que textualmente señala-, “(...) el cumplimiento de las disposiciones fiscales en la investiga
ción prelim inar del delito no genera relación de subordinación por parte de los miembros de la Policía
Nacional del Perú".
En cuanto al artículo 68° del Código Procesal Penal, dispositivo legal que enumera las atribu
ciones de la Policía, que inicialmente también fue objeto de modificaciones por el D. Leg. N°
1605, a través de la Ley N° 32130 fue nuevamente modificado, entre los cambios producidos se
encuentra: i) la obligación de registrar las declaraciones de los presuntos autores o participes
del delito en dispositivos o equipos audiovisuales, y ¡i) la elaboración de un informe policial
en base a las diligencias practicadas preliminarmente; es decir, se la otorga una facultad pre-
calificadora del delito a la Policía pese a que es sabido que el personal policial no cuenta con
formación jurídica.
El informe policial remitido al fiscal no tiene carácter vinculante, contiene los antecedentes
que motivaron su intervención, la relación de las diligencias efectuadas, las precalificaciones
de los delitos presuntamente cometidos, así como los grados de presunta autoría y partici
pación, el análisis de los hechos investigados y las conclusiones respectivas que justifiquen
continuar o no con la Investigación Preparatoria. (Art. 332.2 CPP modificado por Ley N° 32130,
pub. 10.10.2024).
La Ley N° 32130 ha sido cuestionada por diversos juristas del ámbito penal y autoridades del
Ministerio Público, quienes señalan que esta Ley es inconstitucional, ya que las reformas in
troducidas por ésta contravienen lo proscrito en la Constitución Política, además de colisionar
con la autonomía de las facultades atribuidas al Ministerio Público.
