UBILEX
C) Imputado: San Martín castro citando a Moreno Catena: “El imputado es la parte pasiva ne
cesaria del proceso penal, que se ve sometido al proceso y se encuentra amenazado en su
derecho a la libertad, o en el ejercicio o disfrute de otros derechos cuando la pena sea de natu
raleza diferente a la privación de libertad, al atribuírsele la comisión de hechos delictivos por
la posible imposición de una sanción penal en el momento de la sentencia.”246
“La condición de imputado -legitimación pasiva- se adquiere cuando se es objeto de una im
putación por la comisión de un hecho punible, directa o indirecta, formal o informalmente.
Se pierde cuando finaliza el proceso: absolución, con la misma sentencia firme; y, condena,
cuando culminan las actuaciones procesales de ejecución forzosa.”247
Así pues, “la persona sometida a una investigación en el proceso penal recibe diversas deno
minaciones en función de la etapa en la que nos encontremos. Así, el térm ino imputado im
plica una serie de denominaciones que se van dando en función del grado del desarrollo del
proceso, siendo estos: (a) implicado, sujeto incriminado en virtud de los actos de investigación
preliminar; (b) denunciado, sujeto contra el cual se ha formalizado una denuncia penal; (c)
procesado, sujeto contra quien se dirige la imputación como consecuencia de la emisión de
una disposición fiscal de formalización de la investigación preparatoria; y, (d) acusado, sujeto
contra quien ya se ha emitido una acusación,y se ha previsto la realización del juicio oral.”248
D) Abogado D e fe n so r- Defensa Técnica: Podemos señalar que “La misión del defensor con
siste en aportary hacer valer en el proceso todas las circunstancias y puntos de vista, así en la
cuestión de hecho como en la jurídica, favorables al acusado”249. “Desde luego, la importancia
que tiene el abogado defensor en el proceso penal es indiscutible, ya que mediante su aseso
ría el imputado puede ejercer de manera satisfactoria todos los derechos que el ordenamien
to le reconoce y con ello hacer frente al iuspuniendi del Estado.”250
Oré Guardia citando a Rifa Soler indica que, "El hecho de considerar al abogado defensor como
imprescindible para el desarrollo del proceso, exige que se realice una necesaria distinción entre
el defensor elegido libremente por el im putadoyel defensor de oficio o público, que puede ser
designado por el juez o el fiscal si no lo hubiera realizado aquél. En efecto, el imputado siem
pre tiene la oportunidad de designar un abogado defensor de su confianza, lo que significa que
también en cualquier estado del proceso puede reemplazarlo, así como en un inicio contar un
defensor público y luego cambiarlo por el de su elección, con la única limitación de no interferir
con el correcto y normal desarrollo del proceso.”251
Esto último ha sido señalado por el Tribunal Constitucional que considera que: “El derecho a una
defensa técnica consiste en contar con el asesoramientoy patrocinio de un ahogado defensor durante todo
el tiempo que dure el proceso; en que una parte procesal tiene el derecho de contar con un abogado que lo
defenday lo patrocine desde el inicio de la investigación, durante toda esta etapa y para todo el proceso que
