BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1147 of 1506 --

Tema 7: Especialidad Procesal Penal
eventualmente se instaure, para lo cual podrá elegir a su defensor Sin embargo, esta regla tiene su excep
ción, la cual se encuentra prevista en el Código Procesal Penal (Decreto Legislativo 957), en su artículo 85,
que señala que, ante la ausencia del abogado de su elección, la parte podrá elegir otro defensor o, en su defec
to, el órgano jurisdiccional podrá designarle de ofcio otro a efectos de que se realice la audiencia o diligencia
por el carácter de inaplazable que tienen dichas actuaciones en virtud del principio de celeridad que inspira
el referido ordenamiento procesal.”252
En efecto, debemos señalar que el derecho de defensa es un derecho de relevancia no solo cons
titucional, sino de estándares de protección de sistemas internacionales de derechos humanos,
ya que se trata de un derecho de intensa esencial idad para las partes intervinientes en el proce
so penal, entre ellos, el investigado en un proceso penal, sobre quien recae en primer lugar, la
sospecha de la presunta comisión de un hecho delictivo durante la investigación preparatoria,
y la carga probatoria una vez que el representante le atribuyó cargos a través del requerimiento
acusatorio. Por lo que, la defensa en el proceso penal vigente asume un rol fundamental y mucho
más activo en el desarrollo del proceso penal, incluso, podemos afirmar que va a la par de las
actividades que realiza el fiscal durante el desarrollo del proceso, recordemos que el abogado
defensor podrá entre muchas de sus atribuciones en el marco de la defensa: proponer testigos,
proponer diligencias que contribuyan al desarrollo de su teoría del casoyen consecuencia consi
gan la neutralización de las sindicaciones de la parte denunciante; asimismo, también podemos
afirmar que la defensa podría proponer la realización de exámenes periciales de parte, lo cual,
abonaría de modo eficiente en su defensa.
Como se ha señalado anteriormente, la defensa también debe tener la destreza necesaria para
poder asumir el desarrollo de un juicio, es decir, debe contar con la destreza del litigio oral du
rante el juicio oral, es decir, debe contar con el manejo elemental y detallado de las técnicas de
litigación oral.
La defensa también puede responder disciplinariamente si es que, en el ejercicio de su rol, como
tal propende a la perturbación del proceso penal, mediante actos dilatorios, los mismos que
pueden dar lugar a apercibimientos por parte del Representante del Ministerio Público, así como
el Juez, a efectos que sean sometidos a procedimientos disciplinarios ante el Colegio de Aboga
dos a la que se encuentran agremiados.
"Los derechos que ostenta el abogado defensor son de suma importancia, pues de tales derechos
dependerá su participación en el proceso y, el ejercicio eficaz y eficiente de sus funciones. Por
ello, se le debe asegurar, principalmente, su intervención con todas las facultades que le otorga
el ordenamiento.”253
En cuanto a sus derechos, el artículo 84o del Código Procesal Penal señala que: "El abogado de
fensor goza de todos los derechos que la ley le confiere para el ejercicio de su profesión, especial
mente de los siguientes: 1. Prestar asesoramiento desde que su patrocinado fuere citado o dete
nido por la autoridad policial. 2. Interrogar directamente a su defendido, así como a los demás
procesados, testigosy peritos. 3. Recurrí r a la asistencia reservada de un experto en ciencia, técni
ca o arte durante el desarrollo de una diligencia, siempre que sus conocimientos sean requeridos
252 STC N°1795-2016-PH C/TC.
253 ORÉ GUARDIA, Arsenio (2016). Derecho Procesal Penal Peruano. Tomo I. Gaceta Jurídica, p. 265.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1148 of 1506 --

UBILEX
para mejor defender. El asistente deberá abstenerse de intervenir de manera di recta. 4 - Participar
en todas las diligencias, excepto en la declaración prestada durante la etapa de investigación por
el imputado que no defienda. 5 -Aportar los medios de investigación y de prueba que estime per
tinentes. 6 . Presentar peticiones orales o escritas para asuntos de simple trámite. 7. Tener acceso
en todo el desarrollo del proceso a los documentos de ámbito policial y a los expedientes de ám
bito fiscal y judicial para informarse del proceso, sin más limitación que la prevista en la ley, así
como a obtener copia simple de las actuaciones en cualquier estado o grado del procedimiento.
8 . Ingresar a los establecimientos penales y dependencias policiales, previa identificación, para
entrevistarse con su patrocinado. 9. Expresarse con amplia libertad en el curso de la defensa,
oral mente y por escrito, siempre que no se ofenda el honor de las personas, ya sean naturales o
jurídicas. 10. Interponer cuestiones previas, cuestiones prejudiciales, excepciones, recursos im
púgnatenos y los demás medios de defensa permitidos por la ley.”
En cuanto a sus "deberes tiene la obligación de asistir a todas las diligencias que se practiquen,
a fin de obtener la mayor cantidad de información que le permita preparar su estrategia de de
fensa de manera adecuada. Del mismo modo, el abogado defensor tiene el debery derecho de
guardar el secreto profesional, es decir, bajo ningún motivo puede ser obligado a revelar lo que
su cliente le ha confesado; así lo establecen el Código de Ética de los Colegios de Abogados del
Perú. (Art. 10o) y la Constitución (art. 2.18). De este modo, el deber de guardar el secreto profe
sional no se puede vulnerar a pesar de que el cliente le haya confesado ser autor o partícipe del
hecho que se le está imputando.”254
E) Actor civil: "Actor civil es la persona física o jurídica (agraviado o perjudicado por la comisión
del hecho delictivo) que se encuentra facultado para ejercer la acción civil dentro del proceso
penal; es decir, el sujeto que pretende la restitución de la cosa, la reparación del daño o la in
demnización de perjuicios materiales y morales, que interviene en el proceso penal de manera
secundaria y eventual ”255
Con respecto a ello, el Acuerdo Plenario N°5-20ii/CJ-ii6 citando a San Martín Castro, define al
actor civil"(...) como aquella persona que puede ser el agraviado o sujeto pasivo del delito, es de
cir quien directamente ha sufrido un daño criminal y, en defecto de él, el perjudicado, esto es, el
sujeto pasivo del daño indemnizable o el titular del interés directa o inmediatamente lesionado
por el delito, que deduce expresamente en el proceso penal una pretensión patrimonial que trae
a causa de la comisión de un delito.”256
Habiéndose establecido estas precisiones conceptuales cabe señalar la manera en que la norma
procesal indica su forma de constitución; esto, debido a su naturaleza civil propia del principio
dispositivo. Así, para constituirse en Actor Civil se “(...) requiere de una demanda o solicitud en
forma que debe realizarse— oportunidad procesal— antes de la culminación de la investigación
preparatoria (artículo icn CPP), esto es, antes de que se dicte la disposición de conclusión de la
investigación preparatoria o de que el juez dicte el auto que ordene la conclusión de la misma
(artículos 342 y 343 CPP). (...). Como requisito formal la demanda o solicitud de constitución en
