Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1149 of 1506 --

Tema 7: Especialidad Procesal Penal
actor civil se presenta por escrito ante el juez de la investigación preparatoria-en este último caso
se trata de un presupuesto procesal del órgano jurisdiccional."257
Luego de ello, y habiendo cumplido con los requisitos de admisibilidady elementos materiales
que contengan la demanda o solicitud, la constitución en actor civil será expresada en una reso
lución judicial admitiéndola.
En cuanto a las facultades que posee el actorcivil, éstas se encuentran contenidas en los artículos
104 y 105 CPR así, por ejemplo: “(i) conocer de las actuaciones, (ii) ser escuchado antes de cada
decisión que implique extinción o suspensión de la acción penal — siempre que lo solicite-, (¡ii)
deducir nulidad de actuaciones, (iv) ofrecer medios de investigación y de prueba, (v) participar
en su actuación, intervenir en el juicio oral,y (vi) interponer medios impugnativos. La única lim i
tación que tiene es que el ámbito de su intervención se circunscribe al objeto penal, en concreto:
pedir la sanción penal — incluye, por su carácter penal, las consecuencias accesorias formular
solicitudes al margen de su derecho indemnizatorio, y requerir medidas limitativas de derechos
e intervenir en el procedimiento correspondiente cuando están referidas al objeto civil.”258
La finalidad del actorcivil va más allá de la búsqueda de la restitución del bien o de su indemni
zación, puesto que también busca el esclarecimiento del hecho delictivo. Sin embargo, al tratar
se de una acción privada, de contenido patrimonial, procede su desistimiento, con la salvedad
de que solo podrá ejercer la acción indemnizatoria en otra vía si se desistió antes de la acusación
fiscal (artículo 106 CPP).
F) Tercero Civil: Para Ore Guardia el tercero civil o responsable civil “es la persona natural o jurí
dica que, sin haber intervenido en la comisión de un hecho punible, está llamado a responder
civilmente por los perjuicios ocasionados por los autores o partícipes del hecho delictivo, cuando
exista una relación especial de dependencia entre estos y los terceros obligados y dicha particu
lar situación jurídica determine la existencia de una obligación solidaria.’’259
Así pues, queda claro que“(...) el tercero civilmente responsable es la parte procesal que responde
de manera solidaria con el imputado (autor o partícipe) respecto de la responsabilidad civil deri
vada del hecho delictivo. Los responsables solidarios pueden ser personas naturales o personas
jurídicas de derecho privado o público.”260
Según San Martín Castro “los requisitos para la responsabilidad civil indirecta o subsidiaria son
dos:
(i) Que el infractor penal y el presunto responsable civil subsidiario estén ligados por una
relación jurídica o de hecho, por un vínculo, en virtud del cual el responsable penal princi
pal se halla bajo la dependencia onerosa o gratuita, duraderay permanente o puramente
circunstancial y esporádica de su principal o, al menos, la tarea, actividad, misión, servicio
o función que realiza cuenta con el beneplácito, anuencia o aquiescencia del supuesto
responsable civil subsidiario o indirecto,y
