-- 1150 of 1506 --

(ii) Que el delito que genera unay otra responsabilidad-directa o subsidiaria-se halle inscri
to dentro de un ejercicio normal o anormal de las funciones encomendadas y en el seno
de la actividad, tarea o cometido confiados al infractor penal, perteneciendo a su esfera o
ámbito de actuación."261
Por otro lado, el tercero civilmente responsable “(...) debe ser emplazado e incorporado al pro
ceso, a instancia del fiscal o del actor civil. Será tanto, como ha quedado expuesto, el tercero civil
como el responsable civil directo no imputado. El vínculo que existe es de solidaridad pasiva,
salvo el caso especialísimo de la persona jurídica en los supuestos del artículo 104 CP, que tiene
un caractersubsidiario.”262
En cuanto a su legitimación, la norma procesal señala que el fiscal o el actor civil, formularán
un requerimiento o solicitud motivada, que deberá ser presentada luego de la expedición de la
Disposición de Formalización de la Investigación Preparatoriay hasta antes de dar por concluida
la investigación preparatoria. (Inciso 1 del artículo 111 CPP).
6 . N U L ID A D P R O C E S A L
La nulidad procesal requiere como elemento consustancial que el defecto de motivación ge
nere una indefensión efectiva-no ha tratarse de una mera infracción de las normas y garan
tías procesales- Ésta únicamente tendrá virtualidad cuando la vulneración cuestionada lleve
aparejada consecuencias prácticas, consistentes en la privación de la garantía de defensa pro
cesal y en un perjuicio real y efectivo de los intereses afectados por ella, lo que ha de apreciarse
en función de las circunstancias de cada caso (principio de excepcionalidad de las nulidades
de decisiones de mérito en concordancia con el principio de conservación de los actos proce
sales -artículos I52°y siguientes del NCPP-)263.
Por su parte, el Profesor César San Martín Castro señala que, la nulidades un remedio procesal,
distinto del recurso ¡mpugnatorioode la acción de impugnación. Pero desde otra perspectiva,
sostiene que se puede concebir como una sanción procesal que priva de eficacia o efectos un
acto procesal por no haber observado los presupuestos o los requisitos que lo regulan y que
constituyen garantía de los derechos de los justiciables.
El Libro Segundo, Sección I, Título III del NCPR en su artículo 149o instaura la nulidad como
remedio señalando que: “La inobservancia de las disposiciones establecidas para las actuacio
nes procesales es causal de nulidad sólo en los casos previstos por la Ley”. De esta manera, se
tiene que el legislador peruano se refiere a la inobservancia de aquello preestablecido por ley
para el desarrollo de las actuaciones procesales, pues este ocasiona el vicio que desnaturaliza
el proceso.
El legislador clasifica las nulidades en absoluta (art.1500 NCPP) y relativa (art. 151o NCPP).
6.1. N ulid ad absoluta: El NCPP regula la nulidad absoluta en los artículos 149oy 150o NCPR y
es entendida como una sanción de ineficacia de los actos procesales que se realizan inobser
