Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1151 of 1506 --

Tema 7: Especialidad Procesal Penal
vando el contenido esencial de los derechos y garantías de cualquiera de las partes procesales
establecidas en la Constitución y solo en los casos previstos en la ley.
Las nulidades absolutas están destinadas a sancionar el vicio existente, previsto por ley, que
sustancialmente altera los fines del proceso y la decisión que recae en éste. Además, esta ins
titución procesal presenta dos notas características: i) puede ser declarada de oficio, y ii) la
existencia del vicio o error acarrea la ineficacia del acto procesal derivado. Así, la norma es
tablece cuatro causales de nulidad absoluta, en razón de los defectos concernientes: "a) A la
intervención, asistencia y representación del imputado o de la ausencia de su defensor en los
casos en que es obligatoria su presencia; b) Al nombramiento, capacidad y constitución de
jueces o Salas; c) A la promoción de la acción penal, y a la participación del Ministerio Público
en las actuaciones procesales que requieran su intervención obligatoria; d) A la inobservancia
del contenido esencial de los derechos y garantías previstos por la Constitución”264.
6.2. N ulid ad relativa: Según el art. 151 del NCPP, el sujeto procesal afectado deberá instar la
nulidad por el vicio, cuando lo conozca, La solicitud de nulidad deberá describir el defecto y
proponer la solución correspondientey deberá ser interpuesta dentro del quinto día de cono
cido el defecto.
La nulidad no podrá ser alegada por quien la haya ocasionado, haya concurrido a causarla o
no tenga interés en el cumplimiento de la disposición vulnerada. Tampoco podrá ser alegada
luego de la deliberación de la sentencia de primera instancia o, si se verifica en el juicio, luego
de la deliberación de la sentencia de la instancia sucesiva.
6.3. Convalidación (Art. 152 NCPP): Salvo los casos de defectos absolutos, los vicios quedarán
convalidados en los siguientes casos:
a) Cuando el Ministerio Público o los demás sujetos procesales no hayan solicitado oportu
namente su saneamiento;
b) Cuando quienes tengan derecho a impugnarlo hayan aceptado, expresa o tácitamente,
los efectos del acto;
c) Si, no obstante su irregularidad, el acto ha conseguido su fin respecto de los interesados o
si el defecto no ha afectado los derechosy las facultades de los intervinientes.
El saneamiento no procederá cuando el acto irregular no modifique, de ninguna manera, el
desarrollo del proceso ni perjudique la intervención de los interesados.
6.4. Efectos de la n ulid ad .-
1. La nulidad de un acto anula todos los efectos o actos consecutivos que dependen de él. El
juez precisará los actos dependientes que son anulados.
z. Los defectos deberán ser subsanados, siempre que sea posible, renovando el acto, rectifi
cando su error o cumpliendo el acto omitido.
3. La declaración de nulidad conlleva la regresión del proceso al estado e instancia en que se
ha cumplido el acto nulo. Sin embargo, no se podrá retraer el proceso a etapas ya preclui-
