UBILEX
das salvo en los casos en que así correspondiere de acuerdo con las normas del recurso de
apelación o de casación.
4. La declaración de nulidad de actuaciones realizadas durante la Investigación Preparato
ria, no importará la reapertura de ésta. Asimismo, las nulidades declaradas durante el
desarrollo del juicio oral no retrotraerán el procedimiento a la etapa de investigación o a
la etapa intermedia.
6.5. Saneamiento (Art. 153 NCPP): Los defectos deberán ser saneados, siempre que sea po
sible, renovando el acto, rectificando el error o cumpliendo con el acto omitido, de oficio o a
instancia del interesado. Bajo pretexto de renovación del acto, rectificación del error o cumpli
miento del acto omitido, no puede retrotraerse el proceso a períodos ya precluidos, salvo los
casos expresamente previstos por el NCPP
i. Definición: La prueba es todo conocimiento aportado sobre el hecho delictivo que se incor
pora al proceso penal, siempre que se cumplan con los requisitos establecidos por ley. En tal
sentido, la prueba tiene naturaleza procesal, toda vez que despliega sus efectos en el proceso.
Así, la función principal de la prueba es producir la convicción en el juez sobre la forma en
cómo sucedieron los hechos discutidos, para que, posteriormente, se pronuncie sobre la cul
pabilidad o inocencia del imputado.
Tal como se expuso, no toda prueba ingresará exitosamente al proceso penal. Esto, debido a
que debe reunirciertas características que le otorgarán virtualidadsuficiente para ser valorada
por el órgano judicial. En la Sentencia 01014-2007-HC/TC, se establecen dichas característi
cas. Primero, debe ser un reflejo exacto de lo acontecido en la realidad, por lo que no debe ser
susceptible de manipulación. Segundo, debe obtenerse sin violar el contenido esencial de los
derechos fundamentales ni transgredir el orden jurídico. Lo dicho abarca tanto la obtención
de la prueba, como su recepción y valoración. Esto justifica la exclusión de la prueba prohibi
da, de la cual se hablará más adelante. Tercero, la prueba debe ser útil, esto es, que debe vincu
larse directamente al hecho presuntamente delictivo. Aunado a ello, la prueba debe producir
certeza judicial suficiente para la resolución o aportación a la resolución del caso concreto. Por
último, también se dice que debe ser pertinente, es decir, adecuada, en el sentido que debe
guardar relación directa con el objeto del procedimiento.
En suma, los medios probatorios son modos u operaciones, referidos a cosas o personas, que
son susceptibles de proporcionar un dato demostrativo del evento sobre el cual versa la acusa
ción penal (Hernández, 2018, pp. 133)- En la misma línea, el numeral 1 del artículo 157 del CPP
menciona que los hechos objeto de prueba podrán ser acreditados por cualquier medio de
prueba permitido por la Ley.
Cabe mencionar que las partes pueden proponer la actuación de diversas diligencias fiscales,
siempre y cuando dichos requerimientos de parte consten de características tales como la per
tinencia, conducencia, necesidad y utilidad, control que se encontrará bajo la evaluación de
la autoridad fiscal, quien deberá determ inary analizar la procedencia de adm itir dicho reque
rimiento si este cumple con los estándares antes mencionados; en lo demás, la defensa tiene
7 . L A P R U E B A E N E L P R O C E S O P E N A L
