El desalojo preventivo (art- «En los delitos de usurpación, el Juez, a
311°) solicitud del Fiscal o del agraviado, po
drá ordenar el desalojo preventivo del
inmueble indebidamente ocupado en el
término de veinticuatro horas, ministra
do provisionalmente la posesión al agra
