No confundirse sobre «que el derecho del agravia
do está suficientemente acreditado". Elio no quiere
decir que no se pueda cometer usurpación con
tra alguien que no tiene derecho (= título) alguno
a poseer. Significa sola- mente que la víctima de
usurpación que no te- nía derecho, no recuperará
el bien, sin perjuicio de que:
se sancione al responsable del delito,
se devuelva al bien a quien sí corresponda.
Las medidas preventivas
contra las personas jurí
dicas (art- 313°)
La pensión anticipada de
alimentos (art- 314°)
Se trata de algunas consecuencias del art-
105° del CP y algo más:
La clausura temporal, parcial o total,
de sus lo- cales o establecimientos:
La suspensión temporal de todas o al
guna de sus actividades;
El nombramiento de un Administrador
Judicial;
El sometimiento a vigilancia judicial;
- Anotación o inscripción registral del
procesamiento penal.
Se limita a ciertos delitos:
homicidio,
- lesiones graves.
- omisión de asistencia familiar pre
vista en el artículo 150 del Código
Penal.
- violación de la libertad sexual.
- delitos que se relacionan con la
violencia familiar.
■ implica imposibilidad del agraviado de
autosostenerse a consecuencia de la
perpetración del delito.
El CPP parece abstenerse de pronunciamiento so
bre casos en que la desposesión no se deba a una
usurpación. Por ejemplo, mediante una falsificación
de Escritura Pública se logra inscribir una falsa trans
ferencia de inmueble, y mediante soborno a un juez,
éste ordena el des- alojo, para darle el bien al autor de
la falsedad documental. En este proceso por falsedad
documental y cohecho, el desposeído no es técnica
mente sujeto pasivo del delito, pero sí víctima según el
CPP de 2004. Tomando en cuenta que el ni el Derecho
Penal ni el Derecho Procesal Penal implican la anula
ción de actos jurídicos.
a Hay requisito de fumus boni íuris sobre el art-
105° del CP
Se señalan dos peligros:
El procesal de obstaculización probatoria.
- Reiteración delictiva.
Limitación temporal: duración no mayor de la
mitad de las medidas del art- 105° del CP (¿y si
se trata de medidas definitivas?).
Excepción en delitos ecológicos: no hay plazo,
sino condición (siempre sujeta al plazo de la
duración del proceso, por cierto): reparación del
daño.
