bre todo en la noción extendida de agravia- do
que tiene el CPP. Ejemplo: una desaparición for
zada de personas, tomando como víctima a los
hijos menores de edad del desaparecido.
La perpetración («perpetrar-, según el RAE es
«Cometer, consumar un delito o culpa grave», y don
de «culpa- es «Omisión de la diligencia exigible a
alguien, que implica que el hecho injusto o dañoso
resultante motive su responsabilidad civil o penal-)
que es requisito, ¿implica la idea de que en todo de
lito tentado no existe daño, y por tanto es imposible
que haya imposibilidad de autosostenerse?
En la lógica de las limitaciones del art- 314°.
