8. La incautación instrumental (artículo 218° NCPP) recae contra (i) los bienes que constituyen
s cuerpo del delito, o contra (ii) las cosas que se relacionen con el delito o que sean necesarias
- J fc g B L para el esclarecimiento de los hechos Investigados. El objeto de esta medida de aseguramiento
H H es amplio y, por su propia naturaleza investigativa, comprende una extensa gama de bienes u
objetos relacionados, de uno u otro modo, con el delito.
En estricto sentido se entiende por;
A. ''Cuerpo del delito'', además de la persona -el cadáver en el delito de homicidio-comprende al objeto del de
lito, es decir, aquel contra el que recae el hecho punible o que ha sufrido directamente sus efectos lesivos
-la droga en el delito de tráfico ilícito de drogas-,
B. Las ''cosas relacionadas con el delito o necesarias para su esclarecimiento1, son tanto las ''piezas de ejecu
ción'': medios u objetos a través de los cuales se llevó a cabo la comisión del delito, como las denominadas
''piezas de convicción'': cosas, objetos, huellas o vestigios materiales, que pueden servir para la comproba
ción de la existencia, autoría o circunstancias del hecho punible.
9°. La incautac¡6n cautelar (artículo 316°.I NCPP) incide en los efectos provenientes de la infracción penal,
en los instrumentos con los que se ejecut6 y en los objetos del delito permitidos por la ley,
A. Los efectos del delito o producía scaeleris son los objetos producidos mediante la acción delictiva, como
el documento o la moneda falsa, así como las ventajas patrimoniales derivadas del hecho punible, como
el precio del cohecho, el del delincuente a sueldo, o la contraprestación recibida por el transporte de droga,
B. Los instrumentos del delito o instrumenta scaeleris son los objetos que, puestos en relación de medio a
fin con la infracci6n, han servido para su ejecución, tales como el vehículo utilizado para el transporte de
la mercancía, los útiles para el robo, el arma empleada, maquinarias del falsificador, etcétera.
C. Los objetos del delito son las cosas materiales sobre las que recayó la acción típica, como por ejemplo
las cosas hurtadas o robadas, armas o explosivos en el delito de tenencia ilícita de las mismas, la droga
en el delito de tráfico ilícito de drogas, los bienes de contrabando en dicho delito, etcétera, para lo que se
requiere una regulación específica.
