Tema 7: Especialidad Procesal Penal
La incautación exige necesariamente intervención judicial que la autorice, no obstante, esta
autorización podrá ser realizada mediante una resolución confirmatoria en aquellos casos en
donde existe peligro en la demora. Este supuesto es el regulado en el artículo 316 inciso 2 del
NCPR se presenta cuando el fiscal dispone la incautación y posteriormente solicita la resolu
ción confirmatoria de esa decisión que se adoptó por el peligro que representaba no incautar
inmediatamente.
Cuando no existe peligro en la demora, el fiscal debe solicitar la incautación al juez de la inves
tigación preparatoria con la finalidad que este emita la resolución de incautación que autoriza
al fiscal a realizar dicho acto de acuerdo a alguna de las finalidades que ha establecido nuestra
Corte Suprema en el acuerdo plenario citado. Contra la resolución de incautación emitida por el
juez, procede recurso de apelación conforme al artículo 316 inciso 3 que nos remite al artículo.
12. ETAPAS DEL PROCESO
Antes de entraren materia, es necesario previamente señalarque existe, por un lado, el proce
so penal común regulado en el Libro Tercero del CPP; y, por otro lado, los procesos especiales
regulados en el Libro V del CPP Estos últimos presentan estructuras procedimentales que res
ponden a exigencias particulares relativas a cómo se presenta la controversia.
Así tenemos entre los procesos especiales a la terminación anticipada, el proceso de colabora
ción eficaz, los procesos seguidos contra altos funcionarios, entre otros. Estos procesos especia
les tienen un tratamiento deferente al proceso común que se presenta como la regla general.
Por ejemplo, en el proceso común la regla es que se actúen pruebas para lograr mostrar la
verdad al juez a través de las mismas, por el contrario, en el proceso de terminación antici
pada, regulado en el artículo 468 y siguientes del CPR los hechos materia de imputación no
son objeto de prueba en tanto son aceptados por la parte acusada. Consecuentemente no hay
actividad probatoria, diferencia que lo distingue notablemente del proceso común y que ju sti
fica un tratam iento diferenciado que impacta incluso en las consecuencias jurídicas del delito
mediante una rebaja de la pena.
Esta misma dinámica de rasgos distintivos entre el proceso común y los procesos especiales,
tendría que ser objeto de un apartado completo dirigido a desentrañar sus particularidades
que, naturalmente, los hace contar con etapas diferentes a las del proceso común. De allí que
en este apartado nos hemos de concentrar en las fases que presenta el proceso común y que
se encuentran recogidas en el Libro III del CPR
Dicho esto, procedemos a enumerar las fases del proceso común que vienen a ser: la investi
gación preparatoria que consta de diligencias preliminares y de la investigación preparatoria
formalizada, la etapa intermediay el juzgamiento (San Martín Castro, 2015, pág. 801). A conti
nuación, procedemos a explicar cada una de ellas.
