i. La investigación preparatoria
1.1. Las diligencias preliminares: El proceso penal común, tal como está regalado en el CPR
comienza con la noticia criminal -n o titia crim inis-, esto es un posible hecho delictivo. Esto lle
ga a manos del fiscal ya sea por medio de la policía, denuncia directa ante el despacho fiscal
por parte de cualquier persona o por toma directa de conocimiento por parte de la noticia
criminal. Seguidamente la Policía Inicia los actos de investigación preliminar. En este extremo,
cabe reseñar la últim a modificatoria efectuada al artículo 329.1 del CPP mediante Ley 32130
(Pub. 10.10.2024), por el cual, estableció que, "i.-La Policía Nacional del Perú Inicia investigación
comunicando de forma inmediata al Fiscal cuando tenga conocimiento de la sospecha de la comisión de
un hecho que reviste ios caracteres de delito por denuncia de los agraviados o mediante disposición fiscal”.
Cuando la noticia es puesta en conocimiento de la autoridad para que sea investigada, nos
encontramos ante una denuncia, regulada en el artículo 326 del CPR Mientras que cuando
la investigación se inicia por toma directa de conocimiento del hecho, nos encontramos ante
una investigación de oficio regulada en el artículo 329 inciso 2 del mismo cuerpo normativo.
Respecto de la investigación de oficio, ocurre como consecuencia de que los medios de comu
nicación social como los noticieros permiten a la autoridad tom ar conocimiento de un hecho
delictivo sin que haya una persona en particular que lo denuncie. Mientras que la denuncia
supone siempre a un sujeto que voluntariamente pone a conocimiento de la autoridad un
hecho posiblemente delictivo para que se inicien las investigaciones correspondientes (Cubas
Vlllanueva, 2009, pág. 419).
Una vez que el Fiscal, toma conocimiento del hecho delictivo de oficio o por denuncia de parte,
comunica a la Policía, para que ésta realice la investigación preliminar del caso. El Fiscal dis
