Tema 7: Especialidad Procesal Penal
pone que la Policía realice las diligencias de investigación que considere pertinentes y útiles,
dentro de los límites de la Ley.
La investigación preliminar del delito está a cargo de la Policía Nacional con la conducción
jurídica del Fiscal, ésta tiene por finalidad inmediata realizar los actos urgentes o inaplaza
bles destinados a determinar si han tenido lugar los hechos objeto de conocimiento y su de-
lictuosidad, así como asegurar los elementos materiales de su comisión, individualizar a las
personas involucradas en los hechos, incluyendo a los agraviados, y, dentro de los límites de la
Ley, asegurarlas debidamente; y como finalidad mediata investigar los hechos identificando,
ubicando, capturando o citando a los presuntos autores y demás partícipes del hecho delic
tivo, a efectos de ponerlos a disposición del Fiscal con el informe policial respectivo para que
este decida sobre la formalización de la Investigación Preparatoria. El plazo de las diligencias
preliminares, es de 6 o días. Este plazo puede variar de acuerdo a las exigencias del caso, para
lo cual el fiscal deberá fijar un plazo distinto mediante disposición271.
En caso el plazo fijado por el fiscal sea irrazonable, quien se vea afectado puede solicitar que
se emita una decisión final al respecto, ya sea formalizando la investigación o archivando la
misma. En caso el representante del Ministerio Público se niegue a la solicitud para em itir
pronunciamiento, este mismo sujeto afectado puede presentar esa misma solicitud al juez
para que evalúe la razonabilidad del plazo de investigación fijado, y de ser el caso, ordenar el
pronunciamiento por parte del fiscal en alguno de los sentidos ya señalados.
La Policía en todos los casos en que intervenga elevará al Fiscal un informe policial de la inves
tigación preliminar, este informe no tiene carácter vinculantey contiene los antecedentes que
motivaron su intervención, la relación de las diligencias efectuadas, las precalificaciones de los
delitos presuntamente cometidos, así como los grados de presunta autoríay participación, el
análisis de los hechos investigados y las conclusiones respectivas que justifiquen continuar o
no con la Investigación Preparatoria.
Durante esta primera fase del proceso penal, se busca acopiar información relativa a elemen
tos de convicción capaces de establecer hechos reveladores de la existencia de delito, la pres
cripción de la acción penal, la individualización del imputado y, eventual mente, la satisfacción
de requisitos de procedibilidad. Todas estas finalidades de la investigación preliminar están
recogidas en el artículo 336 del CPRy se encuentran revestidas del manto de la reserva y secre
to conforme a su artículo 324.
Asimismo, el ordenamiento procesal prevé una serie de garantías mínimas que el investigado
puede exigir ante el juez de investigación preparatoria desde esta temprana fase del proceso
penal. Estamos hablando de las garantías exigibles mediante tutela de derechos de conformi
dad con el artículo 71 del CPPyque han sido objeto de desarrollo jurisprudencial en el acuerdo
Culminado el plazo yo cumplidas las finalidades de las diligencias preliminares el fiscal debe
em itir una decisión, en consecuencia, si de la denuncia, del Informe Policial o de las Diligen
cias Preliminares que realizó aparecen indicios reveladores de la existencia de un delito, que la
271 No está demás mencionar que la actividad fiscal se desarrolla mediante disposiciones, providencias y reque
rimientos conforme lo señala el artículo 122 del NCPR
