acción penal no ha prescrito, que se ha individualizado al imputado y que, si fuera el caso, se
han satisfecho los requisitos de procedibilidad, dispondrá la formalización y la continuación
de la Investigación Preparatoria regulada en el artículo 336 del CPR
Si, por el contrario, no se han satisfecho los requisitos para formalizar la investigación, corres
ponde su archivo de conformidad con el artículo 334 inciso 1 del CPR Contra la disposición de
archivo de la investigación preliminar, el denunciante o el agraviado pueden interponer queja
en el plazo de 5 días. La queja se interpone ante el fiscal que dictó el archivo de la causa, quien
lo elevará al fiscal superior que emitirá pronunciamiento aprobando o desaprobando la dis
posición de archivo.
La investigación preliminares una subetapa de la Investigación Preparatoria. No podrán repe
tirse una vez formalizada la investigación.
1.2. Investigación preparatoria formalizada: Como ya adelantó, esta fase inicia con la emisión
de la disposición de continuación y formalización de la investigación preparatoria que dicta el
fiscal con conocimiento del juez de investigación preparatoria de conformidad con el artículo
3 del CPR Durante esta segunda etapa de la fase de investigación, el ordenamiento dota al re
presentante del Ministerio Público de una serie de instrumentos que le permiten investigar con
mayor intensidad. Así lo podemos apreciar del artículo 338 inciso 4 en laque se señala que, para
la actuación de prueba anticipada, la imposición de medidas coercitivas, así como la realización
de ciertas diligencias es obligatorio formalizar la investigación preparatoria.
En pocas palabras, durante la investigación formalizada, el fiscal alcanza la posibilidad de des-
plegartodoel arsenal que el ordenamiento prevé para conseguir un caso que permita el juzga
miento. Ello incluye las medidas cautelares que recaen sobre la persona humana, las llamadas
medidas de coerción personal dentro de las cuales se cuenta a la prisión preventiva.
Pero, así como el fiscal cuenta con mayores herramientas en su actividad investigadora, la
defensa también se ve revestida de nuevos instrumentos que le permiten incluso archivar la
causa mediante la intervención del juez de investigación preparatoria. Es así como durante la
fase de investigación formalizada, se pueden planteartodos los medios de defensa que prevé
nuestro ordenamiento procesal en sus artículos 4 ,5 y 6.
Mientras que durante la fase de investigación preliminar la defensa solo podía realizar una
labor persuasiva para con el Ministerio Público, mostrando los elementos de convicción de
descargo necesarios para que pudiera acoger su teoría del caso, durante la investigación for
malizada, se puede acudir directamente ante el juez de la investigación preparatoria.
Al abrirse esta etapa, también acontece uno de los efectos que más polémica ha causado en
la práctica forense desde que entró en vigencia el CPP: la suspensión del plazo de prescripción
de la acción penal por imperio del artículo 339 inciso 1. Si bien el artículo 84 del Código Penal
regula la institución de la suspensión del plazo de prescripción de la acción penal, este artículo
de la norma procesal prevé un supuesto específico de suspensión.
Durante mucho tiempo se discutió si en realidad nos encontrábamos ante un supuesto de
interrupción, pues la suspensión supone una prolongación significativa del plazo de prescrip
ción. Ante esta problemática que dividía a la judicatura nacional, la Corte Suprema emitió dos
acuerdos plenarios-, en los acuerdos plenarios N °i-2 0 io /C ]-ii6 y 3-2012/CJ-116, en los cuales
