Si los plazos vencen sin que exista una decisión final del Ministerio Público, el Imputado pue
de solicitar al juez que ordene dicho pronunciamiento mediante una solicitud de control de
plazo regulada en el artículo 343 del CPR
Cumplidas las finalidades de investigación propias de esta fase, el fiscal emitirá la disposición
de conclusión de la Investigación preparatoria y, a continuación, dentro de los siguientes 15
días, deberá optar por sobreseer la causa o por acusar mediante un requerimiento que se for
mula ante el juez de la investigación preparatoria.
La clausura de esta fase también supone el fenecimiento de la etapa en la cual el actor civil
puede constituirse de conformidad con el artículo 101 del CPP; por lo cual, este sujeto procesal
debe haber solicitado su constitución hasta antes de la notificación de la disposición de con
clusión de la investigación preparatoria.272
