2. E ta p a in t e r m e d ia
La etapa intermedia regulada en la sección II del título V del libro tercero del CPR constituye una
fase de saneamiento, de filtro en el cual el juez de la investigación preparatoria evalúa el resulta
do final de toda la etapa de investigación que se manifiesta en el requerimiento fiscal de sobre
seimiento o de acusación (Del Río Labarthe, 2010, pág. 55)- Por regla general, esta decisión debe
ser adoptada dentro de los 15 días que siguen a la disposición de conclusión de la investigación
preparatoria. Excepcionalmente el plazo es de 30 días para casos de criminalidad organizada.
El artículo 344 inciso 2 recoge la figura del sobreseimiento, contemplando en sus cuatro literales los
supuestos activan esta figura ya sea porque “el hecho imputado no ha existido como tal, que éste
aun existiendo no es típico, no es punible, o que el imputado no es su autor” (Del Río Labarthe, 2010,
pág. 85). A continuación, hacemos un breve repaso de los supuestos de sobreseimiento.
Art. 3 4 4 Inc.
2 Lit. "a"
- "El hecho objeto de la causa no se realizó o no puede atribuírsele al imputado". Producto de la
investigación se ha determinado que el hecho delictivo no existió o, existiendo, no contó con la
intervención delictiva del investigado.
Art. 3 4 4 Inc.
2 Lit. *b"
Art. 3 4 4 Inc,
2 Lit. *c*
- "El hecho imputado no es típico o concurre una causa de justificación, de inculpabilidad o de no pu-
nibilidad”. Aplicando las reglas de imputación objetiva y subjetiva, se determina que el hecho no se
puede subsumir en tipo penal alguno o que existe una causa de justificación o no punibilidad como
son los casos de excusas absolutorias.
- "La acción penal se ha extinguido”. Esto puede acontecer por cualquiera de los supuestos previstos
en el artículo 78 del Código Penal entre los que se encuentra la prescripción, la amnistía, entre otros.
Art. 3 4 4 Inc.
2 Lit. "d" :
- "No existe razonablemente la posibilidad de incorporar nuevos datos a la investigación y no haya
elementos de convicción suficientes para solicitar fundadamente el enjuiciamiento del imputado".
En este último supuesto existen elementos de convicción, pero son manifiestamente insuficientes.
La otra posibilidad, es que el fiscal emita el requerimiento de acusación que puede definirse
como “la interposición de la pretensión procesal penal de una petición fundada dirigida al órga
no jurisdiccional para que imponga una pena a una persona por un hecho punible que se afirma
que ha cometido” (Del Río Labarthe, 2010). La regulación positiva de aquello que debe contener
este requerimiento, lo encontramos en el artículo349 inciso 1 del CPPcuyo texto es como sigue.-
"Art. 349.- Contenido
1. La acusación fiscal será debidamente motivada, y contendrá:
c)
d)
/ a) Los datos que sirvan para identificar al imputado, de conformidad con lo previsto en el numeral 1 del
artículo 88;
La relación clara y precisa del hecho que se atribuye al imputado, con sus circunstancias precedentes,
concomitantes y posteriores. En caso de contener varios hechos independientes, la separación y el detalle
de cada uno de ellos;
Los elementos de convicción que fundamenten el requerimiento acusatorio;
La participación que se atribuya al imputado;
