f) i El artículo de la íe y penal que tipifique el hecho, la cuantía de la pena, que se solicite y Jas cónsecúenciis,
accesorias;
g) El monto de la reparación civil, los bienes embargados o incautados al acusado, o tercero civil, que garan
tizan su pago, y la persona a quien corresponda percibirlo; y,
h) Los medios de prueba que ofrezca para su actuación en la audiencia. En este caso presentará la lista de
testigos y peritos, con indicación del nombre y domicilio, y de los puntos sobre los que habrán de recaer sus:
declaraciones o exposiciones. Asimismo, hará una reseña de Jos demás medios de prueba que ofrezca.
2. La acusación sólo puede referirse a hechos y personas incluidos en la Disposición de formalización de la
Investigación Preparatoria, aunque se efectuare una distinta calificación jurídica.
3. En la acusación, el Ministerio Público podrá señalar, alternativa o subsidiariamente, las circunstancias de he
cho que permitan calificar la conducta del imputado en un tipo penal distinto, para el caso de que no resultaren
demostrados en el debate los elementos que componen su calificación jurídica principal, a fin de posibilitar la
defensa del imputado,
4. El Fiscal indicará en la acusación las medidas de coerción subsistentes dictadas durante la Investigación
Preparatoria; y en su caso, podrá solicitar su variación o que se dicten otras según corresponda
En esta ocasión hemos optado por la transcripción de lo que debe contener la acusación fiscal
por cuanto su descripción es sumamente claray debe ser observada en todos sus extremos. De
hecho, la ausencia de alguna de estas exigencias legalmente previstas, deberá constar como
observación formal por parte de la defensa tras haber sido notificado con el requerimiento
acusatorio.
En este punto, resulta pues imposible comenzar a analizar lo que sigue tras el requerimiento
acusatorio, pues conforme al artículo 350 del CPR la defensa solo cuenta con io días para po
der form ular observaciones formales, deducir excepciones, pedir el sobreseimiento, deducir
medios de defensa que no hayan sido previamente planteados, solicitar la variación de las me
didas coercitivas, solicitar la actuación de prueba anticipada, instar la aplicación del principio
de oportunidad, objetar la reparación civil y ofrecer pruebas.
Según el artículo 351 del CPR vencido el plazo señalado anteriormente, el juez en un plazo no
menor de 5 días ni mayor de 10, fija fecha y hora para la audiencia preliminar también cono
cida como audiencia de control de acusación o de sobreseimiento dependiendo del caso. Las
decisiones que se pueden adoptaren la audiencia preliminar conforme al artículo 352 del CPR
pueden versar sobre:
La corrección de la acusación por defectos formales, las mismas que pueden ser subsa
nadas en la misma audiencia o con un nuevo análisis por parte del fiscal. En este últim o
supuesto, el requerimiento es devueltoy la audiencia se suspende por 5 días.
Se decidirá sobre las excepciones y medios de defensa planteados. La consecuencia ju rí
dica que se desencadena si alguna de ellas es declarada fundada dependerá de su propia
regulación. Por ejemplo, si se declara fundada la excepción de improcedencia de acción,
la consecuencia es el archivo de la causa. La decisión del juez es apelable sin que ello sus
penda la continuación del procedimiento.
Se decidirá sobre el pedido de sobreseimiento que planteó la defensa o incluso puede
dictarse el sobreseimiento de oficio cuando el juez detecta que se configura alguna de
las causales que permiten su aplicación. En este caso, si el juez declara el sobreseimiento,
el fiscal y el agraviado pueden impugnarlo. Pero si el juez desestima el sobreseimiento
planteado por la defensa, dicha decisión no impugnable. Con ello se pone de relieve que
