UBILEX
las excepciones sí permiten apelación por parte de la defensa, a diferencia del sobresei
miento que excluye esa posibilidad.
La admisión de los medios de prueba ofrecidos, para lo cual las partes tienen que ha
ber señalado en su petición el aporte que busca obtener para el esclarecimiento de los
hechos, así como la pertinencia, conducencia y utilidad de los actos probatorios que se
proponen. La decisión del juez de investigación preparatoria en la admisión o rechazo de
los medios de prueba es inimpugnable. La razón de ello es que aquello medios probato
rios rechazados pueden ser nuevamente propuestos al inicio del juzgamiento conforme
al inciso 2 del artículo 373 del CPR
Si el juez de investigación preparatoria declara fundada algún medio de defensa que suponga
el archivo del proceso y esta decisión queda firme, entonces la etapa intermedia culmina con
esa decisión. Ya sea porque se consciente, o porque en apelación la misma es confirmada. Pero
si, por el contrario, el juez decide que el control de la acusación ha dado como resultado que la
misma supera las exigencias formales y materiales que se le imponen, emite el auto de enjui
ciamiento y con ello da por concluida la etapa intermedia. Después de notificar el citado auto,
todos los actuados pasan al juzgado correspondiente para que inicie el juzgamiento.
3. Juzgamiento
La palabra juicio deriva de dos palabras latinas: “ius” y “dicare”, la primera alude a “derecho”
mientras que la segunda a “decir", con lo cual podemos concluir que juicio alude al acto de
decir el derecho (Figueroa Navarro, 2017, pág. 35). En efecto, lo distintivo de esta etapa es que
se presenta como aquella en la que el juez ha de dictar sentencia sobre el fondo (Calaza López,
2021, pág. 461).
Esta es la fase estelar del proceso penal en donde las partes han de postular su teoría del caso
exponiendo los hechos, pruebas y fundamentos jurídicos relevantes para sostener su preten
sión (Peña Cabrera Freyre, 2021, pág. 227). Su inicio se computa desde la emisión del auto de
citación a juicio mediante el cual las partes toman conocimiento del juzgado competente, el
lugary el momento en que se realizará el juicio oral así como los testigosy peritos citados. Esto
es lo que prescribe el artículo 355 del CPP
La audiencia de juicio oral se instala con la imprescindible presencia del juzgador, el fiscal, la
defensa y el acusado tal como así lo señala el artículo 369 inciso 1. El juicio oral se puede de
sarrollaren una o varias sesiones, pero en este últim o caso, no pueden presentar intervalos de
tiempo superiores a 8 días por imperio del artículo 360 inciso 3 que impone la interrupción del
debate oral y su reinicio cuando se supera ese espacio temporal. Esto es a lo que la tradición
forense peruana le denomina el quiebre del juicio.
Cuando inicia el juicio oral, después de haberse dado los alegatos de apertura en la que las
partes exponen aquello que consideran sustenta sus pretensiones, el ordenamiento procesal
en su artículo 373, permite que las partes ofrezcan pruebas nuevas, que no les eran conocidas
durante la fase intermedia; y que reiteren el ofrecimiento de aquellas que no fueron admitidas
durante la audiencia preliminar pero que consideran necesarias para el juzgamiento.
Señalábamos que durante el juicio oral las partes formulan ante el juez su teoría del caso, y
ello se aprecia desde el inicio del mismo en donde cada uno de ellos realiza su alegato de
9 9
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

