Tema 7: Especialidad Procesal Penal
apertura que esperan se vea confirmado al momento de realizar el alegato de clausura. En
medio de estos dos alegatos, se sitúa toda la actividad probatoria en la que se interroga, si así
lo quiere, al acusado o acusados, a los testigos, a los peritos, se exhibe la prueba material y se
oralizan las pruebas documentales.
El interrogatorio de los testigos es muy diferente al interrogatorio de los peritos. Mientras que
los primeros deben declarar sobre lo que han presenciado,.salvo que se trate de un testigo de
oídas en cuyo caso se deberá buscar al testigo presencial, los peritos son examinados de cara a
las conclusiones vertidas en su pericia. La justificación de la prueba pericial estriba en la nece
sidad de esclarecer un hecho desde un punto de vista científico (Cubas Villanueva, 2009, pág.
289), a diferencia de la prueba testimonial que busca conocer hechos presenciados por una
persona (Figueroa Navarro, 2017, pág. 429).
De allí que sea natural que la norma procesal permita a los peritos consultaren todo momen
to notas escritas, documentos y publicaciones durante el interrogatorio, mientras que a los
testigos únicamente se les permita ver su declaración anterior al juicio a efectos de refresca
miento de memoria y para confrontar contradicciones. Estas reglas del interrogatorio de uno
y de otro se encuentran previstas en el artículo 378 del CPR
Culminada la actividad probatoria, existe la posibilidad que hayan surgido hechos que no
han sido probados pero cuyas fuentes de prueba pueden existir. He allí que el ordenamiento
procesal en su artículo 385 da a las partes una últim a oportunidad para solicitar la actuación
de prueba complementaria. Esta facultad también le es reconocida al juez como prueba de
oficio. En ambos casos, esa prueba debe resultar indispensable o manifiestamente útil para
lograr un correcto esclarecimiento de los hechos.
Finalizada la actividad probatoria, tiene lugar el alegato de clausura de las partes y acto seguido
tiene lugar la deliberación que no podrá tener una duración superior a 2 días, ni una suspensión
mayor a 3 días en caso de enfermedad de alguno de los jueces en caso de juzgados colegiados. En
proceso complejos, el plazo se duplica. Si se superan estos plazos sin haber decisión, el juicio debe
reiniciarse con participación de otros jueces. Las decisiones de los juzgados colegiados se adoptan
por mayoría, salvo cuando se impone cadena perpetua en cuyo supuesto se requiere unanimidad.
Si no hubiera mayoría respecto a la cantidad de pena o al monto de la reparación civil, se fija el tér
mino medio. Todas estas reglas se encuentran recogidas en el artículo 392 del CPR
El resultado final es la sentencia. Ya sea condenatoria o absolutoria. De acuerdo al artículo 396
del CPR la sentencia debe ser leída ante las partes que comparezcan. Si la causa es compleja
o la hora a la que culmina la audiencia es avanzada, se podrá leer únicamente el fallo y uno
de los jueces dará cuenta de forma sintetizada de los fundamentos de la decisión. Pero de
berán fijar fecha y hora para la lectura íntegra de la sentencia dentro de los 8 días siguientes.
La sentencia se entiende notificada al momento de su lectura íntegra y las partes recibirán
inmediatamente una copia.
13. TUTELA DE DERECHOS
Es una garantía de específica relevancia procesal penal, que puede usar el imputado cuando
ve afectado o vulnerado uno o varios derechos establecidos específicamente en el artículo 71o
BALOTARIO DESARROLLADO PARA LOS EXAMENES ESCRITOS DE SELECCION
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1194 of 1506 --

UBILEX
del CPR en cuyo caso puede acudir al Juez de la Investigación Preparatoria para que controle
judicialmente la legalidad y legitimidad de los actos de investigación practicados por el M i
nisterio Público y repare, de ser el caso, las acciones u omisiones que generaron el quebranta
miento del derecho de las partes procesales.
Un aspecto vital que es de destacar es que la tutela de derechos es un mecanismo eficaz
tendiente al restablecimiento del statu quo de los derechos vulnerados, que encuentra una
regulación expresa en el CPP, y que debe utilizarse única y exclusivamente cuando haya una
infracción-ya consumada-de los derechos que asiste al imputado. Como puede apreciarse, es
un mecanismo o instrumento procesal que se constituye en la mejor vía reparadora del me
noscabo sufrido, y que incluso puede funcionar con mayor eficiencia y eficacia que un proceso
constitucional de habeas corpus [ALVA FLORIÁN, César A. (2004) La Tutela de Derechos en el
Código Procesal Penal de 2004. Lima, Gaceta Jurídica, p. 13.]273
A U D IE N C IA D E T U T E L A D E D E R E C H O S :
Oportunidad de e je rc ic io
La vía de tutela judicial solo podrá hacerse efectiva durante las diligencias preliminares y en la
investigación preparatoria.
S u je to legitimado para solicitarla
Solo el imputado, no el agraviado, el actor civil o el tercero civil.
Derechos protegidos
La audiencia de tutela es uno de los principales aportes del nuevo sistema procesal penal, diri
gido a la protección de los derechos fundamentales.
Los derechos fundamentales deben gozar de mayor protección y por ello es que a nivel procesal
la Audiencia de tutela es uno de los principales aportes del nuevo sistema procesal. Los dere
chos protegidos a través de esta Audiencia son los que se encuentran recogidos taxativamente
en el artículo 71o del CPR Son los siguientes: (i) conocimiento de los cargos incriminados, (ii)
conocimiento de las causas de la detención, (iii) entrega de la orden de detención girada, (iv)
designación de la persona o institución a la que debe avisarse de la detención y concretización
inmediata de esto, (v) posibilidad de realizar una llamada, en caso se encuentre detenido, (vi)
defensa permanente por un abogado, (vii) posibilidad de entrevistarse en forma privada con
su abogado, (viii) abstención de declarar o declaración voluntaria, (ix) presencia de abogado
defensor en la declaración y en todas las diligencias que requieran su concurso, (x) no ser ob
jeto de medios coactivos, intimidatorios o contrarios a la dignidad, ni ser sometidos a técnicas
o métodos que induzcan o alteren la libre voluntad, (xi) no sufrir restricciones ilegales, y (xii)
ser examinado por un médico legista o por otro profesional de la Salud, cuando el estado de
salud así lo requiera. En salvaguarda de su efectiva vigencia, de esta audiencia de tutela pue
den emanar resoluciones judiciales que corrijan los desafueros cometidos por la Policía o los
Fiscales, así como también protejan al afectado.274
