Tema 7: Especialidad Procesal Penal
14. IMPUGNACIÓN
Los medios impugnatorios son los instrumentos legales puestos a disposición de las partes
y destinados a atacar una resolución judicial para provocar su reforma o anulación. También
son definidos como el conjunto de actos de postulación a través de los cuales la parte gravada
por la resolución definitiva puede obtener su revisión,ya sea porel mismo órgano judicial que
la dictó, ya sea por otro superior, con el objeto de evitar errores judiciales y asegurar la aplica
ción correctay uniforme de Derecho275.
Bajo el Título “La Impugnación”, el nuevo proceso penal regula los llamados recursos impúg
natenos que son aquellos actos procesales que pueden interponer una de las partes procesa
les cuando consideran que la resolución judicial les causa agravio y esperan que se modifique,
revoque o anule.
El CPP no distingue los tipos de medios impugnatorios, sino regula genéricamente el tema de
los recursos mencionando los siguientes-, reposición, apelación, casación y queja.
a) El recurso de reposición.- Es un medio impugnativo que procede contra un decreto. Debe
ser interpuesto en el plazo de un día de notificado o de conocida la resolución.
La doctrina entiende a la reposición como un “remedio”, ya que su resolución es dada por
el m ism ojuez que dictó la resolución impugnada (decreto). Conforme señala CARAVAN-
TES, este recurso tiene por objeto evitar dilataciones y gastos a consecuencia de una nue
va instancia y, por ende, su fundamento está dado por razones de economía procesal276.
El recurso de reposición procede contra los decretos, a fin de que el juez que los dictó
examine nuevamente la cuestión y dicte la resolución que corresponda.
b) Recurso de apelación.- Es el medio impugnatorio que busca la revisión de una resolución
judicial, por parte del superior jerárquico. Es el recurso que permite la doble instancia,
por lo que el superior jerárquico tendrá la competencia que el juez inferior, es decir, de
pronunciarse sobre los hechosy el derecho.
El recurso de apelación procede contra:
Las sentencias;
Los autos de sobreseimiento y los que resuelvan cuestiones previas, cuestiones pre
judiciales y excepciones, o que declaren extinguida la acción penal o pongan fin al
procedimiento o la instancia;
Los autos que revoquen la condena condicional, la reserva del fallo condenatorio o la
conversión de la pena;
Los autos que se pronuncien sobre la constitución de las partesy sobre aplicación de
medidas coercitivas o de cesación de la prisión preventiva;
Los autos expresamente declarados apelables o que causen gravamen irreparable.
