La apelación de autos y concurrencia de la parte apelante a la audiencia de segunda instancia
a 1° La naturaleza procesal de la apelación de sentencias es la revisión de la decisión de la pri-
mera instancia, en la que dado al principio de contradicción y de asistencia efectiva se requiere
la presencia obligatoria de la parte recurrente; por lo que en caso de su inconcurrencia se genera
como gravamen, la inadmisibilidad del recurso, lo que perjudica única y exclusivamente a dicha
SllfS3Bfl§¡l| parte recurrente, caso que no se puede aplicar supletoriamente con la audiencia de apelación de
autos, puesto que no se requiere presencia, puesto que no se realiza juicio alguno. 78° En este
punto, se debe tener en cuenta que el artículo Vil, del Título Preliminar, apartado 3, del NCPP, se
ñala expresamente que "[...] la ley que coapta la libertad o el ejercicio de los derechos procesales de la persona,
a§/'' como la que limite un poder conferido a las partes o establezca sanciones procesales, será interpretada
restrictivamente. La interpretación extensiva y la analogía quedan prohibidas mientras no favorezcan la libertad
del imputado o el ejercicio de sus derechos". De la norma acotada, se puede colegir que el hecho de trasladar
lo dispuesto es el artículo 423, apartado 3, del NCPP, que declara la inadmisibilidad del recurso de apelación de
sentencia por inasistencia del imputado a la audiencia, no puede aplicarse extensivamente a la impugnación de
autos porque se aplica la analogía in malam partem y perjudica de esta manera al imputado, pese a que la norma
contenida en el artículo 420 del acotado Código no lo señala en forma expresa. Por tanto, no es aplicable el apar
tado 3, del artículo 423, del NCPP, donde se señala la inadmisibilidad del recurso, pese a haber sido fundamento
porque toda persona tiene derecho a la tutela jurisdiccional protegida constitucionalmente; tanto más si se tiene
en cuenta que la interpretación sistemática que se buscaría hacer de dicho numeral no sería a favor del reo sino
en contra del mismo, vulnerándose el principio de la función jurisdiccional. 19o En otras palabras, no se puede
obviar que la sanción de inadmisibilidad del recurso por inasistencia a la audiencia es taxativa para los casos de
apelación de sentencias, y siempre en casos en las que discute el juicio de culpabilidad pero no para la apelación
de autos, lo cual no deriva de un olvido o error del legislador, porque claramente se advierte del apartado 5, del
artículo 420, del NCPP, que señala expresamente que "[...] a la audiencia de apelación de autos podrán concurrir
los sujetos procesales que lo estimen conveniente"; por tanto, si su asistencia a la audiencia es discrecional o
facultativo, en tanto que la ley los faculta a asistir o no a un acto procesal, sería ilegítimo porque al ejercer un de
recho sean sancionados penalmente". VIII Pleno Jurisdiccional de las Salas Penales Permanente y Transitorias.
Acuerdo Plenarío N° 1-2012/CJ-1?6.
c) Recurso de casación.- Es un medio de impugnación que tiene por finalidad controlar la
legalidad del proceso penal. Procede contra una resolución que ha aplicado de manera
errónea el derecho sustantivo o procesal. Se distinguen dos clases de casación:
Casación de forma.- Cuando se aplica incorrectamente la ley procesal. Si se declara
fundada la Casación, el proceso se anula, hasta el momento en que incurrió el vicio
procesal, para lo cual se reenvía el proceso a la instancia correspondiente.
Casación de fondo: Cuando se aplica incorrectamente la ley sustantiva. Si se declara
fundada la casación se anula la resolución impugnada, debiendo la Corte Suprema
em itir nuevo fallo, o reenviar el proceso si es necesaria la contradicción procesal.
También podemos decir el recurso de casación es el recurso que se interpone ante el Tri
bunal Supremo contra fallos definitivos en atención a graves infracciones a las leyes o a la
doctrina legal, con la finalidad de “casarlas” o anularlas.
El recurso de casación procede contra las sentencias definitivas, la denegación de autos
de sobreseimiento^ los autos que pongan fin al procedimiento, extingan la acción penal
o la pena o denieguen la extinción, conmutación, reserva o suspensión de la pena, expe
didos en apelación por las Salas Penales Superiores.
La procedencia del recurso de casación está sujeta a las siguientes limitaciones:
a) Si se trata de autos que pongan fin al proceso, cuando el delito imputado más grave
tenga señalado en la Ley, en su extremo mínimo, una pena privativa de libertad efec
tiva o mayor de 6 años.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1197 of 1506 --

Tema 7: Especialidad Procesal Penal
b) Si se trata de sentencias, cuando el delito más grave a que se refiere la acusación
escrita del Fiscal tenga señalado en la Ley, en su extremo mínimo, una pena privativa
de libertad efectiva o mayor de seis años.
c) Si se trata de sentencias que impongan una medida de seguridad, cuando ésta sea la
de internación.
d) Si la impugnación se refiere a la responsabilidad civil, cuando el monto fijado en la
sentencia de primera o de segunda instancia sea superior a 50 Unidades de Referen
cia Procesal o cuando el objeto de la restitución no pueda ser valorado económica
mente.
Excepcionalmente, será procedente el recurso de casación en casos distintos de los arriba
mencionados, cuando la Sala Penal de la Corte Suprema, discrecionalmente, lo considere
necesario para el desarrollo de la doctrina jurisprudencial.
d) Recurso de revisión.- Es un medio impugnativo excepcional que se interpone ante la Cor
te Suprema contra sentencias que han obtenido la calidad de cosa juzgada. En nuestro
sistema la revisión sólo procede contra sentencias condenatorias277.
La revisión de las sentencias condenatorias firmes procede, sin limitación temporal y sólo
a favor del condenado, en los siguientes casos:
a) Cuando después de una sentencia se dictara otra que impone pena o medida de se
guridad por el mismo delito a persona distinta de quien fue primero sancionada, y
no pudiendo conciliarse ambas sentencias, resulte de su contradicción la prueba de
la inocencia de alguno de los condenados.
b) Cuando la sentencia se haya pronunciado contra otra precedente que tenga la cali
dad de cosa juzgada.
c) Si se demuestra que un elemento de prueba, apreciado como decisivo en la senten
cia, carece de valor probatorio que se le asignara por falsedad, invalidez, adultera
ción o falsificación.
d) Si con posterioridad a la sentencia se descubren hechos o medios de prueba, no co
nocidos durante el proceso, que solos o en conexión con las pruebas anteriormente
apreciadas sean capaces de establecer la inocencia del condenado.
e) Cuando se demuestre, mediante decisión firme, que la sentencia fue determinada
exclusivamente por un delito cometido por el juez o grave amenaza contra su perso
na o familiares, siempre que en los hechos no haya intervenido el condenado.
f) Cuando la norma que sustentó la sentencia hubiera sido declarada inconstitucional
por el Tribunal Constitucional o inaplicable en un caso concreto por la Corte Suprema.
e) Recurso de queja.- Cesar San Martín, señala que la queja es un medio impugnatorio de
los autos emitidos por los Juzgados y Salas Superiores que denieguen el Recurso de Ape
lación, Casación o Nulidad278.
