15. PROCESOS ESPECÍALES
El CPP incorporó un conjunto de procesos especiales (Libro Quinto) que se sustentaron en la
necesidad de tomar en cuenta diversas circunstancias, de derecho penal material y de dere
cho procesal penal; así como en la asunción de distintas modulaciones en la configuración de
determinadas garantías procesales específicas y en la concreción diferenciada de varios prin
cipios procesalesy procedimentales, con la finalidad de plasmar respuestas institucionales en
la persecución procesal, adecuadas y proporcionales a los fundamentos que les dieron origen.
Los procesos especiales que regula el Libro V del CPP son los siguientes:
15.1. Proceso inm ediato (Art. 446° y SS.)
El proceso inmediato es un tipo de proceso especial, que bajo ciertos presupuestos especial
mente previstos en la ley, permiten abreviar el proceso penal. De cumplirse tales presupues
tos, el fiscal queda habilitado para incoarlo, obviando el desarrollo de las etapas de investiga
ción preparatoria (total o parcial) e intermedia, propias del proceso penal común.
Supuestos: Según el artículo 446° i CPR el Fiscal, podrá solicitar la vía del proceso inmediato,
según corresponda, cuando:
0 ,
* a. El Imputado ha sido sorprendido y detenido en el flagrante delito;
Según el Acuerdo Plenario Extraordinario N° 2-2016/CIJ-l 16, "el delito flagrante, en su con
cepción constitucionalmente clásica se configura por la evidencia sensorial del hecho delictivo:;
que se está cometiendo o que se acaba de cometer en el mismo instante de ser sorprendido;
el delincuente; de suerte que se conoce directamente tanto la existencia del hecho como la
identidad de! autor y se percibe, al mismo tiempo, la relación de este último con la ejecución del
delito y se da evidencia patente de tal relación. Se trata de una situación táctica, en que el delito
se percibe con evidencia y exige inexcusablemente una inmediata intervención [STSE de 3-2-2004], se
requiere una evidencia sensorial y luego de la noción de urgencia.
La doctrina procesalista reconoce como tres tipos de flagrancia: 1. Flagrancia estricta: el sujeto es sor
prendido y detenido en el momento de ejecutar el hecho delictivo. 2. Cuasi flagrancia: el individuo es
capturado después de ejecutado el hecho delictivo, siempre que no se le haya perdido de vísta y haya
sido perseguido desde la realización del delito. 3. Flagrancia presunta: la persona es intervenida por la
existencia de datos que permiten intuir su intervención -en pureza, que viene de ''intervenir1- en el hecho
delictivo [López Betancourt, Eduardo. Derecho Procesal Penal. Segunda edición. México: lura Editores, p.
concedido por el Ministerio de Ciencia y Tecnología al Área de Derecho Procesal de la Universidad de Alicante
y confinado por el Fondo Europeo de Desarrollo Regional. INCIPP Lima. 2004. p. 19.
