Tema 7: Especialidad Procesal Penal
El imputado ha confesado la comisión del delito:
El delito confeso está definido en el artículo 150 NCPP Por razones de simplificación procesal, la regla
para su admisión será la denominada "confesión pura o simple", en cuya virtud el imputado voluntaria
mente admite ios cargos o imputación formulada en su contra -relación de hechos propios por medio de
la cual reconoce su intervención en el delito-. Ese reconocimiento de los hechos por él cometidos (con
fesión propia), ha de ser libre -sin presiones o amenazas: violencia, intimidación y/o engaño- y prestado
en estado normal de las facultades psíquicas del imputado, así como con información al imputado de
sus derechos2''9.
c. Los elementos de convicción acumulados durante las diligencias preliminares, previo interrogatorio del
imputado, sean evidentes, serán evidentes cuando la fuerza probatoria de cada elemento genere con
vicción en el Fiscal para estimar razonablemente la comisión de un delito que vincule al imputado como
autor o partícipe del mismo.
d. Cuando reciba del juez competente copias certificadas de las piezas procesales pertinentes para acusar
al deudor alimentario por la comisión del delito de omisión de prestación de alimentos previsto en el
artículo 749 del Código Penal.
Si se trata de una causa seguida contra varios imputados, sólo es posible el proceso in
mediato si todos ellos se encuentran en una de las situaciones previstas en el numeral
anterior y estén implicados en el mismo delito. Los delitos conexos en los que estén invo
lucrados otros imputados no se acumulan, salvo que ello perjudique al debido esclareci
miento de los hechos o la acumulación resulte indispensable.
Quedan exceptuados los casos en los que, porsu complejidad, de conformidad con lo dis
puesto en el numeral 3 del artículo 342, sean necesarios ulteriores actos de investigación.
Independientemente de lo señalado en los párrafos anteriores, el fiscal también deberá
solicitar la incoación del proceso inmediato para el delito de conducción en estado de
ebriedad o drogadicción, sin perjuicio de lo señalado en el numeral 3 del artículo 447 del
presente Código (casos de aplicación del principio de oportunidad, de un acuerdo repara-
torio o de la terminación anticipada).
Presupuestos:
a. Que el delito no haya prescrito.
b. Que se hayan satisfecho los requisitos de procedibilidad de existirlos.
c. Que se incurra en uno de los supuestos de hecho que habilita la incoación del proceso
inmediato.
Oportunidad:
Luego de realizadas las diligencias preliminares.
Antes de los 30 días de formalizada la Investigación Preparatoria.
Procedimiento:
1. Requerimiento fiscal de proceso Inmediato.
2. Traslado del requerimiento a las partes.
3. Resolución del juez admitiendo o rechazando el requerimiento. Es apelable con efecto
devolutivo.279
