sales: 1. Audiencia única de incoación. El juez, se pronunciará oralmente y en el siguiente
orden, sobre: a. la procedencia de la incoación del proceso inmediato, b. la procedencia de la
constitución de las partes procesales, si fuera el caso. c. la procedencia del principio de opor
tunidad, de un acuerdo reparatorio o de la terminación anticipada, solicitado por las partes,
d. la procedencia de la medida coercitiva requerida por el fiscal. 2 . Audiencia única de juicio.
Ambas informadas por el principio de aceleramiento procesal, en el que rige la máxima de
que las audiencias son inaplazablesy la vigencia del principio de concentración procesal. Las dos se
erigen en sus notas características.
Cabe destacar que la audiencia única de juicio, condicionada por la audiencia única de incoa
