puestos y requisitos que lo configuran: evidencia delictiva y no complejidad procesal, a su vez,
se subdivide en dos periodos procesales: (i) de definición de los presupuestos del juicio para
dictar, si correspondiere, acumulativay oralmente, los autos de enjuiciam ientoy de citación a
