Tema 7: Especialidad Procesal Penal
15.2. Proceso por razón de la función pública
Dentro de este proceso especial se consideran como procesos por razón de la función pública
tres supuestos, basados en si los delitos cometidos son delitos de función o son ilícitos comu
nes y si son altos dignatarios y congresistas u otros funcionarios públicos:
i. El Proceso por delitos de función atribuidos a Altos Funcionarios Públicos.'' El artículo
4 4 9 del CPP señala que sólo podrán ser procesados en este ámbito los altos dignatarios a
los que se refiere el Artículo 99 de la Constitución Política del Perú, estos altos dignatarios
podrán ser procesados por infracción de la Constitución o por todo delito que cometen
hasta por un plazo de cinco años posteriores al cese de su función y requiere que exista
una denuncia constitucional como consecuencia del procedimiento parlamentario o la
resolución acusatoria de contenido penal aprobada por el Congreso, es decir, como anota
San Martín se requiere del proceso parlamentario de antejuicio o acusación constitucio
nal, cita a Montero Aroca, respecto a tutelas judiciales privilegiadas. Al recibir la resolu
ción acusatoria de contenido penal enviada por el Congreso de la República, la Fiscal de
la Nación formalizará la Investigación Preparatoriay la dirigirá a la Sala Plena de la Corte
Suprema a fin de que nombre al Vocal Supremo que actuará como Juez de la Investiga
ción Preparatoriay a la Sala Penal que se encargará del juzgamiento y del conocimiento
del recurso de apelación contra las decisiones del primero. Cabe anotar, que la Investiga
ción Preparatoria sólo podrá contener los hechos contenidos en la acusación constitucio
nal y la tipificación contenida en la resolución del Congreso, consecuentemente no podrá
darse tipificación alternativa o distinta a aquella, ni considerarse otros hechos, y si fuera
éste el acaso se requerirá de una nueva resolución acusatoria del Congreso iniciándose
un nuevo trám ite que partiendo del Fiscal de la Investigación Preparatoria se elevará a la
Fiscal de la Nación para que formule nueva denuncia constitucional ante el Congreso.
ii. El Proceso por delitos comunes atribuidos a Congresistas y Altos Funcionarios Públi
cos. - Este proceso implicaque en la etapa del Juzgamiento a estos funcionarios interven
drá un tribunal colegiado, y podrán ser comprendidos todos los altos funcionarios hasta
un mes después de haber cesado en sus funciones. En el caso de ser detenido en flagran
cia de delito, deberá ser puesto a disposición del Congreso o del Tribunal Constitucional
en el térm ino de 48 horas a fin de que se defina su situación jurídica. La petición para el
levantamiento de la inmunidad sólo puede ser solicitada por la Corte Suprema de Justicia
la que debe estar acompañada de una copia del expediente judicial, ello para que la Co
misión Calificadora del Congreso, citando al dignatario a fon de que ejerza su Derecho de
Defensa definirá si es pertinente el pedido o no.
iii. El Proceso por delitos de función atribuidos a otros Funcionarios Públicos.- Este apar
tado establece el proceso para los delitos de función perpetrados por otros funcionarios
públicos distintos de aquellos que tienen el rango de altos dignatarios y que puntual
mente se ha desarrollado; así tenemos, que la Fiscal de la Nación, previa indagación
preliminar, emitirá una disposición que ordene al Fiscal respectivo la formalización de la
Investigación Preparatoriay podrá comprender a los integrantes del Consejo Supremo de
Justicia Militar, los Fiscales Superiores, el Procurador Público y otros funcionarios de ese
nivel. En caso de flagrante delito, no será necesaria la disposición de la Fiscal de la Nación,
