UBILEX
el funcionario será conducido al despacho del Fiscal Supremo o del Fiscal Superior para
dicha formalización en el plazo de 48 horas. La Sala Penal de la Corte Suprema designará
entre sus miembros al Vocal Supremo que intervendrá en la Investigación Preparatoria
y a la Sala Penal Especial que se encargará del juzgamiento y del trám ite del recurso de
apelación, la Fiscal de la Nación definirá al Fiscal que conocerá en la etapa de la Investiga
ción Preparatoria y al que intervenga en la etapa de enjuiciamiento y el fallo em itido por
la Sala Penal Especial puede ser apelado ante la Sala Suprema prevista en la Ley Orgánica
del Poder judicial, que es la últim a instancia. Asimismo, corresponderá ser investigados
por el Fiscal Superiory juzgados por el Vocal designado por la Presidencia de la Corte Su
perior para que asuma la labor de la Investigación Preparatoria así como por la Sala Penal
Especial que se encargará del enjuiciamiento, el juez de Primera Instancia, el juez de Paz
Letrado, el Fiscal Provincial y el Fiscal Adjunto Provincial así como otros funcionarios de
similar investidura.
15.3. Proceso de seguridad (art. 456° y ss.)
Este proceso se instaura cuando se ha procedido conforme al artículo 75 del CPP o al finalizar
la Investigación Preparatoria cuando el Fiscal considere que sólo es aplicable al imputado una
medida de seguridad, por razones de salud o de minoría de edad, el Fiscal emitirá el requeri
miento de imposición de medidas de seguridad ante el juez de la Investigación Preparatoria
donde el encauzado será representado por su curador si es menor de edad y no se le interro
gará si ello es imposible. El juez de la Investigación Preparatoria puede rechazar este pedido,
optando por la aplicación de la pena.
Este proceso es reservado, se desarrolla sin público por su particularidad (personas con pro
blemas psíquicos, anomalías, vulnerabilidad notoria o minoridad), incluso puede realizarse
sin la presencia del imputado pudiendo éste ser interrogado en otro ambiente fuera del local
del juicio, se puede interrogar antes de la realización del juicio y leer sus declaraciones ante
riores si no pudiera contarse con su presencia, la diligencia más importante será la declaración
del perito que emitió el dictamen sobre estado de salud del imputado.
15.4. Proceso por delito de ejercicio privado de la acción penal (art. 459 y ss.)
La acción penal se formula por el directamente ofendido mediante querella, ya sea, por sí o
por su representante legal con las facultades generalesy especiales establecidas por el artículo
74 y 75 del CPC. El juez competente para conocer este proceso es el juez Unipersonal. La que
rella debe cumplir los requisitos que establece la ley y precisar la identificación y dom icilio del
querellado, tiene que anexarse la copia de la querella para cada querellado, asimismo, si fuera
el caso también debe ser anexado la copia del poder. La admisión o rechazo del escrito de la
querella es controlado por el juez Unipersonal, su decisión debe ser debidamente motivado.
El juez al adm itir la querella dicta el Auto admisorio, y corre traslado al querellado para que
dentro del plazo de 05 días después de la notificación, conteste a la querella y ofrezca medios
probatorios. El juez con o sin contestación dicta el auto de citación ajuicio oral, la que se desa
rrollará en el plazo no mayor de 30 días ni menor de 10 días.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1203 of 1506 --

Tema 7: Especialidad Procesal Penal
La audiencia tiene dos fases:
a) La fase de la audiencia conciliatoria, que es privada.
b) La fase de la audiencia o juicio oral, que es de carácter público.
En la audiencia el querellante tiene facultades y obligaciones como si fuera Ministerio Público,
con la diferencia de que debe ser interrogado. Se sobresee la causa por inasistencia injustifi
cada del querellante a la audiencia o se ausente durante su desarrollo, concluyendo en forma
definitiva el proceso.
Existen dos clases de coerción personal respecto del querellado:
a) La Comparecencia simple, es la citación al juicio oral sin ninguna regla de conducta, medida
o apercibimiento.
b) Comparecencia restrictiva, consiste en la restricción de ciertos derechos mediante reglas de
conducta, se da cuando existen fundamentos razonables de peligro de fuga, o porque
puede entorpecer la actividad probatoria.
Se instituye también la contumacia contra el querellado rebelde que estando notificado no
asiste al juicio oral, o se ausente durante el desarrollo del mismo, por la que se declara reo con
tumaz disponiéndose la requisitoria policial para su captura y detención, suspendiéndose el
juicio. Además del sobreseimiento por inasistencia o retiro durante el desarrollo del juicio oral
por el querellante que produce la conclusión del proceso, también se instituye el abandono, el
desistlmientoy la transacción como formas de conclusión del proceso de querella.
El querellante puede desistí rse de la acción p enafy también puede transigircon el querellado,
en cualquier estado del proceso. Una vez desistida o abandonada el proceso, el querellante ya
no tiene derecho para poder intentar nuevamente la querella, es decir, fenece en forma total
la acción de querella por el delito ofendido, por haberse abandonado o por haberse desistido.
Se da la sucesión procesal por muerte o por incapacidad de la querellante producida durante
el desarrollo del proceso de querella y antes de que concluya el juicio oral.
El proceso termina con la sentencia del Juez Unipersonal, y al ser apelada, con la sentencia de
vista de la Sala Penal Superior en forma definitiva.
SIMILITUDES Y DEFERENCIAS DEL PROCESO DE QUERELLA
lnlW uíte Ufe*- « « i i
El Código de Procedimientos Penales de 1941, estable
cía dos procedimientos para las querellas, una para las
querellas simples y otra para las agravadas y que se co
metían a través de los medios de comunicación social.
Con el Nuevo Código Procesal Penal, las querellas, se
sustancian a través de un solo proceso, no importa que
sea por prensa, medio de imprenta, radio, el juicio oral se
desarrolla a través de un solo proceso y se plantea ante el
Juez Penal Unipersonal.
Generalmente se apertura el proceso por acción priva
da, es con comparecencia simple y no con mandato de
comparecencia restrictiva, por lo que la pena máxima es
de tres años y ciento veinte a trescientos sesenta y cin
co días multa, en el transcurso del proceso y antes de la
realización del juicio oral, se puede solicitar la variación
de medida cautelar de comparecencia simple por la de
comparecencia con restricciones.
La querella, es interpuesta sólo por la persona ofendida o
su representante legal, el Nuevo Código Procesal lo deno
mina como Querellante Particular, el cual, para hacer valer
su derecho, tiene que cumplir con determinados requisi
tos (Art.109 NCPP) y si no se declara en el proceso se
tendrá por no presentada la misma la demanda.
