15.6. Proceso por colaboración eficaz (Art. 472° y ss.)
La colaboración eficaz en palabras de CESAR SAN MARTÍN: “Es un mecanismo de la justicia
premial negociada, incardinadaen el denominado Derecho Premial, descansa en la figura del
arrepentido, quien debe adm itir o, en todo caso, no contradecir ante la autoridad los hechos
delictivos que se le atribuyen y proporcionar información suficiente, eficaz e importante en
orden a neutralizar una actividad delictiva, identificar la lógica de actuación criminal de una
organización delictivay asus intervinientes,y/o entregar bienes delictivos o ubicar su destino
o paradero."283
Características:
Es un procedimiento simplificado con base consensual y premial.
Se requiere un acuerdo de beneficios y colaboración.
El acuerdo está sujeto a la aprobación judicial.
Procede en casos por delitos taxativamente señalados en la ley.
El acuerdóse puede celebrar cualquiera sea la situación jurídica del colaborador.
