Tema 7: Especialidad Procesal Penal
R e q u is ito s q u e d e b e r e u n ir e l c o la b o ra d o r:
1. Debe de haber abandonado voluntariamente sus actividades delictivas.
2. Debe adm itir los hechos en los que ha intervenido o se le imputen. Los hechos que no
acepte no formarán parte del proceso por colaboración eficaz.
3 . Debe presentarse al Fiscal mostrando su disposición por proporcionar información efi
caz.
Procedimiento: Luego de que la persona procesada expresa su deseo de colaborar, el Fiscal
inicia las diligencias de corroboración, a fin de establecer la eficacia de la información pro
porcionada. El Fiscal puede celebrar un Convenio Preparatorio que precise los beneficios, las
obligacionesyel mecanismo de aporte de la información y de su corroboración. Mientras dure
el proceso, el colaborador puede ser sometido a medidas de aseguramiento personal para ga
rantizar las investigaciones, el éxito del proceso y su seguridad personal.
El agraviado debe ser citado durante la verificación, afín de proporcionar información y docu
mentación sobre los hechos y absolver las preguntas que se le formulen.
Si el Fiscal corrobora la información y considera que es posible otorgarle al colaborador los
beneficios que correspondan, elabora un acta que debe contener lo siguiente: El beneficio
acordado; los hechos a los cuales se refiere el beneficio y la confesión en los casos en que ésta
se produjese; y las obligaciones a las que queda sujeta la persona beneficiada.
