15J! Proceso por faltas (482 al 486 del CPP)
El proceso por faltas tiene por finalidad procesar todas las conductas infractoras de faltas re
guladas en el código penal, es decir, de aquellos delitos en miniatura que tienen categoría de
infracciones, o leves como sustentan otros autores.
Son competentes para conocer este proceso los Jueces de Paz y los Juzgado de Paz Letrado.
Constituyen primera instancia siendo el Juez Penal Especializado la segunda y últim a instan
cia vía apelación. No interviene el Ministerio Público.
En este proceso el actor civil se denomina querellante, y ese acto se produce necesariamente
en el momento de denunciar la falta. La denuncia se puede form ular en forma verbal o escrita
ante la policía o ante el Juez sea letrado o no, cuando la denuncia es formulada ante el juez
éste si considera que el hecho denunciado constituye fa lta y la acción no ha prescrito y requie
re de una indagación previa, en cuyo caso, remite la denunciay sus recaudos a la PNP para la
investigación pertinente, quien, al concluir emitirá el informe policial correspondiente.
El Juez recibido el informe podrá dictar auto de citación ajuicio o en su defecto dictará el auto
de archivamiento. El juez al dictar el auto de citación a juicio puede disponer la realización
inmediata de la audiencia en los siguientes casos: a) Cuando están presentes el im putadoyel
querellante y demás órganos de prueba, b) Cuando el imputado ha reconocido la falta que se
le atribuye. De no darse estas probabilidades el juez fijará la fecha más próxima para el juicio,
convocándose al agraviado, al imputado y a los testigos. El juicio se desarrollará en audiencia
única y oral con presencia obligatoria de los abogados defensores tanto del imputado y que
rellante. El Juez en el auto de citación ajuicio únicamente podrá dictar mandato de compare
cencia sin ninguna clase de restricciones, es decir, sin reglas de conducta; pero, si no concurre
a la audiencia será conducido por la fuerza pública, incluso el juez puede ordenar la privación
de su libertad por tiempo que dure la audiencia.
Instalada la audiencia en primer término el juez debe hacer una relación de los cargos que
aparecen en el informe policial o en la querella, acto seguido si se encuentra el agraviado pro
cederá a propiciar la conciliación y la celebración del acuerdo de la reparación si fuera el caso,
de darse la conciliación, el juez dará por concluida el proceso, homologando la conciliación o
el acuerdo. Si no se produce la conciliación la audiencia continuará, preguntando en primer
término al imputado si reconoce o no su culpabilidad, si admite la imputación se dará por
concluida el debate cuando no es necesaria la actuación de otros medios de prueba dictando
la sentencia en forma escrita o verbal, en este últim o caso, deberá ser protocolizado en docu
mento en el término de dos días.
