Tema 7: Especialidad Procesal Penal
De no darse los hipotéticos anteriores, entonces la audiencia se desarrollará en la forma si
guiente: a) Interrogatorio al imputado, b) Interrogatorio a la parte ofendida, c) Interrogatorio a
los testigos y peritos, d) Actuación de las demás pruebas. Todo con la brevedad y simpleza del
caso. La audiencia se desarrolla en una sola sesión,y únicamente puede suspenderse hasta por
tres días cuando hay la necesidad de actuar medios probatorios imprescindibles, y esta sus
pensión se puede dar de oficio por el juez o a petición de cualquiera de las partes. Concluido
este plazo sigue la secuela regular aunque haya testigos o peritos que falten declarar.
Las partes tienen derecho para form ular sus alegatos después de la actuación de los medios
probatorios, producido los alegatos o sin ella, el juez inmediatamente dictará la sentencia en
ese acto o dentro de 3 días después de haber culminado la audiencia. La sentencia es apelable
por cualquiera de las partes ante el mismo juez, quien elevará los autos al juez penal especia
lizado, la que resolverá en últim a instancia la apelada, en el plazo improrrogable de 10 días
cuando no hay solicitud concreta de actuación de medios probatorios; caso contrario, es decir,
de haber solicitud de medios probatorios que actuar, el juez señalará vista de la causa dentro
del plazo de 20 días de recibida la apelación.
16. COOPERACIÓN JUDICIAL INTERNACIONAL
La cooperación judicial internacional, es una valiosa herramienta al alcance de los Estados en su
tarea de combatir el delito, perseguíry sancionar a sus autores o partícipes, con una utilidad ma
nifiesta, sobre todo cuando se trata de ilícitos penales de carácter transnacional, como el tráfico
ilícito de drogas, el lavado de activos, el terrorismo, la trata de personas, la corrupción de funcio
narios, entre otros, en cuya ejecución como en las tareas de esconder las ilícitas ganancias obte-
nidasyen la de evadir la acción de la justicia, las fronteras no constituyen un límite invencible.
De allí que resulta imperiosa la “...necesidad de articular instrumentos de cooperación internacional
en materia penal mediante la figura de la extradición -entre otras-como una de las instituciones desti
nadas a e vita rla im punidad en caso de delitos cuya promoción, materialización y /o resultado implica a
más de un Estado" (Expediente N° 7624''2005/TC).
Precisamente, debido a esta necesidad y como una clara expresión del fenómeno de la glo
bal ización, los Estados asumen compromisos de cooperación que se materializan en tratados
multilaterales o bilaterales, mientras que en sus legislaciones internas van incluyendo normas
cada vez más precisas, para hacer de la cooperación judicial internacional un mecanismo de
ayuda mutua o recíproca más expeditiva.
En esa línea, nuestro legislador, reconociendo la importancia de lo que podría denominarse
como “derecho procesal penal internacional", como instrumento del instrumento que posibi
lita la aplicación del derecho penal material, ha destinado el Libro Sétimo del nuevo Código
Procesal Penal a la cooperación judicial internacional.
Una de las novedades más saltantes de este cuerpo legal es la designación de la Fiscalía de la
Nación como autoridad central (artículo 512), que actúa como ente emisory transmisor de los
actos de cooperación judicial internacional previstos en el CPP: la extradición (artículos 513 al
527), la solicitud de asistencia judicial internacional (artículos 528 al 537), el traslado de con
denados (artículos 540 al 549) y la entrega vigilada de bienes delictivos (artículos 550 al 553).
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1210 of 1506 --

El CPP trae asimismo disposiciones relativas a la cooperación con la Corte Penal Internacional
(artículos 554 a 566) -en observancia del artículo 88 del Estatuto de Roma-y a la práctica de
diligenciasen otros Estados por juecesy fiscales nacionales y extranjeros (artículos 538 y 589).
a) La extradición: La extradición es una institución Mixta Jurídicay Política,y queasuvezen
el plano estrictamente jurídico también es híbrida, al pertenecery estar influenciada por
tres disciplinas jurídicas distintas: el Derecho Internacional, el Derecho Penaly el Derecho
Procesal Penal.
La extradición sirve al derecho procesal, pues se caracteriza por ser un instrumento del proceso
penal, bien respecto a la actividad de declaración, en los supuestos de extradición de imputa
dos, bien respecto a la actividad de ejecución, en los casos de extradición de condenados.
Según Huapaya Olivares, existen en la extradición los elementos siguientes:
Básicos.- En donde existe un Estado requirente o solicitante, que es el Estado perju
dicado con la acción delictiva y cuyo probable responsable ha huido o se encuentra
fuera de su jurisdicción. El estado requerido, que es aquel en cuyo territorio se en
cuentra la persona sometida a proceso o condenada por un delito cometido en otro
Estadoy por últim o el Extraditable, presunto infractor de la ley penal o el sancionado
en juicio por estos hechos y cuya acreencia es reclamada para fines de proceso o de
ejecución de sentencia.
Complementarios.- Pues existe un acto de cooperación soberano entre Estados a
efectos de facilitar la entrega del imputado, ya sea para que sea sometido a un pro
ceso o ejecución de condena, por un delito com etidoy que se encuentra físicamente
dentro de la jurisdicción del Estado requerido, la misma que es solicitado en aten
ción a un tratado o en aplicación del principio de reciprocidad.
Los delitos materia de extradición, son todos aquellos que no tengan naturaleza política,
por tanto, un apersona puede ser extraditada, por haber cometido un ilícito que sea ma
teria de sanción o posible sanción penal.
Su procedencia está regulada en el artículo 413 del CPRel primer numeral de este artículo
establece que la persona procesada, acusada o condenada como autor o partícipe que
se encuentra en otro Estado, puede ser extraditada a fin de ser juzgada o de cumplir la
sanción penal que le haya sido impuesta como acusada presente.
El segundo numeral trata sobre la oferta, convenio o declaración de reciprocidad, que se
aplica cuando no existe tratado o cuando el delito no está previsto en el tratado, debien
do en estos casos aplicarse el artículo 647 de la Ley de Extradición.
Clases:
En el Nuevo Código Procesal Penal se contempla dos clases de extradición:
i. Extradición pasiva (art. 516 CPP): La extradición pasiva es un acto por el que, las auto
ridades de un Estado hacen entrega a las de otro, previa la correspondiente solicitud, de
una persona imputada o condenada por la comisión de infracciones penales, que se en
cuentra en el espacio físico del primero, para que el Estado requirente la juzgue o haga
cumplir la condena impuesta.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCION
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1211 of 1506 --

Tema 7: Especialidad Procesal Penal
R e ch azo d e ia e x tra d ic ió n (a r t. 517 C PP):
1. No procede la extradición si el hecho materia del proceso no constituye delito tanto en el
Estado requirentecomoen el Perú,y si en ambas legislaciones no tenga prevista una con
minación penal, en cualquiera de sus extremos, igual o superior a una pena privativa de
un año. Si se requiere una extradición por varios delitos, bastará que uno de ellos cumpla
con esa condición para que proceda respecto de los restantes delitos.
2. La extradición no tendrá lugar, igualmente:
a) Si el Estado solicitante no tuviera jurisdicción o competencia para juzgar el delito;
b) Si el extraditado ya hubiera sido absuelto, condenado, indultado, amnistiado o suje
to a otro derecho de gracia equivalente;
c) Si hubiera transcurrido el término de la prescripción del delito o de la pena, confor
me a la Ley nacional o del Estado requirente, siempre que no sobrepase el término
de la legislación peruana;
d) Si el extraditado hubiere de responder en el Estado requirente ante tribunal de ex
cepción o el proceso al que se le va a someter no cumple las exigencias internaciona
les del debido proceso;
e) Si el delito fuere exclusivamente militar, contra la religión, político o conexo con él,
de prensa, o de opinión. La circunstancia de que la víctima del hecho punible de que
se trata ejerciera funciones públicas, no justifica por sí sola que dicho delito sea cali
ficado como político. Tampoco politiza el hecho de que el extraditado ejerciere fun
ciones políticas. De igual manera están fuera de la consideración de delitos políticos,
los actos de terrorismo, los delitos contra la humanidad y los delitos respecto de los
cuales el Perú hubiera asumido una obligación convencional internacional de extra
ditar o enjuiciar;
f) Si el delito es perseguible a instancia de partey si se trata de una falta; y,
g) Si el delito fuere tributario, salvo que se cometa por una declaración intencional
mente falsa, o por una omisión intencional, con el objeto de ocultar ingresos prove
nientes de cualquier otro delito.
3. Tampoco se dispondrá la extradición, cuando:
i. La demanda de extradición motivada por una infracción de derecho común ha sido
presentada con el fin de perseguir o de castigar a un individuo por consideraciones
de raza, religión, nacionalidad o de opiniones políticas o que la situación del extradi
tado se exponga a agravarse por una u otra de estas razones;
ii. Existan especiales razones de soberanía nacional, seguridad u orden público u otros
intereses esenciales del Perú, que tornen inconveniente el acogimiento del pedido;
iii. El Estado requirente no diere seguridades de que se computará el tiempo de priva
ción de libertad que demande el trámite de extradición, así como el tiempo que el
extraditado hubiese sufrido en el curso del proceso que motivó el requerimiento.
iv. El delito por el que se solicita la extradición tuviere pena de muerte en el Estado re-
quirentey éste no diere seguridades de que no será aplicable.
BALOTAR 10 DESARROLLADO PARA LOS EXAMENES ESCRITOS DESELECCION
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 1212 of 1506 --

íí. Extradición activa (art. 525 CPP): La extradición activa es el acto en virtud del cual el Estado
Peruano solicita a otro Estado la entrega de una persona, a la que se le atribuye la comisión de
un hecho punible, a fin de que sea juzgada, o si ya lo fue y resultó condenada, para tratar que
cumpla su sentencia en territorio nacional. Gimeno Sendra, la conceptúa como el conjunto
de actuaciones ordenadas legalmente que han de seguirse para solicitar la entrega de una
persona imputada penalmente al Estado extranjero donde se encuentra, con la finalidad de
que pueda responder de los hechos delictivos que se le imputa o, en su caso de que cumpla en
el territorio del Estado que la reclama la pena o medida de seguridad que se la haya impuesto.
17. ASISTENCIA JUDICIAL INTERNACIONAL
Es el mecanismo mediante el cual un Estado solicita a otro, la actuación de diligencias dentro
del territorio extranjero, para obtener información o documentación que permita esclarecer
las investigaciones o procesos penales que se encuentran en giro, las mismas que se llevarán a
cabo bajo las reglas procesales del Estado requerido.
La solicitud de asistencia judicial internacional o carta rogatoria sólo procederá cuando la
pena privativa de libertad para el delito investigado o juzgado no sea menor de un año y siem
pre que no se trate de delito sujeto exclusivamente a la legislación militar. (Art. 528 NCPP).
Trámite de las solicitudes.-
1. La Fiscalía de la Nación cursará las solicitudes de asistencia de las autoridades extranje
ras al Juez de la Investigación Preparatoria del lugar donde deba realizarse la diligencia,
quien en el plazo de dos días, decidirá acerca de la procedencia de la referida solicitud.
2. Contra la resolución del Juez de la Investigación Preparatoria procede recurso de apela
ción sin efecto suspensivo. La Sala Penal Superior correrá traslado de lo actuado al Fiscal
Superiory a los interesados debidamente apersonados por el plazo común de tres días, y
resolverá, previa vista de la causa, en el plazo de cinco días.
3. En el trám ite de ejecución del acto de asistencia judicial intervendrá el Ministerio Público
y se citará a la Embajada del país solicitante para que se haga representar por un Aboga
do. También se aceptará la intervención de los abogados de quienes resulten ser partes
en el proceso del que derive la carta rogatoria.
4. Sin perjuicio de lo anterior, en todo lo referente a las condiciones y formas de realización
del acto de asistencia, rige la legislación nacional.
5. Corresponde actuar la diligencia de asistencia judicial al propio Juez de la Investigación
Preparatoria. Luego de ejecutarla, elevará las actuaciones a la Fiscalía de la Nación para su
remisión a la autoridad requirente por intermedio del Ministerio de Relaciones Exteriores.
