BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 1213

-- 1214 of 1506 --

UBILEX
Lo contencioso administrativo tiene por finalidad ejercer control sobre las actuaciones u om i
siones de la Administración Pública, por lo tanto, el ejercicio de este control garantiza a los
Ciudadanos la defensa de sus derechos e intereses legítimos, actualmente, encontramos dos
sistemas de lo contencioso administrativo:
1. PRINCIPIOS ESPECIALES DEL CONTENCIOSO ADMINISTRATIVO
Estos principios son de observancia obligatoria para el proceso contencioso administrativo,
en tanto su aplicación garantizará el derecho de reclamar por parte de los administrados el
control jurídico de las actuaciones administrativas que les afectan, sin perjuicio que el Estado
pretenda verificar a través de este proceso la legalidad por afectación del interés público de
sus propios actos administrativos. Estos principios especiales son-,
1. Principio de integración. Artículo 139, inciso 8 , de la Constitución Política del Estado esta
blece que “Son principios y derechos de ¡a función jurisdiccional”: “8 . El principio de no dejar de admi
nistrar justicia por vacío o deficiencia de la ley. En tal caso, deben aplicarse los principios generales del
derechoyel derecho consuetudinario.” De esta manera, el principio especial de integración en el
proceso contencioso administrativo es una expresión del principio de no dejar de administrar
justicia por vacía o deficiencia de la ley previsto en la Constitución.
2. Principiodeigualdadprocesal. Principio procesal que implicaque todos los litigantes tengan las
mismas oportunidades de actuación dentro del proceso, sin que ninguno se encuentre en posición
de inferioridad respecto de los demás285. Las partes en el proceso contencioso administrativo son las
Entidades Públicas y los Administrados, ambas pueden ser demandantes o demandados.
3. Principio de favorecimiento del proceso. El principio de favorecimiento al proceso no tie
ne como propósito dejar sin efecto los distintos requisitos previstos en la propia ley para el
ejercicio de la acción contenciosa administrativa, por el contrario, tiene como propósito ser
empleado como un medio para maximizarlo en los casos en los que pudieran generarse du
das fundadas sobre su aplicación, dando prioridad a la búsqueda de los fines previstos en el
artículo 1 del Texto Único Ordenado de la Ley 27584 (el control jurídico por el Poder Judicial
de las actuaciones de la administración pública sujetas al derecho administrativo y la efectiva
tutela de los derechos e intereses de los administrados)286. Por otro lado, el principio de favo
recimiento del proceso no puede ser empleado como instrumento para defraudar el marco
previsto legalmente para regular la procedencia de la acción contenciosa administrativa, sino
como un medio para maximizarlo por encima de las dudas razonables que pudiera mantener
el juzgador sobre la procedencia de la demanda287.
4. Principio de suplencia de oficio. El juez no sólo debe atender las demandas con celeridad,
sino, que sobre todo debe suplir las deficiencias formales en las que incurran las partes, sin
perjuicio de disponer la subsanación de las mismas en un plazo razonable en los casos en
285 Diccionario del Español Jurídico.
