Tema de Contencioso Adm inistrativo
que no sea posible la suplencia de oficio, conforme así lo prevé el numeral 4) del artículo 2
del TUO de la Ley 27584288. Conforme a esto, se verificará la lesión al contenido esencial de
la garantía constitucional del debido proceso legal y la tutela jurisdiccional, si se desestima
la demanda bajo el argumento que el demandante viene impugnando actos administrativos
que no causan estado, sin tom aren consideración los principios de favorecí miento del proceso
y suplencia de oficio establecidos en el artículo 2 numerales 3 y 4 del TUO de la Ley 27584, y
la concepción de plena jurisdicción que caracteriza al proceso contencioso administrativo289.
i!. ACTUACIONES IMPUGNABLES
Son actuaciones impugnables en el proceso contencioso administrativo.
1. Los actos administrativos y cualquier declaración administrativa. Cuando halamos de
acto administrativo nos referimos a aquella manifestación unilateral de voluntad emitida
en el marco de las normas de derecho público que emiten las entidades públicas, como
es el caso de la Resoluciones Administrativas (esto no excluye que la Administración Pú
blica contenga sus actos administrativos en cartas, oficios, memorandos).
2. El silencio administrativo. Cuando los administrados hacen uso de su derecho de petición
a través de una solicitud, estos deben de esperar que venza el plazo legal para la emisión
de un acto administrativo, cuando este plazo vence es derecho de los administrados hacer
uso del silencio administrativo que es un mecanismo de favorecer, recurrir o impugnar la
inacción de la administración pública; este silencio puede ser positivo o negativo, en el caso
que se entienda que el silencio es positivo se entiende que existe una resolución ficta que
aprueba el pedido del administrado, siendo posible en estos casos exigir el cumplimiento
en lo contencioso de esta resolución ficta (proceso contencioso administrativo de cumpli
miento); cuando el silencio es negativo se entiende que el pedido realizado ha sido negado,
por lo que se posibilita que el administrado lo recurra a través de los recursos adm inistrati
vos o, en su caso, la demanda contencioso administrativa, en el caso del silencio negativo no
existe una resolución ficta, pensaresto implicaría otorgar lacargaal administrado de probar
la nulidad de un acto inexistente. El silencio administrativo negativo no inicia el cómputo de
plazos administrativosy judiciales para su impugnación.
3. Inercia de la administración pública. La pretensión contenida en el inciso 4) del artículo
5 del TUO de la Ley 27584, puede ser planteada ante la omisión o inercia de la Adminis
tración, tiene por objeto la realización del acto debido, y se tram ita en el proceso conten
cioso administrativo, siempre que el interesado previamente haya reclamado por escrito
ante el titu lar de la entidad, el cumplimiento de la actuación om itida290. La omisión en la
resolución de una solicitud derivada del derecho de petición acarrea el silencio adminis
trativo, por otro lado, cuando la Administración Pública es renuente a cum plir con una
ley, reglamento o acto administrativo, es posible requerirla para que cumpla con realizar
la actuación a la que se encuentra obligada por mandato de la ley, reglamento o acto
