administrativo; esto puede denominarse proceso contencioso administrativo de cum
plimiento. En efecto, conforme al principio de legalidad las autoridades administrativas
están obligadas al cumplimiento de la ley, reglamento o acto administrativo, razón por la
cual su incumplimiento deriva en una omisión administrativa pasible de control jurídico
a través de lo contencioso administrativo.
4. Actuaciones materiales no sustentadas en acto administrativo. El acceso a la vía con
tenciosa administrativa no requiere necesariamente la existencia de un acto adminis
trativo o resolución formalmente dictada por la Administración, dado que el TUO de la
Ley 27584 reconoce claramente como una de las actuaciones que posibilitan el ingreso al
contencioso administrativo a la actuación material que no se sustenta en acto adminis
trativo291. Los actos de ejecución o efectividad de un acto administrativo derivan en actua
ciones materiales (vías de hecho) que son los actos que realiza la administración pública
para ejecutar un acto administrativo; cuando se realiza una actuación material sin contar
con un acto administrativo previo que la valide se entiende que esta actuación material
es contraria al ordenamiento jurídico, por ejemplo, cuando se realiza un recojo de escom
bros del frente de una casa, sin que exista una resolución previa que lo autorice.
5. Actuaciones materiales de exceso o abuso de poder. También puede acontecer que se
realiza una actuación material sustentada en acto administrativo, sin embargo, la realiza
ción de la actuación material constituye un exceso, abuso o desvío de poder, esto es, que
la autoridad administrativa comete un exceso en las funciones conferidas por ley, abusa
de sus facultades o lejos de direccionar sus facultades la usa para otro fin; por ejemplo,
cuando se dispone el descerraje de un local, sin embargo, cuando se ingresa al local se
produce un exceso al disponer el depósito de todos los bienes ubicados en el local.
6. Contratos administrativos. El acto administrativo es una declaración unilateral de volun
tad de la Administración Pública, sin embargo, cuando además de la voluntad del Estado
participa la voluntad del particular estamos ante los contratos administrativos o públicos,
generalmente estos contratos serán para la contratación de servicios o contratación de
obras. Firmado un contrato administrativo es posible que surjan problemas en su efica
cia, aplicación o interpretación por lo que puede usarse el proceso contencioso adminis
trativo para dilucidar estos problemas, salvo que en el contrato se haya acordado recurrir
previamente a un proceso de conciliación o un proceso arbitral, en estos casos, se excluye
el proceso judicial contencioso administrativo.
7. Actuaciones sobre el personal que presta servicios a favor del estado. Esta actuación se
refiere al empleo público, función pública o servicio civil, esto es, al personal que presta
servicios de manera subordinada a favor de la Administración Pública, en estos casos, lo
contencioso administrativo sería el proceso ideal para la defensa y protección de dere-
chosy beneficios laborales, será de protección el derecho individual del empleo públicoy
el derecho colectivo del empleo público (sindicación, negociación colectiva y huelga). En
este punto también se incluyen las indemnizaciones afavorde los servidores públicos o a
favor de las entidades públicas. Por ejemplo, las actividades desempeñadas como Jefe de
